insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (404, 58, 1, 10, 'سورة المجادلة ١ – ١٠', 'المجادلة: قد سمع الله قول التي تجادلك', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 404) = $j$[{"lbl": "الآيات ١ – ٤", "q": "قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ ﴿١﴾ ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّـٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ ﴿٢﴾ وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٣﴾ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ ﴿٤﴾", "w": [["قد سمع الله قول التي تجادلك في زوجها", "التي تراجعك أيها النبي في شأن زوجها أوس بن الصامت."], ["وتشتكي إلى الله", "وحدتها وفاقتها، وصبية صغاراً إن ضمّتهم إليه ضاعوا، وإن ضمّتهم إليها جاعوا."], ["والله يسمع تحاوركما", "تراجعكما: أنت أيها الرسول، والمحاورة لك وهي خولة."], ["إن الله سميع بصير", "سميع لأقوالكما، بصير بأحوالكما."], ["الذين يظاهرون منكم من نسائهم", "يحرّمون نساءهم بقول: أنتِ عليّ كظهر أمي."], ["ما هنّ أمهاتهم", "ليس هنّ بأمهاتهم."], ["إن أمهاتهم إلا اللائي ولدنهم", "ما أمهاتهم إلا اللائي ولدنهم."], ["وإنهم ليقولون منكراً من القول وزوراً", "وإنهم بالظهار ليقولون منكراً من القول وكذباً."], ["وإن الله لعفوّ غفور", "ذو صفح عن عباده، غفور لذنوبهم إن تابوا."], ["ثم يعودون لما قالوا", "يعزمون على العودة للتي ظاهروا منها، إذ كان الظهار في الجاهلية طلاقاً."], ["فتحرير رقبة من قبل أن يتماسّا", "فالواجب عليه تحرير رقبة مؤمنة قبل أن يجامعها."], ["ذلكم توعظون به", "تؤمرون به فافعلوه على سبيل الوجوب."], ["فمن لم يجد فصيام شهرين متتابعين", "فمن لم يجد الرقبة لانعدامها أو غلاء ثمنها فالواجب صيام شهرين متتابعين قبل الوطء."], ["فمن لم يستطع", "الصيام لمرض أو كبر سن."], ["فإطعام ستين مسكيناً", "فعليه قبل الوطء أن يطعم ستين مسكيناً، لكل مسكين مدّ من بُرّ، أو مدّان من غيره من غالب قوت أهل البلد."], ["ذلك لتؤمنوا بالله ورسوله", "ما تقدّم من بيان حكم الظهار شرعه لكم لتؤمنوا، لأن الطاعة إيمان والمعصية من الكفران."], ["وتلك حدود الله", "أحكام شرعه."], ["وللكافرين عذاب أليم", "وللكافرين بها الجاحدين لها عذاب ذو ألم."]], "m": "نزلت هذه الآية في خولة بنت ثعلبة الأنصارية وزوجها أوس بن الصامت أخي عبادة بن الصامت رضي الله عنهم؛ كان قد ظاهر منها فقال لها في غضب: أنتِ عليّ كظهر أمي، وكان الظهار يومئذ طلاقاً، وكانت المرأة ذات أطفال صغار وقد تقدّم بها وبزوجها السن، فجاءت رسول الله ﷺ تشكو إليه ضعفها وضعف زوجها وضعف أطفالها، وما زالت تراجعه حتى نزلت هذه الآيات الأربع من فاتحة سورة المجادلة التي سُمّيت بها. قد سمع الله قول المرأة التي تراجعك في شأن زوجها، وتشتكي إلى الله ضعف حالها بعد أن قلت لها: والله ما أُمرت في شأنك بشيء، والله يسمع مراجعتكما، إن الله سميع لأقوال عباده بصير بأحوالهم. وهذا حكم الظهار: أولاً: أن قول الرجل لامرأته أنتِ عليّ كظهر أمي لا يجعلها أماً له، إذ أمه هي التي ولدته. ثانياً: هذا القول كذب وزور ومنكر، وقائله آثم فليتب إلى الله ويستغفره. ثالثاً: لولا عفو الله ومغفرته للتائبين لعاقبهم على هذا القول. رابعاً: الذين يظاهرون من نسائهم ثم يعزمون على وطئها فالواجب عليهم قبل الوطء تحرير رقبة مؤمنة، فمن لم يجدها فصيام شهرين متتابعين، فإن لم يستطع لعلة قامت به فإطعام ستين مسكيناً، كل ذلك من قبل أن يتماسّا. ذلك الذي تقدّم شرعه لكم لتؤمنوا بالله ورسوله، إذ الإيمان اعتقاد وقول وعمل، فطاعة الله ورسوله إيمان ومعصيتهما من الكفران. وتلك حدود الله فلا تعتدوها، وللكافرين بها المتعدّين لها عذاب أليم.", "h": ["إجابة الله لأوليائه بتفريج كروبهم وقضاء حوائجهم، فله الحمد وله الشكر.", "حرمة الظهار باعتباره منكراً وكذباً وزوراً، فتجب التوبة منه.", "بيان حكم المظاهر: عليه عتق رقبة قبل أن يجامع امرأته المظاهر منها، فإن لم يجد الرقبة المؤمنة صام شهرين متتابعين من الهلال إلى الهلال، وإذا انقطع التتابع لمرض بنى على ما صامه، فإن لم يستطع لمرض ونحوه أطعم ستين مسكيناً، فأعطى لكل مسكين على حدة مدّاً من بُرّ أو مدّين من غير البُرّ كالشعير والتمر.", "لو جامع المظاهر قبل إخراج الكفارة أثم، فليستغفر ربه وليخرج كفارته ولا شيء عليه غيرها، لحديث الترمذي الصحيح.", "طاعة الله ورسوله إيمان، ومعصية الله ورسوله من الكفران."], "k": "«قد سمع الله قول التي تجادلك… وتشتكي إلى الله»… شكوى امرأة ضعيفة نزل فيها قرآن؛ فلماذا أتردد أن أشكو إليه همّي؟"}, {"lbl": "الآيات ٥ – ٧", "q": "إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۭ بَيِّنَٰتٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ ﴿٥﴾ يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿٦﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿٧﴾", "w": [["إن الذين يحادّون الله ورسوله", "يخالفون الله ورسوله ويعادونهما."], ["كُبتوا كما كُبت الذين من قبلهم", "ذُلّوا وأُهينوا كما ذُلّ وأُهين من قبلهم لمخالفتهم رسلهم."], ["وقد أنزلنا آيات بيّنات", "والحال أنّا قد أنزلنا آيات واضحات دالة على صدق الرسول."], ["وللكافرين عذاب مهين", "عذاب يوقعهم في الذل والهوان."], ["يوم يبعثهم الله جميعاً", "يوم القيامة."], ["أحصاه الله ونسوه", "جمعه وعدّه، ونسوه هم."], ["والله على كل شيء شهيد", "لا يغيب عنه شيء من الأشياء."], ["ما يكون من نجوى ثلاثة إلا هو رابعهم", "ما يكون من متناجين ثلاثة إلا هو تعالى رابعهم بعلمه بهم وقدرته عليهم."], ["ولا أدنى من ذلك", "أقل من الثلاثة، وهما الاثنان."], ["إلا هو معهم أين ما كانوا", "في أي مكان من الأرض أو السماء."]], "m": "هذه الآية تحمل بشرى لرسول الله ﷺ بهزيمة قريش وهي تحزّب الأحزاب لحربه في غزوة الخندق: إن الذين يخالفون الله ورسوله ويعادونهما أُذلّوا وأُهينوا كما أُذلّ الذين من قبلهم ممن كذّبوا رسلهم، وقد أنزلنا آيات بيّنات كلها دالة على صدق رسولنا، ومع هذا عادوه وحاربوه، فلهذا يكبتهم الله في الدنيا، وللكافرين أمثالهم عذاب مهين يوم القيامة، يوم يبعثهم الله جميعاً لا يتخلّف منهم أحد، فينبّئهم بما عملوا من الشر والفساد، أحصاه الله إذ كتبته ملائكته وكُتب قبل فعلهم له في اللوح المحفوظ، ونسوه لعمى قلوبهم وكفرهم بربهم ولقائه، والله على كل شيء شهيد، فلا يقع شيء إلا تحت بصره. ألم تعلم يا رسولنا أن الله يعلم ما في السماوات وما في الأرض من دقيق الأشياء وجليلها؟ ورد أن جماعة من المنافقين كانوا يتناجون بينهم إغاظة للمؤمنين، فنزلت هذه الآية تعرّض بهم: ما يكون من متناجين ثلاثة إلا والله رابعهم بعلمه بهم وقدرته عليهم، وهذه فائدة المعيّة: العلم والقدرة على الأخذ والعطاء، ولا خمسة إلا هو سادسهم، ولا أدنى من ذلك ولا أكثر إلا هو معهم بعلمه وقدرته أينما كانوا، ثم يخبرهم بما عملوا يوم القيامة ليجزيهم به، إن الله بكل شيء عليم.", "h": ["وعيد الله الشديد بالكبت والذل والهوان لكل من يحادّ الله ورسوله.", "إحاطة علم الله بكل شيء، وشهوده لكل شيء، وإحصاؤه لكل أعمال العباد؛ حال توجب مراقبة الله تعالى والخشية منه والحياء منه أشد الحياء.", "الإرشاد إلى أن التناجي للمشاورة في الخير ينبغي أن يكون عدد المتناجين فيه ثلاثة أو خمسة أو سبعة، ليكون الواحد عدلاً مرجّحاً للخلاف قاضياً فيه."], "k": "«أحصاه الله ونسوه»… أنسى ذنوبي وهي محصاة عنده؛ فلأذكرها اليوم وأستغفر قبل أن أُنبَّأ بها."}, {"lbl": "الآيات ٨ – ١٠", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نُهُواْ عَنِ ٱلنَّجۡوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنۡهُ وَيَتَنَٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِۖ وَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ لَوۡلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ يَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِيرُ ﴿٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوۡاْ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٩﴾ إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ وَلَيۡسَ بِضَآرِّهِمۡ شَيۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٠﴾", "w": [["ألم تر إلى الذين نُهوا عن النجوى", "عن المسارّة الكلامية، والمنهيّون هم اليهود والمنافقون."], ["ثم يعودون لما نُهوا عنه", "من التناجي تعمّداً لأذية المؤمنين بالمدينة."], ["ويتناجون بالإثم والعدوان", "بما هو إثم في نفسه، وعداوة الرسول والمؤمنين."], ["ومعصية الرسول", "يوصي بعضهم بعضاً بمعصية الرسول وعدم طاعته."], ["وإذا جاؤوك حيّوك بما لم يحيّك به الله", "حيّوك بلفظ: السام عليك، والله حيّاه بلفظ: السلام عليك أيها النبي ورحمة الله وبركاته."], ["ويقولون في أنفسهم", "سرّاً فيما بينهم."], ["لولا يعذّبنا الله بما نقول", "هلّا يعذّبنا الله بما نقول له، فلو كان نبياً لعاجلنا الله بالعذاب."], ["حسبهم جهنم يصلونها", "يكفيهم عذاب جهنم يصلونها، فبئس المصير لهم."], ["فلا تتناجوا بالإثم والعدوان", "فلا يناجِ بعضكم بعضاً بما هو إثم، ولا بما هو عدوان وظلم، ولا بما هو معصية للرسول."], ["وتناجوا بالبر والتقوى", "وتناجوا إن أردتم ذلك بالخير وطاعة الله ورسوله."], ["إنما النجوى من الشيطان", "إنما النجوى بالإثم والعدوان من الشيطان، بتغريره."], ["ليحزن الذين آمنوا", "ليوهمهم أنها بسبب شيء وقع مما يؤذيهم."], ["وليس بضارّهم شيئاً إلا بإذن الله", "وليس التناجي بضارّ المؤمنين شيئاً إلا بإرادة الله تعالى."], ["وعلى الله فليتوكّل المؤمنون", "وعلى الله لا على غيره يجب أن يتوكّل المؤمنون."]], "m": "نزلت هذه الآية في يهود المدينة والمنافقين، إذ كانوا يتحدّثون سرّاً على مرأى من المؤمنين، والوقت وقت حرب، فيوهمون المؤمنين أن عدواً قد عزم على غزوهم، أو أن سرية هُزمت، أو أن مؤامرة تُحاك ضدهم، فنهاهم رسول الله ﷺ عن التناجي، فأبوا إلا أن يتناجوا، فأنزل الله هذه الآية يعجّب رسوله منهم ويتوعّدهم: ألم تر إلى الذين نُهوا عن النجوى ثم يعودون لما نُهوا عنه عصياناً وتمرّداً، ويتناجون بالإثم كالغيبة والبذاء، وبالعدوان على المؤمنين وظلمهم، وبمعصية الرسول. وإذا جاؤوك حيّوك بما لم يحيّك به الله، يقولون: السام عليكم، والسام الموت، يلوون بها ألسنتهم، ويقولون فيما بينهم: لو كان محمد نبياً لأخذنا الله بما نقول له من الدعاء عليه بالموت. قال تعالى: حسبهم عذاباً جهنم يصلونها يحترقون بحرّها يوم القيامة، فبئس المصير. ثم قال في تربية المؤمنين روحياً وتهذيبهم أخلاقياً: يا أيها الذين آمنوا إذا تناجيتم لأمر استدعى ذلك فلا تتناجوا بالإثم والعدوان ومعصية الرسول فتكون حالكم كحال اليهود والمنافقين، ولكن تناجوا بما هو خير لا إثم فيه، وبطاعة الله ورسوله، واتقوا الله الذي إليه تُحشرون. إنما النجوى من الشيطان، هو الدافع إليها، ليوقع المؤمنين في غمّ وحزن، وليس التناجي ولا الشيطان بضارّ المؤمنين شيئاً إلا بإرادة الله لحِكم يعلمها، فلا تحزنوا لما ترون من تناجي أعدائكم، وتوكّلوا على الله في أموركم كلها، فإنه كافٍ من يتوكّل عليه كل ما يهمّه.", "h": ["بيان مكر اليهود والمنافقين وكيدهم للمؤمنين في كل زمان ومكان.", "إذا حيّا الكافر المؤمن، ردّ عليه المؤمن بقوله: وعليكم؛ لما صحّ أن النبي ﷺ دخل عليه ناس من اليهود فقالوا: السام عليك يا أبا القاسم، فقال ﷺ: «وعليكم»، فقالت عائشة رضي الله عنها: عليكم السام ولعنكم الله وغضب عليكم، فقال لها ﷺ: «يا عائشة، عليك بالرفق، وإياك والعنف والفحش»، فقالت: ألا تسمعهم يقولون السام؟ فقال لها: «أوما سمعتِ ما أقول: وعليكم». رواه الشيخان.", "إذا سلّم الذميّ وكان سلامه بلفظ: السلام عليكم، لا بأس أن يُردّ عليه بلفظه.", "حرمة التناجي بغير البر والتقوى، لقوله تعالى: «إلا من أمر بصدقة أو معروف أو إصلاح بين الناس» من سورة النساء.", "لا يجوز أن يتناجى اثنان دون الثالث، لما يوقع ذلك في نفس الثالث من حزن، لا سيما إن كان ذلك في سفر أو في حرب.", "وجوب التوكّل على الله، وترك الأوهام والوساوس فإنها من الشيطان."], "k": "«وتناجوا بالبر والتقوى»… حين أهمس لأحد، هل أهمس بخير أم بما يُحزن غائباً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 404;
insert into public.tdb_cards(topic, i, body) select 404, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ ﴿١﴾ ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّـٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ ﴿٢﴾ وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٣﴾ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ ﴿٤﴾", "w": [["قد سمع الله قول التي تجادلك في زوجها", "التي تراجعك أيها النبي في شأن زوجها أوس بن الصامت."], ["وتشتكي إلى الله", "وحدتها وفاقتها، وصبية صغاراً إن ضمّتهم إليه ضاعوا، وإن ضمّتهم إليها جاعوا."], ["والله يسمع تحاوركما", "تراجعكما: أنت أيها الرسول، والمحاورة لك وهي خولة."], ["إن الله سميع بصير", "سميع لأقوالكما، بصير بأحوالكما."], ["الذين يظاهرون منكم من نسائهم", "يحرّمون نساءهم بقول: أنتِ عليّ كظهر أمي."], ["ما هنّ أمهاتهم", "ليس هنّ بأمهاتهم."], ["إن أمهاتهم إلا اللائي ولدنهم", "ما أمهاتهم إلا اللائي ولدنهم."], ["وإنهم ليقولون منكراً من القول وزوراً", "وإنهم بالظهار ليقولون منكراً من القول وكذباً."], ["وإن الله لعفوّ غفور", "ذو صفح عن عباده، غفور لذنوبهم إن تابوا."], ["ثم يعودون لما قالوا", "يعزمون على العودة للتي ظاهروا منها، إذ كان الظهار في الجاهلية طلاقاً."], ["فتحرير رقبة من قبل أن يتماسّا", "فالواجب عليه تحرير رقبة مؤمنة قبل أن يجامعها."], ["ذلكم توعظون به", "تؤمرون به فافعلوه على سبيل الوجوب."], ["فمن لم يجد فصيام شهرين متتابعين", "فمن لم يجد الرقبة لانعدامها أو غلاء ثمنها فالواجب صيام شهرين متتابعين قبل الوطء."], ["فمن لم يستطع", "الصيام لمرض أو كبر سن."], ["فإطعام ستين مسكيناً", "فعليه قبل الوطء أن يطعم ستين مسكيناً، لكل مسكين مدّ من بُرّ، أو مدّان من غيره من غالب قوت أهل البلد."], ["ذلك لتؤمنوا بالله ورسوله", "ما تقدّم من بيان حكم الظهار شرعه لكم لتؤمنوا، لأن الطاعة إيمان والمعصية من الكفران."], ["وتلك حدود الله", "أحكام شرعه."], ["وللكافرين عذاب أليم", "وللكافرين بها الجاحدين لها عذاب ذو ألم."]], "m": "نزلت هذه الآية في خولة بنت ثعلبة الأنصارية وزوجها أوس بن الصامت أخي عبادة بن الصامت رضي الله عنهم؛ كان قد ظاهر منها فقال لها في غضب: أنتِ عليّ كظهر أمي، وكان الظهار يومئذ طلاقاً، وكانت المرأة ذات أطفال صغار وقد تقدّم بها وبزوجها السن، فجاءت رسول الله ﷺ تشكو إليه ضعفها وضعف زوجها وضعف أطفالها، وما زالت تراجعه حتى نزلت هذه الآيات الأربع من فاتحة سورة المجادلة التي سُمّيت بها. قد سمع الله قول المرأة التي تراجعك في شأن زوجها، وتشتكي إلى الله ضعف حالها بعد أن قلت لها: والله ما أُمرت في شأنك بشيء، والله يسمع مراجعتكما، إن الله سميع لأقوال عباده بصير بأحوالهم. وهذا حكم الظهار: أولاً: أن قول الرجل لامرأته أنتِ عليّ كظهر أمي لا يجعلها أماً له، إذ أمه هي التي ولدته. ثانياً: هذا القول كذب وزور ومنكر، وقائله آثم فليتب إلى الله ويستغفره. ثالثاً: لولا عفو الله ومغفرته للتائبين لعاقبهم على هذا القول. رابعاً: الذين يظاهرون من نسائهم ثم يعزمون على وطئها فالواجب عليهم قبل الوطء تحرير رقبة مؤمنة، فمن لم يجدها فصيام شهرين متتابعين، فإن لم يستطع لعلة قامت به فإطعام ستين مسكيناً، كل ذلك من قبل أن يتماسّا. ذلك الذي تقدّم شرعه لكم لتؤمنوا بالله ورسوله، إذ الإيمان اعتقاد وقول وعمل، فطاعة الله ورسوله إيمان ومعصيتهما من الكفران. وتلك حدود الله فلا تعتدوها، وللكافرين بها المتعدّين لها عذاب أليم.", "h": ["إجابة الله لأوليائه بتفريج كروبهم وقضاء حوائجهم، فله الحمد وله الشكر.", "حرمة الظهار باعتباره منكراً وكذباً وزوراً، فتجب التوبة منه.", "بيان حكم المظاهر: عليه عتق رقبة قبل أن يجامع امرأته المظاهر منها، فإن لم يجد الرقبة المؤمنة صام شهرين متتابعين من الهلال إلى الهلال، وإذا انقطع التتابع لمرض بنى على ما صامه، فإن لم يستطع لمرض ونحوه أطعم ستين مسكيناً، فأعطى لكل مسكين على حدة مدّاً من بُرّ أو مدّين من غير البُرّ كالشعير والتمر.", "لو جامع المظاهر قبل إخراج الكفارة أثم، فليستغفر ربه وليخرج كفارته ولا شيء عليه غيرها، لحديث الترمذي الصحيح.", "طاعة الله ورسوله إيمان، ومعصية الله ورسوله من الكفران."], "k": "«قد سمع الله قول التي تجادلك… وتشتكي إلى الله»… شكوى امرأة ضعيفة نزل فيها قرآن؛ فلماذا أتردد أن أشكو إليه همّي؟"}, {"lbl": "الآيات ٥ – ٧", "q": "إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۭ بَيِّنَٰتٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ ﴿٥﴾ يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿٦﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿٧﴾", "w": [["إن الذين يحادّون الله ورسوله", "يخالفون الله ورسوله ويعادونهما."], ["كُبتوا كما كُبت الذين من قبلهم", "ذُلّوا وأُهينوا كما ذُلّ وأُهين من قبلهم لمخالفتهم رسلهم."], ["وقد أنزلنا آيات بيّنات", "والحال أنّا قد أنزلنا آيات واضحات دالة على صدق الرسول."], ["وللكافرين عذاب مهين", "عذاب يوقعهم في الذل والهوان."], ["يوم يبعثهم الله جميعاً", "يوم القيامة."], ["أحصاه الله ونسوه", "جمعه وعدّه، ونسوه هم."], ["والله على كل شيء شهيد", "لا يغيب عنه شيء من الأشياء."], ["ما يكون من نجوى ثلاثة إلا هو رابعهم", "ما يكون من متناجين ثلاثة إلا هو تعالى رابعهم بعلمه بهم وقدرته عليهم."], ["ولا أدنى من ذلك", "أقل من الثلاثة، وهما الاثنان."], ["إلا هو معهم أين ما كانوا", "في أي مكان من الأرض أو السماء."]], "m": "هذه الآية تحمل بشرى لرسول الله ﷺ بهزيمة قريش وهي تحزّب الأحزاب لحربه في غزوة الخندق: إن الذين يخالفون الله ورسوله ويعادونهما أُذلّوا وأُهينوا كما أُذلّ الذين من قبلهم ممن كذّبوا رسلهم، وقد أنزلنا آيات بيّنات كلها دالة على صدق رسولنا، ومع هذا عادوه وحاربوه، فلهذا يكبتهم الله في الدنيا، وللكافرين أمثالهم عذاب مهين يوم القيامة، يوم يبعثهم الله جميعاً لا يتخلّف منهم أحد، فينبّئهم بما عملوا من الشر والفساد، أحصاه الله إذ كتبته ملائكته وكُتب قبل فعلهم له في اللوح المحفوظ، ونسوه لعمى قلوبهم وكفرهم بربهم ولقائه، والله على كل شيء شهيد، فلا يقع شيء إلا تحت بصره. ألم تعلم يا رسولنا أن الله يعلم ما في السماوات وما في الأرض من دقيق الأشياء وجليلها؟ ورد أن جماعة من المنافقين كانوا يتناجون بينهم إغاظة للمؤمنين، فنزلت هذه الآية تعرّض بهم: ما يكون من متناجين ثلاثة إلا والله رابعهم بعلمه بهم وقدرته عليهم، وهذه فائدة المعيّة: العلم والقدرة على الأخذ والعطاء، ولا خمسة إلا هو سادسهم، ولا أدنى من ذلك ولا أكثر إلا هو معهم بعلمه وقدرته أينما كانوا، ثم يخبرهم بما عملوا يوم القيامة ليجزيهم به، إن الله بكل شيء عليم.", "h": ["وعيد الله الشديد بالكبت والذل والهوان لكل من يحادّ الله ورسوله.", "إحاطة علم الله بكل شيء، وشهوده لكل شيء، وإحصاؤه لكل أعمال العباد؛ حال توجب مراقبة الله تعالى والخشية منه والحياء منه أشد الحياء.", "الإرشاد إلى أن التناجي للمشاورة في الخير ينبغي أن يكون عدد المتناجين فيه ثلاثة أو خمسة أو سبعة، ليكون الواحد عدلاً مرجّحاً للخلاف قاضياً فيه."], "k": "«أحصاه الله ونسوه»… أنسى ذنوبي وهي محصاة عنده؛ فلأذكرها اليوم وأستغفر قبل أن أُنبَّأ بها."}, {"lbl": "الآيات ٨ – ١٠", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نُهُواْ عَنِ ٱلنَّجۡوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنۡهُ وَيَتَنَٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِۖ وَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ لَوۡلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ يَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِيرُ ﴿٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوۡاْ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٩﴾ إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ وَلَيۡسَ بِضَآرِّهِمۡ شَيۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٠﴾", "w": [["ألم تر إلى الذين نُهوا عن النجوى", "عن المسارّة الكلامية، والمنهيّون هم اليهود والمنافقون."], ["ثم يعودون لما نُهوا عنه", "من التناجي تعمّداً لأذية المؤمنين بالمدينة."], ["ويتناجون بالإثم والعدوان", "بما هو إثم في نفسه، وعداوة الرسول والمؤمنين."], ["ومعصية الرسول", "يوصي بعضهم بعضاً بمعصية الرسول وعدم طاعته."], ["وإذا جاؤوك حيّوك بما لم يحيّك به الله", "حيّوك بلفظ: السام عليك، والله حيّاه بلفظ: السلام عليك أيها النبي ورحمة الله وبركاته."], ["ويقولون في أنفسهم", "سرّاً فيما بينهم."], ["لولا يعذّبنا الله بما نقول", "هلّا يعذّبنا الله بما نقول له، فلو كان نبياً لعاجلنا الله بالعذاب."], ["حسبهم جهنم يصلونها", "يكفيهم عذاب جهنم يصلونها، فبئس المصير لهم."], ["فلا تتناجوا بالإثم والعدوان", "فلا يناجِ بعضكم بعضاً بما هو إثم، ولا بما هو عدوان وظلم، ولا بما هو معصية للرسول."], ["وتناجوا بالبر والتقوى", "وتناجوا إن أردتم ذلك بالخير وطاعة الله ورسوله."], ["إنما النجوى من الشيطان", "إنما النجوى بالإثم والعدوان من الشيطان، بتغريره."], ["ليحزن الذين آمنوا", "ليوهمهم أنها بسبب شيء وقع مما يؤذيهم."], ["وليس بضارّهم شيئاً إلا بإذن الله", "وليس التناجي بضارّ المؤمنين شيئاً إلا بإرادة الله تعالى."], ["وعلى الله فليتوكّل المؤمنون", "وعلى الله لا على غيره يجب أن يتوكّل المؤمنون."]], "m": "نزلت هذه الآية في يهود المدينة والمنافقين، إذ كانوا يتحدّثون سرّاً على مرأى من المؤمنين، والوقت وقت حرب، فيوهمون المؤمنين أن عدواً قد عزم على غزوهم، أو أن سرية هُزمت، أو أن مؤامرة تُحاك ضدهم، فنهاهم رسول الله ﷺ عن التناجي، فأبوا إلا أن يتناجوا، فأنزل الله هذه الآية يعجّب رسوله منهم ويتوعّدهم: ألم تر إلى الذين نُهوا عن النجوى ثم يعودون لما نُهوا عنه عصياناً وتمرّداً، ويتناجون بالإثم كالغيبة والبذاء، وبالعدوان على المؤمنين وظلمهم، وبمعصية الرسول. وإذا جاؤوك حيّوك بما لم يحيّك به الله، يقولون: السام عليكم، والسام الموت، يلوون بها ألسنتهم، ويقولون فيما بينهم: لو كان محمد نبياً لأخذنا الله بما نقول له من الدعاء عليه بالموت. قال تعالى: حسبهم عذاباً جهنم يصلونها يحترقون بحرّها يوم القيامة، فبئس المصير. ثم قال في تربية المؤمنين روحياً وتهذيبهم أخلاقياً: يا أيها الذين آمنوا إذا تناجيتم لأمر استدعى ذلك فلا تتناجوا بالإثم والعدوان ومعصية الرسول فتكون حالكم كحال اليهود والمنافقين، ولكن تناجوا بما هو خير لا إثم فيه، وبطاعة الله ورسوله، واتقوا الله الذي إليه تُحشرون. إنما النجوى من الشيطان، هو الدافع إليها، ليوقع المؤمنين في غمّ وحزن، وليس التناجي ولا الشيطان بضارّ المؤمنين شيئاً إلا بإرادة الله لحِكم يعلمها، فلا تحزنوا لما ترون من تناجي أعدائكم، وتوكّلوا على الله في أموركم كلها، فإنه كافٍ من يتوكّل عليه كل ما يهمّه.", "h": ["بيان مكر اليهود والمنافقين وكيدهم للمؤمنين في كل زمان ومكان.", "إذا حيّا الكافر المؤمن، ردّ عليه المؤمن بقوله: وعليكم؛ لما صحّ أن النبي ﷺ دخل عليه ناس من اليهود فقالوا: السام عليك يا أبا القاسم، فقال ﷺ: «وعليكم»، فقالت عائشة رضي الله عنها: عليكم السام ولعنكم الله وغضب عليكم، فقال لها ﷺ: «يا عائشة، عليك بالرفق، وإياك والعنف والفحش»، فقالت: ألا تسمعهم يقولون السام؟ فقال لها: «أوما سمعتِ ما أقول: وعليكم». رواه الشيخان.", "إذا سلّم الذميّ وكان سلامه بلفظ: السلام عليكم، لا بأس أن يُردّ عليه بلفظه.", "حرمة التناجي بغير البر والتقوى، لقوله تعالى: «إلا من أمر بصدقة أو معروف أو إصلاح بين الناس» من سورة النساء.", "لا يجوز أن يتناجى اثنان دون الثالث، لما يوقع ذلك في نفس الثالث من حزن، لا سيما إن كان ذلك في سفر أو في حرب.", "وجوب التوكّل على الله، وترك الأوهام والوساوس فإنها من الشيطان."], "k": "«وتناجوا بالبر والتقوى»… حين أهمس لأحد، هل أهمس بخير أم بما يُحزن غائباً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (405, 58, 11, 22, 'سورة المجادلة ١١ – ٢٢', 'المجادلة: أولئك حزب الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 405) = $j$[{"lbl": "الآيات ١١ – ١٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿١١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيۡتُمُ ٱلرَّسُولَ فَقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَةٗۚ ذَٰلِكَ خَيۡرٞ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٢﴾ ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَٰتٖۚ فَإِذۡ لَمۡ تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٣﴾", "w": [["تفسّحوا في المجالس", "توسّعوا في المجالس التي هي مجالس علم وذكر."], ["فافسحوا يفسح الله لكم", "في الجنة وفي الرزق والقبر."], ["وإذا قيل انشزوا فانشزوا", "قوموا للصلاة أو لغيرها من أعمال البر."], ["يرفع الله الذين آمنوا منكم", "بالنصر وحسن الذكر في الدنيا، وفي غرفات الجنان في الآخرة."], ["والذين أوتوا العلم درجات", "ويرفع الذين أوتوا العلم درجات عالية لجمعهم بين العلم والعمل."], ["إذا ناجيتم الرسول", "إذا أردتم مناجاته."], ["فقدّموا بين يدي نجواكم صدقة", "قبل المناجاة تصدّقوا بصدقة ثم ناجوه ﷺ."], ["ذلك خير لكم وأطهر", "تقديم الصدقة بين يدي المناجاة خير لما فيه من نفع الفقراء، وأطهر لذنوبكم."], ["فإن لم تجدوا", "ما تتصدّقون به."], ["فإن الله غفور رحيم", "غفور لمناجاتكم، رحيم بكم، فليس عليكم في المناجاة بدون صدقة إثم."], ["أأشفقتم أن تقدّموا", "أخفتم الفقر إن قدّمتم بين يدي نجواكم صدقات؟"], ["فإذ لم تفعلوا وتاب الله عليكم", "لم تقدّموا الصدقات، وتاب الله عليكم بأن رخّص لكم في تركها."], ["فأقيموا الصلاة وآتوا الزكاة", "على الوجه المطلوب من إقامتها، وأخرجوا الزكاة."], ["وأطيعوا الله ورسوله", "وداوموا على ذلك وعلى طاعة الله ورسوله."], ["والله خبير بما تعملون", "من أعمال البر والإحسان، وسيثيبكم على ذلك بالجنة."]], "m": "ما زال السياق في تربية المؤمنين وتهذيبهم ليكملوا ويسعدوا: يا أيها الذين آمنوا إذا قال لكم الرسول ﷺ أو غيره: توسّعوا في المجلس ليجد غيركم مكاناً بينكم، فتوسّعوا ولا تضنّوا بالقرب من الرسول أو من العالم الذي يعلّمكم أو المذكّر الذي يذكّركم، فإن أنتم تفسّحتم فإن الله يكافئكم فيوسّع عليكم في الدنيا بسعة الرزق، وفي القبر، وفي الآخرة في غرفات الجنان. وإذا قيل قوموا من المجلس لعلة أو للصلاة أو لفعل بر فقوموا، يرفع الله الذين آمنوا منكم درجات بالنصر والذكر الحسن في الدنيا وفي غرف الجنة في الآخرة، والذين أوتوا العلم منكم درجات عالية لجمعهم بين الإيمان والعلم والعمل، والله بما تعملون خبير، يذكّرهم بعلمه بهم ليراقبوه. ثم أمرهم إذا أراد أحدهم أن يناجي رسول الله ﷺ ويكلّمه وحده أن يقدّم صدقة أولاً، وكان هذا لمصلحة الفقراء، وللتخفيف عن رسول الله ﷺ، إذ كل مؤمن يودّ أن يخلو به ويكلّمه، والرسول بشر لا يتّسع لكل أحد. ذلك خير لكم حيث تعود الصدقة على إخوانكم الفقراء، وأطهر لنفوسكم، فإن لم تجدوا ما تقدّمونه فناجوه ولا حرج عليكم. فلما تحرّجوا من بذل الصدقة، وأكثرهم فقراء، نسخ تعالى ذلك، ولم تدم مدة الوجوب أكثر من ليالٍ: أأشفقتم أن تقدّموا بين يدي نجواكم صدقات؟ فإذ لم تفعلوا وتاب الله عليكم برفع هذا الواجب، فأقيموا الصلاة بأدائها في أوقاتها في جماعة المؤمنين، وآتوا الزكاة الواجبة، وأطيعوا الله ورسوله، يكفكم ذلك عوضاً عن الصدقة التي نُسخت تخفيفاً عليكم ورحمة، والله خبير بما تعملون فراقبوه.", "h": ["الندب إلى فضيلة التوسّع في مجالس العلم والتذكير.", "الندب والترغيب في القيام بالمعروف وأداء الواجبات إذا دُعي المؤمن إلى ذلك.", "فضيلة الإيمان، وفضل العلم والعمل به.", "مشروعية النسخ في الشريعة قبل العمل بالمنسوخ وبعده، إذ هذه الصدقة نُسخت قبل أن يُعمل بها، إلا ما كان من علي رضي الله عنه، فإنه أخبر أنه تصدّق بدينار وناجى رسول الله ﷺ ثم نُسخت هذه الصدقة، فكان يقول: في القرآن آية لم يعمل بها أحد غيري، وهي فضيلة له.", "في إقامة الصلاة وإيتاء الزكاة وطاعة الله ورسوله في الواجبات والمحرّمات عوض عما يفوت المؤمن من النوافل."], "k": "«تفسّحوا في المجالس فافسحوا يفسح الله لكم»… مكان صغير أتركه لغيري يوسّع الله به عليّ؛ فهل أتذكّر هذا في الزحام؟"}, {"lbl": "الآيات ١٤ – ١٩", "q": "۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ يَعۡلَمُونَ ﴿١٤﴾ أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدًاۖ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٥﴾ ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِ فَلَهُمۡ عَذَابٞ مُّهِينٞ ﴿١٦﴾ لَّن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿١٧﴾ يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ ﴿١٨﴾ ٱسۡتَحۡوَذَ عَلَيۡهِمُ ٱلشَّيۡطَٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُوْلَـٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ أَلَآ إِنَّ حِزۡبَ ٱلشَّيۡطَٰنِ هُمُ ٱلۡخَٰسِرُونَ ﴿١٩﴾", "w": [["ألم تر إلى الذين تولّوا قوماً غضب الله عليهم", "ألم تنظر إلى المنافقين الذين تولّوا اليهود؟"], ["ما هم منكم ولا منهم", "ما هم منكم أيها المؤمنون ولا من اليهود، بل هم مذبذبون."], ["ويحلفون على الكذب وهم يعلمون", "يحلفون لكم أنهم مؤمنون وهم يعلمون أنهم غير مؤمنين."], ["إنهم ساء ما كانوا يعملون", "قبح أشد القبح عملهم، وهو النفاق والمعاصي."], ["اتخذوا أيمانهم جُنّة", "ستراً على أنفسهم وأموالهم، فادّعوا الإيمان كذباً وحلفوا عليه."], ["فصدّوا عن سبيل الله", "فصدّوا بتلك الأيمان المؤمنين عن قتالهم."], ["فيحلفون له كما يحلفون لكم", "يوم يبعثهم يحلفون لله أنهم كانوا مؤمنين كما يحلفون لكم اليوم."], ["ويحسبون أنهم على شيء", "يظنون في أيمانهم الكاذبة أنهم على شيء من الحق."], ["استحوذ عليهم الشيطان", "غلب عليهم الشيطان."], ["فأنساهم ذكر الله", "فلم يذكروه بألسنتهم إلا تقيّة، ولا يذكرون وعده ولا وعيده."], ["أولئك حزب الشيطان", "أتباع الشيطان وجنده."], ["ألا إن حزب الشيطان هم الخاسرون", "المغبونون الخاسرون في صفقة حياتهم."]], "m": "في الأيام التي نزلت فيها هذه السورة كان النفاق بالمدينة بالغاً أشدّه، وكان اليهود كذلك كثيرين متحزّبين ضد الإسلام، وذلك قبل إجلائهم من المدينة، ففي هذه الآيات يحذّر الله رسوله والمؤمنين من العدوّين معاً: ألم تر يا رسولنا إلى المنافقين الذين تولّوا اليهود ولاية نصرة وتحزّب ضد الرسول والمؤمنين؟ ما هم منكم ولا من اليهود، بل هم مذبذبون حيارى، معكم في الظاهر ومع اليهود في الباطن. ويحلفون على الكذب وهم يعلمون أنهم كاذبون، إذ كانوا يأتون رسول الله ﷺ ويحلفون له أنهم مؤمنون، فتوعّدهم الله بقوله: أعدّ الله لهم عذاباً شديداً، إنهم ساء ما كانوا يعملون. اتخذوا أيمانهم ستارة ووقاية يقون بها أنفسهم من القتل وأموالهم من الأخذ، فصدّوا بتلك الأيمان الكاذبة المؤمنين عن قتالهم، فلهم عذاب مهين يوم القيامة. لن تغني عنهم يوم القيامة أموالهم التي يجمعونها ولا أولادهم الذين يعتزّون بهم من الله شيئاً، أولئك أصحاب النار هم فيها خالدون. واذكر يا رسولنا يوم يبعثهم الله جميعاً فيحلفون له أنهم كانوا مؤمنين كما يحلفون لكم اليوم، ويظنّون أنهم على شيء من الصواب، ألا إنهم هم الكاذبون. غلب عليهم الشيطان فأنساهم ذكر الله، فلا يذكرونه إلا قليلاً، كما أنساهم ذكر وعده ووعيده، فلا يرغبون فيما عنده ولا يرهبون مما لديه، أولئك أتباع الشيطان وجنده، ألا إن حزب الشيطان هم المغبونون في صفقتهم في الدنيا والآخرة.", "h": ["حرمة موالاة اليهود.", "حرمة الحلف على الكذب، وهي اليمين الغموس.", "من علامات استحواذ الشيطان على الإنسان تركه لذكر الله بقلبه ولسانه."], "k": "«استحوذ عليهم الشيطان فأنساهم ذكر الله»… حين يطول غيابي عن الذكر، فمن الذي استحوذ على قلبي؟"}, {"lbl": "الآيات ٢٠ – ٢٢", "q": "إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَـٰٓئِكَ فِي ٱلۡأَذَلِّينَ ﴿٢٠﴾ كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ﴿٢١﴾ لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوٓاْ ءَابَآءَهُمۡ أَوۡ أَبۡنَآءَهُمۡ أَوۡ إِخۡوَٰنَهُمۡ أَوۡ عَشِيرَتَهُمۡۚ أُوْلَـٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ وَأَيَّدَهُم بِرُوحٖ مِّنۡهُۖ وَيُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ رَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ أُوْلَـٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ ﴿٢٢﴾", "w": [["إن الذين يحادّون الله ورسوله", "يخالفون الله ورسوله فيما يأمران به وينهيان عنه."], ["أولئك في الأذلّين", "المغلوبين المقهورين."], ["كتب الله لأغلبنّ أنا ورسلي", "كتب في اللوح المحفوظ، أو قضى وحكم، بأن يغلب هو ورسله بالحجة أو السيف."], ["يوادّون من حادّ الله ورسوله", "يصادقون من يخالف الله ورسوله بمحبتهم ونصرتهم."], ["ولو كانوا آباءهم أو أبناءهم أو إخوانهم أو عشيرتهم", "ولو كانوا أقرب قريب إليهم، وقد قاتل الصحابة أقرباءهم على الإيمان."], ["أولئك كتب في قلوبهم الإيمان", "أثبت الإيمان في قلوبهم."], ["وأيّدهم بروح منه", "ببرهان ونور وهدى."], ["رضي الله عنهم ورضوا عنه", "رضي الله عنهم بطاعتهم إياه في الدنيا، ورضوا عنه في الآخرة بإدخاله إياهم الجنة."], ["ألا إن حزب الله هم المفلحون", "جند الله وأولياؤه هم الفائزون بالنجاة من النار ودخول الجنة."]], "m": "يخبر تعالى موجّهاً المؤمنين مرشداً لهم إلى أقوم طريق: إن الذين يخالفون الله ورسوله في أمرهما ونهيهما وما يدعوان إليه من الدين الحق أولئك في زمرة الأذلّين في الدنيا والآخرة. كتب الله في اللوح المحفوظ وقضى بأن يغلب رسله أعداءه بالحجة والسيف، إن الله قوي عزيز، ذو قوة لا تُقهر وعزة لا تُرام، فلذا قضى بنصرة رسوله على أعدائه مهما كانت قوتهم. لا تجد يا رسولنا أناساً يؤمنون بالله إيماناً صادقاً وباليوم الآخر يوادّون بالمحبة والنصرة من حادّ الله ورسوله، ولو كانوا أقرب قريب إليهم من أب أو ابن أو أخ أو عشيرة. أولئك كتب الله في قلوبهم الإيمان، أي أثبته وقرّره فيها، فهو لا يبرح ينير لهم طريق الهدى حتى ينتهوا إلى جوار ربهم، وأيّدهم ببرهان ونور منه، هذا في الدنيا، وأما في الآخرة فيدخلهم جنات تجري من تحتها الأنهار خالدين فيها، وفوق ذلك رضي الله عنهم بطاعتهم إياه، ورضوا عنه بإدخاله إياهم الجنة. أولئك العالون في كمالاتهم الروحية حزب الله، أي جنده وأولياؤه، ألا إن حزب الله هم المفلحون، الفائزون يوم القيامة بالنجاة من النار ودخول الجنة.", "h": ["كتب الله الذل والصغار على من حادّه وحادّ رسوله بمخالفتهما فيما يحبّان ويكرهان.", "قضى الله تعالى بنصرة رسوله فنصره، إنه قوي عزيز.", "حرمة موالاة الكافر بالنصرة والمحبة ولو كان أقرب قريب، وقد قاتل أصحاب رسول الله ﷺ آباءهم وأبناءهم وإخوانهم وعشيرتهم في بدر، وفيهم نزلت هذه الآية تبشّرهم برضوان الله تعالى لهم وإنعامه عليهم."], "k": "«رضي الله عنهم ورضوا عنه»… رضاه غاية الغايات؛ فهل أنا راضٍ عن قضائه كما أرجو أن يرضى عني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 405;
insert into public.tdb_cards(topic, i, body) select 405, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١ – ١٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿١١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيۡتُمُ ٱلرَّسُولَ فَقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَةٗۚ ذَٰلِكَ خَيۡرٞ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٢﴾ ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَٰتٖۚ فَإِذۡ لَمۡ تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٣﴾", "w": [["تفسّحوا في المجالس", "توسّعوا في المجالس التي هي مجالس علم وذكر."], ["فافسحوا يفسح الله لكم", "في الجنة وفي الرزق والقبر."], ["وإذا قيل انشزوا فانشزوا", "قوموا للصلاة أو لغيرها من أعمال البر."], ["يرفع الله الذين آمنوا منكم", "بالنصر وحسن الذكر في الدنيا، وفي غرفات الجنان في الآخرة."], ["والذين أوتوا العلم درجات", "ويرفع الذين أوتوا العلم درجات عالية لجمعهم بين العلم والعمل."], ["إذا ناجيتم الرسول", "إذا أردتم مناجاته."], ["فقدّموا بين يدي نجواكم صدقة", "قبل المناجاة تصدّقوا بصدقة ثم ناجوه ﷺ."], ["ذلك خير لكم وأطهر", "تقديم الصدقة بين يدي المناجاة خير لما فيه من نفع الفقراء، وأطهر لذنوبكم."], ["فإن لم تجدوا", "ما تتصدّقون به."], ["فإن الله غفور رحيم", "غفور لمناجاتكم، رحيم بكم، فليس عليكم في المناجاة بدون صدقة إثم."], ["أأشفقتم أن تقدّموا", "أخفتم الفقر إن قدّمتم بين يدي نجواكم صدقات؟"], ["فإذ لم تفعلوا وتاب الله عليكم", "لم تقدّموا الصدقات، وتاب الله عليكم بأن رخّص لكم في تركها."], ["فأقيموا الصلاة وآتوا الزكاة", "على الوجه المطلوب من إقامتها، وأخرجوا الزكاة."], ["وأطيعوا الله ورسوله", "وداوموا على ذلك وعلى طاعة الله ورسوله."], ["والله خبير بما تعملون", "من أعمال البر والإحسان، وسيثيبكم على ذلك بالجنة."]], "m": "ما زال السياق في تربية المؤمنين وتهذيبهم ليكملوا ويسعدوا: يا أيها الذين آمنوا إذا قال لكم الرسول ﷺ أو غيره: توسّعوا في المجلس ليجد غيركم مكاناً بينكم، فتوسّعوا ولا تضنّوا بالقرب من الرسول أو من العالم الذي يعلّمكم أو المذكّر الذي يذكّركم، فإن أنتم تفسّحتم فإن الله يكافئكم فيوسّع عليكم في الدنيا بسعة الرزق، وفي القبر، وفي الآخرة في غرفات الجنان. وإذا قيل قوموا من المجلس لعلة أو للصلاة أو لفعل بر فقوموا، يرفع الله الذين آمنوا منكم درجات بالنصر والذكر الحسن في الدنيا وفي غرف الجنة في الآخرة، والذين أوتوا العلم منكم درجات عالية لجمعهم بين الإيمان والعلم والعمل، والله بما تعملون خبير، يذكّرهم بعلمه بهم ليراقبوه. ثم أمرهم إذا أراد أحدهم أن يناجي رسول الله ﷺ ويكلّمه وحده أن يقدّم صدقة أولاً، وكان هذا لمصلحة الفقراء، وللتخفيف عن رسول الله ﷺ، إذ كل مؤمن يودّ أن يخلو به ويكلّمه، والرسول بشر لا يتّسع لكل أحد. ذلك خير لكم حيث تعود الصدقة على إخوانكم الفقراء، وأطهر لنفوسكم، فإن لم تجدوا ما تقدّمونه فناجوه ولا حرج عليكم. فلما تحرّجوا من بذل الصدقة، وأكثرهم فقراء، نسخ تعالى ذلك، ولم تدم مدة الوجوب أكثر من ليالٍ: أأشفقتم أن تقدّموا بين يدي نجواكم صدقات؟ فإذ لم تفعلوا وتاب الله عليكم برفع هذا الواجب، فأقيموا الصلاة بأدائها في أوقاتها في جماعة المؤمنين، وآتوا الزكاة الواجبة، وأطيعوا الله ورسوله، يكفكم ذلك عوضاً عن الصدقة التي نُسخت تخفيفاً عليكم ورحمة، والله خبير بما تعملون فراقبوه.", "h": ["الندب إلى فضيلة التوسّع في مجالس العلم والتذكير.", "الندب والترغيب في القيام بالمعروف وأداء الواجبات إذا دُعي المؤمن إلى ذلك.", "فضيلة الإيمان، وفضل العلم والعمل به.", "مشروعية النسخ في الشريعة قبل العمل بالمنسوخ وبعده، إذ هذه الصدقة نُسخت قبل أن يُعمل بها، إلا ما كان من علي رضي الله عنه، فإنه أخبر أنه تصدّق بدينار وناجى رسول الله ﷺ ثم نُسخت هذه الصدقة، فكان يقول: في القرآن آية لم يعمل بها أحد غيري، وهي فضيلة له.", "في إقامة الصلاة وإيتاء الزكاة وطاعة الله ورسوله في الواجبات والمحرّمات عوض عما يفوت المؤمن من النوافل."], "k": "«تفسّحوا في المجالس فافسحوا يفسح الله لكم»… مكان صغير أتركه لغيري يوسّع الله به عليّ؛ فهل أتذكّر هذا في الزحام؟"}, {"lbl": "الآيات ١٤ – ١٩", "q": "۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ يَعۡلَمُونَ ﴿١٤﴾ أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدًاۖ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٥﴾ ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِ فَلَهُمۡ عَذَابٞ مُّهِينٞ ﴿١٦﴾ لَّن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿١٧﴾ يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ ﴿١٨﴾ ٱسۡتَحۡوَذَ عَلَيۡهِمُ ٱلشَّيۡطَٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُوْلَـٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ أَلَآ إِنَّ حِزۡبَ ٱلشَّيۡطَٰنِ هُمُ ٱلۡخَٰسِرُونَ ﴿١٩﴾", "w": [["ألم تر إلى الذين تولّوا قوماً غضب الله عليهم", "ألم تنظر إلى المنافقين الذين تولّوا اليهود؟"], ["ما هم منكم ولا منهم", "ما هم منكم أيها المؤمنون ولا من اليهود، بل هم مذبذبون."], ["ويحلفون على الكذب وهم يعلمون", "يحلفون لكم أنهم مؤمنون وهم يعلمون أنهم غير مؤمنين."], ["إنهم ساء ما كانوا يعملون", "قبح أشد القبح عملهم، وهو النفاق والمعاصي."], ["اتخذوا أيمانهم جُنّة", "ستراً على أنفسهم وأموالهم، فادّعوا الإيمان كذباً وحلفوا عليه."], ["فصدّوا عن سبيل الله", "فصدّوا بتلك الأيمان المؤمنين عن قتالهم."], ["فيحلفون له كما يحلفون لكم", "يوم يبعثهم يحلفون لله أنهم كانوا مؤمنين كما يحلفون لكم اليوم."], ["ويحسبون أنهم على شيء", "يظنون في أيمانهم الكاذبة أنهم على شيء من الحق."], ["استحوذ عليهم الشيطان", "غلب عليهم الشيطان."], ["فأنساهم ذكر الله", "فلم يذكروه بألسنتهم إلا تقيّة، ولا يذكرون وعده ولا وعيده."], ["أولئك حزب الشيطان", "أتباع الشيطان وجنده."], ["ألا إن حزب الشيطان هم الخاسرون", "المغبونون الخاسرون في صفقة حياتهم."]], "m": "في الأيام التي نزلت فيها هذه السورة كان النفاق بالمدينة بالغاً أشدّه، وكان اليهود كذلك كثيرين متحزّبين ضد الإسلام، وذلك قبل إجلائهم من المدينة، ففي هذه الآيات يحذّر الله رسوله والمؤمنين من العدوّين معاً: ألم تر يا رسولنا إلى المنافقين الذين تولّوا اليهود ولاية نصرة وتحزّب ضد الرسول والمؤمنين؟ ما هم منكم ولا من اليهود، بل هم مذبذبون حيارى، معكم في الظاهر ومع اليهود في الباطن. ويحلفون على الكذب وهم يعلمون أنهم كاذبون، إذ كانوا يأتون رسول الله ﷺ ويحلفون له أنهم مؤمنون، فتوعّدهم الله بقوله: أعدّ الله لهم عذاباً شديداً، إنهم ساء ما كانوا يعملون. اتخذوا أيمانهم ستارة ووقاية يقون بها أنفسهم من القتل وأموالهم من الأخذ، فصدّوا بتلك الأيمان الكاذبة المؤمنين عن قتالهم، فلهم عذاب مهين يوم القيامة. لن تغني عنهم يوم القيامة أموالهم التي يجمعونها ولا أولادهم الذين يعتزّون بهم من الله شيئاً، أولئك أصحاب النار هم فيها خالدون. واذكر يا رسولنا يوم يبعثهم الله جميعاً فيحلفون له أنهم كانوا مؤمنين كما يحلفون لكم اليوم، ويظنّون أنهم على شيء من الصواب، ألا إنهم هم الكاذبون. غلب عليهم الشيطان فأنساهم ذكر الله، فلا يذكرونه إلا قليلاً، كما أنساهم ذكر وعده ووعيده، فلا يرغبون فيما عنده ولا يرهبون مما لديه، أولئك أتباع الشيطان وجنده، ألا إن حزب الشيطان هم المغبونون في صفقتهم في الدنيا والآخرة.", "h": ["حرمة موالاة اليهود.", "حرمة الحلف على الكذب، وهي اليمين الغموس.", "من علامات استحواذ الشيطان على الإنسان تركه لذكر الله بقلبه ولسانه."], "k": "«استحوذ عليهم الشيطان فأنساهم ذكر الله»… حين يطول غيابي عن الذكر، فمن الذي استحوذ على قلبي؟"}, {"lbl": "الآيات ٢٠ – ٢٢", "q": "إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَـٰٓئِكَ فِي ٱلۡأَذَلِّينَ ﴿٢٠﴾ كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ﴿٢١﴾ لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوٓاْ ءَابَآءَهُمۡ أَوۡ أَبۡنَآءَهُمۡ أَوۡ إِخۡوَٰنَهُمۡ أَوۡ عَشِيرَتَهُمۡۚ أُوْلَـٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ وَأَيَّدَهُم بِرُوحٖ مِّنۡهُۖ وَيُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ رَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ أُوْلَـٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ ﴿٢٢﴾", "w": [["إن الذين يحادّون الله ورسوله", "يخالفون الله ورسوله فيما يأمران به وينهيان عنه."], ["أولئك في الأذلّين", "المغلوبين المقهورين."], ["كتب الله لأغلبنّ أنا ورسلي", "كتب في اللوح المحفوظ، أو قضى وحكم، بأن يغلب هو ورسله بالحجة أو السيف."], ["يوادّون من حادّ الله ورسوله", "يصادقون من يخالف الله ورسوله بمحبتهم ونصرتهم."], ["ولو كانوا آباءهم أو أبناءهم أو إخوانهم أو عشيرتهم", "ولو كانوا أقرب قريب إليهم، وقد قاتل الصحابة أقرباءهم على الإيمان."], ["أولئك كتب في قلوبهم الإيمان", "أثبت الإيمان في قلوبهم."], ["وأيّدهم بروح منه", "ببرهان ونور وهدى."], ["رضي الله عنهم ورضوا عنه", "رضي الله عنهم بطاعتهم إياه في الدنيا، ورضوا عنه في الآخرة بإدخاله إياهم الجنة."], ["ألا إن حزب الله هم المفلحون", "جند الله وأولياؤه هم الفائزون بالنجاة من النار ودخول الجنة."]], "m": "يخبر تعالى موجّهاً المؤمنين مرشداً لهم إلى أقوم طريق: إن الذين يخالفون الله ورسوله في أمرهما ونهيهما وما يدعوان إليه من الدين الحق أولئك في زمرة الأذلّين في الدنيا والآخرة. كتب الله في اللوح المحفوظ وقضى بأن يغلب رسله أعداءه بالحجة والسيف، إن الله قوي عزيز، ذو قوة لا تُقهر وعزة لا تُرام، فلذا قضى بنصرة رسوله على أعدائه مهما كانت قوتهم. لا تجد يا رسولنا أناساً يؤمنون بالله إيماناً صادقاً وباليوم الآخر يوادّون بالمحبة والنصرة من حادّ الله ورسوله، ولو كانوا أقرب قريب إليهم من أب أو ابن أو أخ أو عشيرة. أولئك كتب الله في قلوبهم الإيمان، أي أثبته وقرّره فيها، فهو لا يبرح ينير لهم طريق الهدى حتى ينتهوا إلى جوار ربهم، وأيّدهم ببرهان ونور منه، هذا في الدنيا، وأما في الآخرة فيدخلهم جنات تجري من تحتها الأنهار خالدين فيها، وفوق ذلك رضي الله عنهم بطاعتهم إياه، ورضوا عنه بإدخاله إياهم الجنة. أولئك العالون في كمالاتهم الروحية حزب الله، أي جنده وأولياؤه، ألا إن حزب الله هم المفلحون، الفائزون يوم القيامة بالنجاة من النار ودخول الجنة.", "h": ["كتب الله الذل والصغار على من حادّه وحادّ رسوله بمخالفتهما فيما يحبّان ويكرهان.", "قضى الله تعالى بنصرة رسوله فنصره، إنه قوي عزيز.", "حرمة موالاة الكافر بالنصرة والمحبة ولو كان أقرب قريب، وقد قاتل أصحاب رسول الله ﷺ آباءهم وأبناءهم وإخوانهم وعشيرتهم في بدر، وفيهم نزلت هذه الآية تبشّرهم برضوان الله تعالى لهم وإنعامه عليهم."], "k": "«رضي الله عنهم ورضوا عنه»… رضاه غاية الغايات؛ فهل أنا راضٍ عن قضائه كما أرجو أن يرضى عني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (406, 59, 1, 10, 'سورة الحشر ١ – ١٠', 'الحشر: ويؤثرون على أنفسهم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 406) = $j$[{"lbl": "الآيات ١ – ٥", "q": "سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١﴾ هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَـٰٓأُوْلِي ٱلۡأَبۡصَٰرِ ﴿٢﴾ وَلَوۡلَآ أَن كَتَبَ ٱللَّهُ عَلَيۡهِمُ ٱلۡجَلَآءَ لَعَذَّبَهُمۡ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابُ ٱلنَّارِ ﴿٣﴾ ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٤﴾ مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ ﴿٥﴾", "w": [["سبّح لله ما في السماوات وما في الأرض", "نزّه الله تعالى وقدّسه بلسان الحال والمقال ما في السماوات وما في الأرض من سائر الكائنات."], ["وهو العزيز الحكيم", "العزيز في انتقامه من أعدائه، الحكيم في تدبيره لأوليائه."], ["هو الذي أخرج الذين كفروا من أهل الكتاب من ديارهم", "أخرج يهود بني النضير من ديارهم بالمدينة."], ["لأول الحشر", "لأول حشر كان، وثاني حشر كان من خيبر إلى الشام."], ["ما ظننتم أن يخرجوا", "ما ظننتم أيها المؤمنون أن بني النضير يخرجون من ديارهم."], ["وظنّوا أنهم مانعتهم حصونهم من الله", "ظنّوا أن حصونهم تمنعهم مما قضى الله به عليهم من إجلائهم."], ["فأتاهم الله من حيث لم يحتسبوا", "فجاءهم الله من حيث لم يظنّوا أنهم يُؤتون منه."], ["وقذف في قلوبهم الرعب", "قذف الله تعالى فيها الخوف الشديد من محمد وأصحابه."], ["يخربون بيوتهم بأيديهم", "حتى لا ينتفع بها المؤمنون، وليأخذوا بعض أبوابها وأخشابها المستحسنة معهم."], ["وأيدي المؤمنين", "إذ كانوا يهدمون عليهم الحصون ليتمكّنوا من قتالهم."], ["فاعتبروا يا أولي الأبصار", "فاتّعظوا بحالهم يا أصحاب العقول، ولا تغترّوا ولا تعتمدوا إلا على الله."], ["ولولا أن كتب الله عليهم الجلاء", "الخروج من المدينة."], ["لعذّبهم في الدنيا", "بالقتل والسبي كما عذّب إخوانهم بني قريظة."], ["ذلك بأنهم شاقّوا الله ورسوله", "جزاهم بما جزاهم به بسبب مخالفتهم لله ورسوله ومعاداتهم لهما."], ["ما قطعتم من لينة أو تركتموها", "ما قطعتم أيها المؤمنون من نخلة أو تركتموها بلا قطع."], ["فبإذن الله وليخزي الفاسقين", "كان بإرادة الله، وليخزي الفاسقين يهود بني النضير."]], "m": "يخبر تعالى عن جلاله وعظمته بأنه سبّحه، أي نزّهه عن كل النقائص من الشريك والصاحبة والولد والعجز، بلسان القال والحال جميع ما في السماوات وما في الأرض من الملائكة والإنس والجن والحيوان والشجر والحجر، وأنه هو العزيز الحكيم. هو الذي أخرج الذين كفروا من ديارهم، يهود بني النضير، أجلاهم من ديارهم بالمدينة لأول الحشر إلى أذرعات بالشام، ومنهم من نزل بخيبر، وسيكون لهم حشر آخر حيث أجلاهم عمر من خيبر إلى الشام. ما ظننتم أيها المؤمنون أن يخرجوا، وظنّوا هم أن حصونهم مانعتهم من الله، فخاب ظنهم، إذ أتاهم أمر الله من حيث لم يظنّوا، بأن قذف في قلوبهم الرعب من الرسول وأصحابه، حتى أصبحوا يخربون بيوتهم بأيديهم وأيدي المؤمنين: المؤمنون يخربونها من الظاهر لفتح البلاد، وهم يخربونها من الباطن، وذلك أن الصلح الذي تمّ أنهم يحملون أموالهم إلا السلاح ويجلون إلى الشام، فكانوا إذا أعجبهم الباب أو الخشبة نزعوها فيخرب البيت لذلك. فاعتبروا يا أولي البصائر بحال بني النضير الأقوياء كيف قذف الله الرعب في قلوبهم، فلا تغترّوا بقواكم، ولكن اعتمدوا على الله وتوكّلوا عليه. ولولا أن كتب الله عليهم الجلاء أزلاً لعذّبهم في الدنيا بالقتل والسبي كما عذّب بني قريظة بعدهم، ولهم في الآخرة عذاب النار، ذلك بأنهم خالفوا الله ورسوله وعادوهما، ومن يشاقّ الله فإن الله شديد العقاب. وما قطعتم من نخلة أو تركتموها قائمة على أصولها فقد كان ذلك بإذن الله فلا إثم عليكم فيه، وأخزى به الفاسقين اليهود.", "h": ["بيان جلال الله وعظمته مع عزه وحكمته في تسبيحه من كل المخلوقات العلوية والسفلية، وفي إجلاء بني النضير من ديارهم، وهو أول حشر لهم.", "بيان أكبر عبرة في خروج بني النضير، وذلك لما كان لهم من قوة، ولما عليه المؤمنون من ضعف، ومع هذا فقد انهزموا وتركوا البلاد والأموال ورحلوا إلى غير رجعة؛ فعلى مثل هذا يتّعظ المتّعظون، فإنه لا قوة تنفع مع قوة الله، فلا يغترّ العقلاء بقواهم المادية، بل عليهم أن يعتمدوا على الله أولاً وآخراً.", "علّة هزيمة بني النضير ليست إلا محادّتهم لله والرسول ومخالفتهم لهما، وهذه سنّته تعالى في كل من يحادّه ويحادّ رسوله، فإنه ينزل به أشد أنواع العقوبات.", "عفو الله تعالى عن المجتهد إذا أخطأ وعدم مؤاخذته؛ فقد اجتهد المؤمنون في قطع نخل بني النضير من أجل إغاظتهم حتى ينزلوا من حصونهم، وقطع النخل المثمر فساد، ولكن الله تعالى لم يؤاخذهم لأنهم مجتهدون."], "k": "«وظنّوا أنهم مانعتهم حصونهم من الله»… على أي حصن أعتمد أنا غير الله؟"}, {"lbl": "الآيتان ٦ – ٧", "q": "وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَآ أَوۡجَفۡتُمۡ عَلَيۡهِ مِنۡ خَيۡلٖ وَلَا رِكَابٖ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٦﴾ مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٧﴾", "w": [["وما أفاء الله على رسوله منهم", "وما ردّ الله ليد رسوله ﷺ من مال بني النضير."], ["فما أوجفتم عليه من خيل ولا ركاب", "لم تسرعوا في طلبه بخيل ولا إبل، ولم تعانوا فيه مشقة."], ["ولكن الله يسلّط رسله على من يشاء", "وقد سلّط رسوله محمداً ﷺ على بني النضير ففتح بلادهم صلحاً."], ["وما أفاء الله على رسوله من أهل القرى", "ما ردّ الله على رسوله من أموال أهل القرى التي لم يُوجف عليها بخيل ولا ركاب."], ["فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل", "لله جزء، وللرسول جزء، ولقرابة الرسول جزء، ولليتامى جزء، وللمساكين جزء، ولابن السبيل جزء، تُقسم بالسوية."], ["كي لا يكون دولة بين الأغنياء منكم", "كيلا يكون المال متداولاً بين الأغنياء الأقوياء ولا يناله الضعفاء والفقراء."], ["وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا", "ما أعطاكم الرسول أو أذن لكم فيه أو أمركم به فخذوه، وما نهاكم عنه وحظره عليكم فانتهوا عنه."], ["واتقوا الله إن الله شديد العقاب", "فلا تعصوه ولا تعصوا رسوله، واحذروا عقوبته."]], "m": "ما زال السياق في غزوة بني النضير؛ بعد الصلح تركوا بساتينهم فيئاً لرسول الله ﷺ، فرغب المسلمون فيها، ورأى بعضهم أنها ستُقسم عليهم كما تُقسم الغنائم، فأبى الله ذلك وقال: وما ردّ الله على رسوله من مال بني النضير، والفيء الظل يتقلّص ثم يرجع؛ وأصل أموالهم لرسول الله ﷺ، لأنهم عاهدوه فأبقى عليهم أموالهم بمقتضى المعاهدة، فلما نقضوا العهد وتآمروا على قتله لم يستحقوا من المال شيئاً. وبداية القضية أن من بنود المعاهدة أن يُسهموا مع الرسول فيما يتحمّل من ديات، فلما قتل عمرو بن أمية الضمري رجلين خطأً، خرج ﷺ إلى بني النضير يطالبهم بالإسهام في الدية، فأنزلوه بأحسن مجلس، ثم خلوا بأنفسهم وقالوا: الفرصة سانحة للتخلّص من الرجل، فجاؤوا برحى من صخرة وطلعوا بها إلى سطح المنزل، وهمّوا أن يسقطوها على رأسه ﷺ وهو جالس في ظل الجدار، فأوحى الله إليه أن قم من مكانك، فقام على الفور، ثم أعلن الخروج إليهم لنقضهم العهد، فحاصرهم، وانتهى الأمر بصلح يقضي بأن يجلوا عن المدينة يحملون أموالهم على إبلهم دون السلاح. فما أوجفتم على أموالهم خيلاً ولا إبلاً، لأنهم في طرف المدينة، فلم تتحمّلوا سفراً ولا قتالاً، فلذا لا حقّ لكم فيها، فإنها فيء وليست بغنيمة، ولكن الله يسلّط رسله على من يشاء بدون قتال، فهو له ﷺ ينفقه كما يشاء، ومع هذا فقد أنفقه ولم يُبقِ منه إلا قوت سنة لأزواجه رضي الله عنهن. وما أفاء الله على رسوله من أموال أهل القرى التي فُتحت صلحاً فتُقسم فيئاً: لله وللرسول ولذي القربى، وهم بنو هاشم وبنو المطلب، واليتامى، والمساكين، وابن السبيل، كيلا يكون المال متداولاً بين الأغنياء منكم ولا يناله الضعفاء، وما لله ينفق في المصالح العامة، وكذا ما للرسول بعد وفاته ﷺ. وما آتاكم الرسول من مال وغيره فخذوه، وما نهاكم عنه فانتهوا، واتقوا الله فلا تعصوه ولا تعصوا رسوله، فإن الله شديد العقاب.", "h": ["بيان أن مال بني النضير كان فيئاً خاصاً برسول الله ﷺ.", "الفيء، وهو ما حصل عليه المسلمون بدون قتال، وإنما بفرار العدو وتركه، أو بصلح يتم بينه وبين المسلمين، يُقسم على ما ذكر تعالى في هذه الآية؛ وأما الغنائم، وهي ما أُخذ عنوة بالقوة، فإنها تُخمّس: خمس لله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل، والأربعة الأخماس الباقية تُقسم على المجاهدين الذين شاركوا في المعارك.", "وجوب طاعة رسول الله ﷺ وتطبيق أحكامه والاستنان بسننه المؤكدة، وحرمة مخالفته فيما نهى عنه أمته؛ روى الشيخان أن ابن مسعود رضي الله عنه قال: لعن الله الواشمات والمتنمّصات والمتفلّجات للحسن المغيّرات خلق الله، فبلغ ذلك امرأة من بني أسد فقالت: لقد قرأت ما بين لوحي المصحف فما وجدته، قال: إن كنتِ قرأتِه فقد وجدتِه، أما قرأتِ: «وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا»؟ قالت: بلى، قال: فإنه ﷺ قد نهى عنه."], "k": "«وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا»… هل أتعامل مع السنة كأمر أُطيعه، أم كاختيار أنتقي منه؟"}, {"lbl": "الآيات ٨ – ١٠", "q": "لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ ﴿٨﴾ وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٩﴾ وَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ ﴿١٠﴾", "w": [["للفقراء المهاجرين", "الذين أُخرجوا من ديارهم وأموالهم."], ["يبتغون فضلاً من الله ورضواناً", "هاجروا طالبين من الله رزقاً يكفيهم، ورضاً منه."], ["أولئك هم الصادقون", "في إيمانهم، حيث تركوا ديارهم وأموالهم وهاجروا ينصرون الله ورسوله."], ["والذين تبوّؤوا الدار والإيمان", "والأنصار الذين نزلوا المدينة وألفوا الإيمان بعدما اختاروه."], ["من قبلهم", "من قبل المهاجرين."], ["ولا يجدون في صدورهم حاجة", "حسداً ولا غيظاً."], ["مما أوتوا", "مما أُوتي إخوانهم المهاجرون من فيء بني النضير."], ["ويؤثرون على أنفسهم", "في كل شيء، حتى إن الرجل منهم تكون تحته المرأتان فيطلّق إحداهما ليزوّجها مهاجراً."], ["ولو كان بهم خصاصة", "حاجة شديدة وخلّة كبيرة لا يجدون ما يسدّونها به."], ["ومن يوق شحّ نفسه", "ومن يقه الله حرص نفسه على المال والبخل به."], ["والذين جاؤوا من بعدهم", "من بعد المهاجرين والأنصار، من التابعين إلى يومنا هذا."], ["ولا تجعل في قلوبنا غلّاً للذين آمنوا", "حقداً، أي انطواءً على العداوة والبغضاء."]], "m": "ما زال السياق في الحديث عن فيء بني النضير وتوزيع الرسول ﷺ له: إذ أعطاه للمهاجرين ولم يعطِ الأنصار إلا أبا دجانة وسهل بن حنيف لحاجة ذكراها، فتكلّم المنافقون للفتنة وعابوا صنيعه، فأنزل الله هذه الآية: للفقراء المهاجرين الذين أُخرجوا من ديارهم وأموالهم يطلبون رزقاً يكفّ وجوههم عن المسألة، ورضواناً من ربهم لا يعقبه سخط، وينصرون الله ورسوله، أولئك هم الصادقون في إيمانهم، إذ صدّقوا القول بالعمل. وأما الأنصار الذين لم يعطهم المال الزائل وهم في غير حاجة إليه، فقد أعطاهم ما هو خير من المال، واسمع ثناءه عليهم: والذين نزلوا المدينة وبوّؤوا الإيمان قلوبهم وألفوه من قبل نزول المهاجرين إليهم، يحبون من هاجر إليهم من المؤمنين الفارّين بدينهم، ولا يجدون في صدورهم حسداً ولا غيظاً مما أُعطي المهاجرون، ويؤثرونهم على أنفسهم ولو كان بهم حاجة شديدة، وفي السيرة من عجيب إيثارهم أن الرجل يكون تحته امرأتان فيطلّق إحداهما، فإذا انتهت عدتها زوّجها أخاه المهاجر، فهل بعد هذا الإيثار من إيثار؟ ومن يقه الله مرض الشح، وهو البخل بالمال والحرص على جمعه ومنعه، فهو من المفلحين، وقد وقى الأنصار هذا الخطر فهم مفلحون. والذين جاؤوا من بعد المهاجرين والأنصار يقولون في دعائهم الدائم: ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان، وهم المهاجرون والأنصار، ولا تجعل في قلوبنا غلّاً للذين آمنوا بك وبرسولك، ربنا إنك رؤوف رحيم.", "h": ["بيان فضل المهاجرين والأنصار، وأن حبهم إيمان وبغضهم كفران.", "فضيلة الإيثار على النفس.", "فضيلة إيواء المهاجرين الذين هاجروا في سبيل الله فراراً بدينهم، ومساعدتهم على العيش في دار الهجرة.", "خطر الشح، وهو البخل بما وجب إخراجه من المال، والحرص على جمعه.", "بيان طبقات المسلمين ودرجاتهم، وهي ثلاثة بالإجمال: المهاجرون الأولون، والأنصار الذين تبوّؤوا الدار وألفوا الإيمان، ومن جاء بعدهم من التابعين وتابعيهم إلى قيام الساعة من أهل الإيمان والتقوى."], "k": "«ولا تجعل في قلوبنا غلّاً للذين آمنوا»… دعاء أحتاجه كل يوم؛ هل في قلبي الآن غلّ لأحد من المؤمنين؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 406;
insert into public.tdb_cards(topic, i, body) select 406, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١﴾ هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَـٰٓأُوْلِي ٱلۡأَبۡصَٰرِ ﴿٢﴾ وَلَوۡلَآ أَن كَتَبَ ٱللَّهُ عَلَيۡهِمُ ٱلۡجَلَآءَ لَعَذَّبَهُمۡ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابُ ٱلنَّارِ ﴿٣﴾ ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٤﴾ مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ ﴿٥﴾", "w": [["سبّح لله ما في السماوات وما في الأرض", "نزّه الله تعالى وقدّسه بلسان الحال والمقال ما في السماوات وما في الأرض من سائر الكائنات."], ["وهو العزيز الحكيم", "العزيز في انتقامه من أعدائه، الحكيم في تدبيره لأوليائه."], ["هو الذي أخرج الذين كفروا من أهل الكتاب من ديارهم", "أخرج يهود بني النضير من ديارهم بالمدينة."], ["لأول الحشر", "لأول حشر كان، وثاني حشر كان من خيبر إلى الشام."], ["ما ظننتم أن يخرجوا", "ما ظننتم أيها المؤمنون أن بني النضير يخرجون من ديارهم."], ["وظنّوا أنهم مانعتهم حصونهم من الله", "ظنّوا أن حصونهم تمنعهم مما قضى الله به عليهم من إجلائهم."], ["فأتاهم الله من حيث لم يحتسبوا", "فجاءهم الله من حيث لم يظنّوا أنهم يُؤتون منه."], ["وقذف في قلوبهم الرعب", "قذف الله تعالى فيها الخوف الشديد من محمد وأصحابه."], ["يخربون بيوتهم بأيديهم", "حتى لا ينتفع بها المؤمنون، وليأخذوا بعض أبوابها وأخشابها المستحسنة معهم."], ["وأيدي المؤمنين", "إذ كانوا يهدمون عليهم الحصون ليتمكّنوا من قتالهم."], ["فاعتبروا يا أولي الأبصار", "فاتّعظوا بحالهم يا أصحاب العقول، ولا تغترّوا ولا تعتمدوا إلا على الله."], ["ولولا أن كتب الله عليهم الجلاء", "الخروج من المدينة."], ["لعذّبهم في الدنيا", "بالقتل والسبي كما عذّب إخوانهم بني قريظة."], ["ذلك بأنهم شاقّوا الله ورسوله", "جزاهم بما جزاهم به بسبب مخالفتهم لله ورسوله ومعاداتهم لهما."], ["ما قطعتم من لينة أو تركتموها", "ما قطعتم أيها المؤمنون من نخلة أو تركتموها بلا قطع."], ["فبإذن الله وليخزي الفاسقين", "كان بإرادة الله، وليخزي الفاسقين يهود بني النضير."]], "m": "يخبر تعالى عن جلاله وعظمته بأنه سبّحه، أي نزّهه عن كل النقائص من الشريك والصاحبة والولد والعجز، بلسان القال والحال جميع ما في السماوات وما في الأرض من الملائكة والإنس والجن والحيوان والشجر والحجر، وأنه هو العزيز الحكيم. هو الذي أخرج الذين كفروا من ديارهم، يهود بني النضير، أجلاهم من ديارهم بالمدينة لأول الحشر إلى أذرعات بالشام، ومنهم من نزل بخيبر، وسيكون لهم حشر آخر حيث أجلاهم عمر من خيبر إلى الشام. ما ظننتم أيها المؤمنون أن يخرجوا، وظنّوا هم أن حصونهم مانعتهم من الله، فخاب ظنهم، إذ أتاهم أمر الله من حيث لم يظنّوا، بأن قذف في قلوبهم الرعب من الرسول وأصحابه، حتى أصبحوا يخربون بيوتهم بأيديهم وأيدي المؤمنين: المؤمنون يخربونها من الظاهر لفتح البلاد، وهم يخربونها من الباطن، وذلك أن الصلح الذي تمّ أنهم يحملون أموالهم إلا السلاح ويجلون إلى الشام، فكانوا إذا أعجبهم الباب أو الخشبة نزعوها فيخرب البيت لذلك. فاعتبروا يا أولي البصائر بحال بني النضير الأقوياء كيف قذف الله الرعب في قلوبهم، فلا تغترّوا بقواكم، ولكن اعتمدوا على الله وتوكّلوا عليه. ولولا أن كتب الله عليهم الجلاء أزلاً لعذّبهم في الدنيا بالقتل والسبي كما عذّب بني قريظة بعدهم، ولهم في الآخرة عذاب النار، ذلك بأنهم خالفوا الله ورسوله وعادوهما، ومن يشاقّ الله فإن الله شديد العقاب. وما قطعتم من نخلة أو تركتموها قائمة على أصولها فقد كان ذلك بإذن الله فلا إثم عليكم فيه، وأخزى به الفاسقين اليهود.", "h": ["بيان جلال الله وعظمته مع عزه وحكمته في تسبيحه من كل المخلوقات العلوية والسفلية، وفي إجلاء بني النضير من ديارهم، وهو أول حشر لهم.", "بيان أكبر عبرة في خروج بني النضير، وذلك لما كان لهم من قوة، ولما عليه المؤمنون من ضعف، ومع هذا فقد انهزموا وتركوا البلاد والأموال ورحلوا إلى غير رجعة؛ فعلى مثل هذا يتّعظ المتّعظون، فإنه لا قوة تنفع مع قوة الله، فلا يغترّ العقلاء بقواهم المادية، بل عليهم أن يعتمدوا على الله أولاً وآخراً.", "علّة هزيمة بني النضير ليست إلا محادّتهم لله والرسول ومخالفتهم لهما، وهذه سنّته تعالى في كل من يحادّه ويحادّ رسوله، فإنه ينزل به أشد أنواع العقوبات.", "عفو الله تعالى عن المجتهد إذا أخطأ وعدم مؤاخذته؛ فقد اجتهد المؤمنون في قطع نخل بني النضير من أجل إغاظتهم حتى ينزلوا من حصونهم، وقطع النخل المثمر فساد، ولكن الله تعالى لم يؤاخذهم لأنهم مجتهدون."], "k": "«وظنّوا أنهم مانعتهم حصونهم من الله»… على أي حصن أعتمد أنا غير الله؟"}, {"lbl": "الآيتان ٦ – ٧", "q": "وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَآ أَوۡجَفۡتُمۡ عَلَيۡهِ مِنۡ خَيۡلٖ وَلَا رِكَابٖ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٦﴾ مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٧﴾", "w": [["وما أفاء الله على رسوله منهم", "وما ردّ الله ليد رسوله ﷺ من مال بني النضير."], ["فما أوجفتم عليه من خيل ولا ركاب", "لم تسرعوا في طلبه بخيل ولا إبل، ولم تعانوا فيه مشقة."], ["ولكن الله يسلّط رسله على من يشاء", "وقد سلّط رسوله محمداً ﷺ على بني النضير ففتح بلادهم صلحاً."], ["وما أفاء الله على رسوله من أهل القرى", "ما ردّ الله على رسوله من أموال أهل القرى التي لم يُوجف عليها بخيل ولا ركاب."], ["فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل", "لله جزء، وللرسول جزء، ولقرابة الرسول جزء، ولليتامى جزء، وللمساكين جزء، ولابن السبيل جزء، تُقسم بالسوية."], ["كي لا يكون دولة بين الأغنياء منكم", "كيلا يكون المال متداولاً بين الأغنياء الأقوياء ولا يناله الضعفاء والفقراء."], ["وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا", "ما أعطاكم الرسول أو أذن لكم فيه أو أمركم به فخذوه، وما نهاكم عنه وحظره عليكم فانتهوا عنه."], ["واتقوا الله إن الله شديد العقاب", "فلا تعصوه ولا تعصوا رسوله، واحذروا عقوبته."]], "m": "ما زال السياق في غزوة بني النضير؛ بعد الصلح تركوا بساتينهم فيئاً لرسول الله ﷺ، فرغب المسلمون فيها، ورأى بعضهم أنها ستُقسم عليهم كما تُقسم الغنائم، فأبى الله ذلك وقال: وما ردّ الله على رسوله من مال بني النضير، والفيء الظل يتقلّص ثم يرجع؛ وأصل أموالهم لرسول الله ﷺ، لأنهم عاهدوه فأبقى عليهم أموالهم بمقتضى المعاهدة، فلما نقضوا العهد وتآمروا على قتله لم يستحقوا من المال شيئاً. وبداية القضية أن من بنود المعاهدة أن يُسهموا مع الرسول فيما يتحمّل من ديات، فلما قتل عمرو بن أمية الضمري رجلين خطأً، خرج ﷺ إلى بني النضير يطالبهم بالإسهام في الدية، فأنزلوه بأحسن مجلس، ثم خلوا بأنفسهم وقالوا: الفرصة سانحة للتخلّص من الرجل، فجاؤوا برحى من صخرة وطلعوا بها إلى سطح المنزل، وهمّوا أن يسقطوها على رأسه ﷺ وهو جالس في ظل الجدار، فأوحى الله إليه أن قم من مكانك، فقام على الفور، ثم أعلن الخروج إليهم لنقضهم العهد، فحاصرهم، وانتهى الأمر بصلح يقضي بأن يجلوا عن المدينة يحملون أموالهم على إبلهم دون السلاح. فما أوجفتم على أموالهم خيلاً ولا إبلاً، لأنهم في طرف المدينة، فلم تتحمّلوا سفراً ولا قتالاً، فلذا لا حقّ لكم فيها، فإنها فيء وليست بغنيمة، ولكن الله يسلّط رسله على من يشاء بدون قتال، فهو له ﷺ ينفقه كما يشاء، ومع هذا فقد أنفقه ولم يُبقِ منه إلا قوت سنة لأزواجه رضي الله عنهن. وما أفاء الله على رسوله من أموال أهل القرى التي فُتحت صلحاً فتُقسم فيئاً: لله وللرسول ولذي القربى، وهم بنو هاشم وبنو المطلب، واليتامى، والمساكين، وابن السبيل، كيلا يكون المال متداولاً بين الأغنياء منكم ولا يناله الضعفاء، وما لله ينفق في المصالح العامة، وكذا ما للرسول بعد وفاته ﷺ. وما آتاكم الرسول من مال وغيره فخذوه، وما نهاكم عنه فانتهوا، واتقوا الله فلا تعصوه ولا تعصوا رسوله، فإن الله شديد العقاب.", "h": ["بيان أن مال بني النضير كان فيئاً خاصاً برسول الله ﷺ.", "الفيء، وهو ما حصل عليه المسلمون بدون قتال، وإنما بفرار العدو وتركه، أو بصلح يتم بينه وبين المسلمين، يُقسم على ما ذكر تعالى في هذه الآية؛ وأما الغنائم، وهي ما أُخذ عنوة بالقوة، فإنها تُخمّس: خمس لله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل، والأربعة الأخماس الباقية تُقسم على المجاهدين الذين شاركوا في المعارك.", "وجوب طاعة رسول الله ﷺ وتطبيق أحكامه والاستنان بسننه المؤكدة، وحرمة مخالفته فيما نهى عنه أمته؛ روى الشيخان أن ابن مسعود رضي الله عنه قال: لعن الله الواشمات والمتنمّصات والمتفلّجات للحسن المغيّرات خلق الله، فبلغ ذلك امرأة من بني أسد فقالت: لقد قرأت ما بين لوحي المصحف فما وجدته، قال: إن كنتِ قرأتِه فقد وجدتِه، أما قرأتِ: «وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا»؟ قالت: بلى، قال: فإنه ﷺ قد نهى عنه."], "k": "«وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا»… هل أتعامل مع السنة كأمر أُطيعه، أم كاختيار أنتقي منه؟"}, {"lbl": "الآيات ٨ – ١٠", "q": "لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ ﴿٨﴾ وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٩﴾ وَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ ﴿١٠﴾", "w": [["للفقراء المهاجرين", "الذين أُخرجوا من ديارهم وأموالهم."], ["يبتغون فضلاً من الله ورضواناً", "هاجروا طالبين من الله رزقاً يكفيهم، ورضاً منه."], ["أولئك هم الصادقون", "في إيمانهم، حيث تركوا ديارهم وأموالهم وهاجروا ينصرون الله ورسوله."], ["والذين تبوّؤوا الدار والإيمان", "والأنصار الذين نزلوا المدينة وألفوا الإيمان بعدما اختاروه."], ["من قبلهم", "من قبل المهاجرين."], ["ولا يجدون في صدورهم حاجة", "حسداً ولا غيظاً."], ["مما أوتوا", "مما أُوتي إخوانهم المهاجرون من فيء بني النضير."], ["ويؤثرون على أنفسهم", "في كل شيء، حتى إن الرجل منهم تكون تحته المرأتان فيطلّق إحداهما ليزوّجها مهاجراً."], ["ولو كان بهم خصاصة", "حاجة شديدة وخلّة كبيرة لا يجدون ما يسدّونها به."], ["ومن يوق شحّ نفسه", "ومن يقه الله حرص نفسه على المال والبخل به."], ["والذين جاؤوا من بعدهم", "من بعد المهاجرين والأنصار، من التابعين إلى يومنا هذا."], ["ولا تجعل في قلوبنا غلّاً للذين آمنوا", "حقداً، أي انطواءً على العداوة والبغضاء."]], "m": "ما زال السياق في الحديث عن فيء بني النضير وتوزيع الرسول ﷺ له: إذ أعطاه للمهاجرين ولم يعطِ الأنصار إلا أبا دجانة وسهل بن حنيف لحاجة ذكراها، فتكلّم المنافقون للفتنة وعابوا صنيعه، فأنزل الله هذه الآية: للفقراء المهاجرين الذين أُخرجوا من ديارهم وأموالهم يطلبون رزقاً يكفّ وجوههم عن المسألة، ورضواناً من ربهم لا يعقبه سخط، وينصرون الله ورسوله، أولئك هم الصادقون في إيمانهم، إذ صدّقوا القول بالعمل. وأما الأنصار الذين لم يعطهم المال الزائل وهم في غير حاجة إليه، فقد أعطاهم ما هو خير من المال، واسمع ثناءه عليهم: والذين نزلوا المدينة وبوّؤوا الإيمان قلوبهم وألفوه من قبل نزول المهاجرين إليهم، يحبون من هاجر إليهم من المؤمنين الفارّين بدينهم، ولا يجدون في صدورهم حسداً ولا غيظاً مما أُعطي المهاجرون، ويؤثرونهم على أنفسهم ولو كان بهم حاجة شديدة، وفي السيرة من عجيب إيثارهم أن الرجل يكون تحته امرأتان فيطلّق إحداهما، فإذا انتهت عدتها زوّجها أخاه المهاجر، فهل بعد هذا الإيثار من إيثار؟ ومن يقه الله مرض الشح، وهو البخل بالمال والحرص على جمعه ومنعه، فهو من المفلحين، وقد وقى الأنصار هذا الخطر فهم مفلحون. والذين جاؤوا من بعد المهاجرين والأنصار يقولون في دعائهم الدائم: ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان، وهم المهاجرون والأنصار، ولا تجعل في قلوبنا غلّاً للذين آمنوا بك وبرسولك، ربنا إنك رؤوف رحيم.", "h": ["بيان فضل المهاجرين والأنصار، وأن حبهم إيمان وبغضهم كفران.", "فضيلة الإيثار على النفس.", "فضيلة إيواء المهاجرين الذين هاجروا في سبيل الله فراراً بدينهم، ومساعدتهم على العيش في دار الهجرة.", "خطر الشح، وهو البخل بما وجب إخراجه من المال، والحرص على جمعه.", "بيان طبقات المسلمين ودرجاتهم، وهي ثلاثة بالإجمال: المهاجرون الأولون، والأنصار الذين تبوّؤوا الدار وألفوا الإيمان، ومن جاء بعدهم من التابعين وتابعيهم إلى قيام الساعة من أهل الإيمان والتقوى."], "k": "«ولا تجعل في قلوبنا غلّاً للذين آمنوا»… دعاء أحتاجه كل يوم؛ هل في قلبي الآن غلّ لأحد من المؤمنين؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (407, 59, 11, 24, 'سورة الحشر ١١ – ٢٤', 'الحشر: ولتنظر نفس ما قدّمت لغد', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 407) = $j$[{"lbl": "الآيات ١١ – ١٤", "q": "۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نَافَقُواْ يَقُولُونَ لِإِخۡوَٰنِهِمُ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَئِنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِيعُ فِيكُمۡ أَحَدًا أَبَدٗا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ ﴿١١﴾ لَئِنۡ أُخۡرِجُواْ لَا يَخۡرُجُونَ مَعَهُمۡ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمۡ وَلَئِن نَّصَرُوهُمۡ لَيُوَلُّنَّ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يُنصَرُونَ ﴿١٢﴾ لَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ﴿١٣﴾ لَا يُقَٰتِلُونَكُمۡ جَمِيعًا إِلَّا فِي قُرٗى مُّحَصَّنَةٍ أَوۡ مِن وَرَآءِ جُدُرِۭۚ بَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ﴿١٤﴾", "w": [["ألم تر إلى الذين نافقوا", "ألم تنظر إلى الذين أظهروا الإيمان وأخفوا في نفوسهم الكفر؟"], ["يقولون لإخوانهم الذين كفروا من أهل الكتاب", "يهود بني النضير."], ["لئن أُخرجتم لنخرجنّ معكم", "لئن أُخرجتم من دياركم بالمدينة نخرج معكم ولا نبقى بعدكم."], ["وإن قوتلتم لننصرنّكم", "إن قاتلكم محمد ﷺ وأصحابه لننصرنّكم بالرجال والسلاح."], ["والله يشهد إنهم لكاذبون", "فيما وعدوا به إخوانهم من بني النضير."], ["ولئن نصروهم ليولّنّ الأدبار", "وعلى فرض أنهم نصروهم ليولّنّ الأدبار، ثم لا يُنصر المنافقون واليهود."], ["لأنتم أشد رهبة في صدورهم من الله", "تالله لأنتم أشد خوفاً في صدورهم من الله، لأن الله يؤخّر عذابهم وأنتم تعجّلونه لهم."], ["ذلك بأنهم قوم لا يفقهون", "لظلمة كفرهم وعدم استعدادهم للفهم عن الله ورسوله."], ["لا يقاتلونكم جميعاً", "لا يقاتلكم يهود بني النضير مجتمعين."], ["إلا في قرى محصّنة", "بالأسوار العالية."], ["أو من وراء جُدُر", "من وراء المباني والجدران، أما المواجهة فلا يقدرون عليها."], ["بأسهم بينهم شديد", "العداوة بينهم شديدة، والبغضاء أشد."], ["تحسبهم جميعاً وقلوبهم شتّى", "تحسبهم مجتمعين، وقلوبهم متفرقة خلاف ما تحسبهم عليه."], ["ذلك بأنهم قوم لا يعقلون", "إذ لو كانوا يعقلون لاجتمعوا على الحق."]], "m": "ما زال السياق في الحديث عن غزوة بني النضير: ألم تنظر يا رسولنا إلى الذين نافقوا، وهم عبد الله بن أُبيّ بن سلول وجماعة معه، إذ بعثوا إلى بني النضير حين نزل بساحتهم رسول الله ﷺ لحربهم: أن اثبتوا وتمنّعوا، فإن قوتلتم قاتلنا معكم، وإن أُخرجتم خرجنا معكم، غير أنهم لم يفوا لهم، ولم يأتهم منهم أحد، وقذف الله الرعب في قلوب اليهود فسألوا رسول الله ﷺ أن يجليهم ويكفّ عن دمائهم على أن لهم ما حملت الإبل من أموالهم إلا السلاح. والله يشهد إنهم لكاذبون فيما قالوا لهم، وفعلاً لم يقاتلوا معهم ولم يخرجوا معهم، وعلى فرض أنهم نصروهم ليولّنّ الأدبار هاربين، ثم لا يُنصر اليهود ولا المنافقون. لأنتم أشد رهبة في صدور المنافقين من الله، لأنهم يرون أن الله يؤجّل عذابهم، وأما المؤمنون فيأخذونهم بسرعة إذا أعلنوا عن كفرهم. ذلك بيان لجبنهم وخوفهم الشديد من الرسول ﷺ والمؤمنين، إذ لو كانوا يفقهون لما خافوا العبد ولم يخافوا المعبود. لا يقاتلكم اليهود والمنافقون مجتمعين إلا في قرى محصّنة بأسوار وحصون أو من وراء الجدران، العداوة بينهم قوية والبغضاء شديدة، تحسبهم في الظاهر مجتمعين لكن قلوبهم متفرقة لا تجتمع على غير عداوة الإسلام وأهله، وذلك لكثرة أطماعهم وأغراضهم وأنانيتهم، ذلك بأنهم قوم لا يعقلون، إذ لو كانوا يعقلون لما حاربوا الحق وكفروا به وهم يعلمون.", "h": ["تقرير حقيقة، وهي أن الكفر ملة واحدة، وأن الكافرين إخوان.", "خلف الوعد آية النفاق وعلامته البارزة.", "الجبن والخوف صفة من صفات اليهود اللازمة لهم، لا تنفكّ عنهم.", "عامة الكفار يبدون متحدين ضد الإسلام، وهم كذلك، ولكنهم فيما بينهم تمزّقهم العداوات وتقطّعهم الأطماع وسوء الأغراض والنيات."], "k": "«لأنتم أشد رهبة في صدورهم من الله»… هل أخاف من نظرة الناس أكثر مما أخاف من نظر الله إليّ؟"}, {"lbl": "الآيات ١٥ – ٢٠", "q": "كَمَثَلِ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَرِيبٗاۖ ذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١٥﴾ كَمَثَلِ ٱلشَّيۡطَٰنِ إِذۡ قَالَ لِلۡإِنسَٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيٓءٞ مِّنكَ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ ﴿١٦﴾ فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِي ٱلنَّارِ خَٰلِدَيۡنِ فِيهَاۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ ﴿١٧﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٨﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿١٩﴾ لَا يَسۡتَوِيٓ أَصۡحَٰبُ ٱلنَّارِ وَأَصۡحَٰبُ ٱلۡجَنَّةِۚ أَصۡحَٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَآئِزُونَ ﴿٢٠﴾", "w": [["كمثل الذين من قبلهم قريباً", "مثل يهود بني النضير في ترك الإيمان ومحاربة الرسول ﷺ كمثل إخوانهم بني قينقاع."], ["ذاقوا وبال أمرهم ولهم عذاب أليم", "ذاقوا عاقبة كفرهم وحربهم لرسول الله، ولهم عذاب أليم في الآخرة."], ["كمثل الشيطان إذ قال للإنسان اكفر", "ومثلهم أيضاً في سماعهم من المنافقين وخذلانهم لهم كمثل الشيطان إذ قال للإنسان: اكفر."], ["فلما كفر قال إني بريء منك", "قال له الشيطان بعد أن كفّره: إني بريء منك."], ["وذلك جزاء الظالمين", "خلودهما في النار، الغاوي والمغوي، ذلك جزاؤهما وجزاء الظالمين."], ["ولتنظر نفس ما قدّمت لغد", "لينظر كل أحد ما قدّم ليوم القيامة من خير وشر."], ["ولا تكونوا كالذين نسوا الله", "ولا تكونوا أيها المؤمنون كالذين نسوا الله فتركوا طاعته."], ["فأنساهم أنفسهم", "فعاقبهم بأن أنساهم أنفسهم فلم يعملوا لها خيراً قط."], ["لا يستوي أصحاب النار وأصحاب الجنة", "أصحاب الجنة فائزون بالسلامة من المرهوب والظفر بالمرغوب، وأصحاب النار خاسرون، فكيف يستويان؟"]], "m": "هذه الآيات في بقية الحديث عن بني النضير: مثلهم في هزيمتهم بعد نقضهم العهد كمثل الذين من قبلهم قريباً في الزمان والمكان، وهم بنو قينقاع، إذ نقضوا عهدهم فأخرجهم رسول الله ﷺ، فذاقوا عاقبة نقضهم وكفرهم في الدنيا، ولهم في الآخرة عذاب أليم. ومثلهم مع المنافقين كمثل الشيطان إذ قال للإنسان: اكفر بوسائله الخاصة، فلما كفر الإنسان تبرّأ منه الشيطان وقال: إني بريء منك إني أخاف الله رب العالمين؛ كذلك حال بني النضير مع المنافقين، حرّضوهم على الحرب وواعدوهم أن يكونوا معهم ثم خذلوهم. فكان عاقبة الإنسان والشيطان أنهما في النار خالدين فيها، وذلك جزاء الظالمين. وبعد نهاية قصة بني النضير نادى تعالى المؤمنين ليوجّههم: يا أيها الذين آمنوا اتقوا الله بفعل أوامره واجتناب نواهيه، ولينظر أحدكم في خاصة نفسه ماذا قدّم لغد، أي ليوم القيامة، واتقوا الله، أعاد الأمر بالتقوى لأن التقوى ملاك الأمر ومفتاح دار السلام، إن الله خبير بما تعملون، يشجّعهم على مراقبته. ولا تكونوا كأناس تركوا العمل بطاعة الله وطاعة رسوله فعاقبهم ربهم بأن أنساهم أنفسهم فلم يعملوا لها خيراً، وأصبحوا بذلك فاسقين. لا يستوي أصحاب النار في الدركات السفلى وأصحاب الجنة في الفراديس العلا، إذ أصحاب الجنة فائزون، وأصحاب النار خاسرون.", "h": ["ضرب مثل لحال الكافرين في عدم الاتعاظ بحال غيرهم.", "التحذير من سبل الشيطان، وهي الإغراء بالمعاصي وتزيينها، فإذا وقع العبد في الهلكة تبرّأ الشيطان منه وتركه في محنته وعذابه.", "وجوب التقوى بفعل الأوامر وترك النواهي.", "وجوب مراقبة الله تعالى، والنظر يومياً فيما قدّم الإنسان للآخرة وما أخّر.", "التحذير من نسيان الله تعالى المقتضي لعصيانه، فإن عقوبته خطيرة، وهي أن يُنسي الله العبد نفسه فلا يقدّم لها خيراً قط، فيهلك ويخسر خسراناً مبيناً.", "عدم التساوي بين أهل النار وأهل الجنة؛ إذ أصحاب النار لم ينجوا من المرهوب وهو النار، ولم يظفروا بالمرغوب وهو الجنة، وأصحاب الجنة على العكس."], "k": "«ولتنظر نفس ما قدّمت لغد»… قبل أن أنام الليلة: ماذا قدّمت اليوم لغدي؟"}, {"lbl": "الآيات ٢١ – ٢٤", "q": "لَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ ٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ يَتَفَكَّرُونَ ﴿٢١﴾ هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ ﴿٢٢﴾ هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَيۡمِنُ ٱلۡعَزِيزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ ﴿٢٣﴾ هُوَ ٱللَّهُ ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ يُسَبِّحُ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٤﴾", "w": [["لو أنزلنا هذا القرآن على جبل", "وجعلنا فيه تمييزاً وعقلاً وإدراكاً."], ["لرأيته خاشعاً متصدّعاً", "لرأيت ذلك الجبل متشقّقاً متطامناً ذليلاً."], ["من خشية الله", "من خوف الله، خشية ألا يكون أدّى حقه من التعظيم."], ["وتلك الأمثال نضربها للناس", "مثل هذا المثل نضرب الأمثال للناس."], ["لعلهم يتفكّرون", "فيؤمنون ويوحّدون ويطيعون."], ["هو الله الذي لا إله إلا هو", "المعبود بحق الذي لا معبود بحق إلا هو عز وجل."], ["عالم الغيب والشهادة", "عالم السر والعلانية."], ["هو الرحمن الرحيم", "رحمن الدنيا والآخرة ورحيمهما."], ["الملك القدّوس", "الذي يملك كل شيء ويحكم كل شيء، الطاهر المنزّه عما لا يليق به."], ["السلام المؤمن المهيمن", "ذو السلامة من كل نقص، المصدّق رسله بالمعجزات، الرقيب الشهيد على عباده بأعمالهم."], ["العزيز الجبّار المتكبّر", "العزيز في انتقامه، الجبّار لغيره على مراده، المتكبّر على خلقه."], ["سبحان الله عما يشركون", "تنزيهاً لله تعالى عما يشركون من الآلهة الباطلة."], ["هو الله الخالق البارئ المصوّر", "الخالق لكل المخلوقات، المنشئ لها، مصوّرها ومركّبها على هيئات مختلفة."], ["له الأسماء الحسنى", "تسعة وتسعون اسماً، كلها حسنى في غاية الحسن."], ["يسبّح له ما في السماوات والأرض", "ينزّهه بلسان القال والحال جميع ما في السماوات والأرض."], ["وهو العزيز الحكيم", "الغالب على أمره، الحكيم في جميع تدبيره."]], "m": "لما أمر تعالى في الآيات السابقة ونهى ووعظ وذكّر بما لا مزيد عليه، أخبر أنه لو أنزل هذا القرآن العظيم على جبل بعد أن خلق فيه إدراكاً وتمييزاً كما خلق ذلك في الإنسان، لرأيت ذلك الجبل خاشعاً ذليلاً متصدّعاً من الخوف من الله، لعله قصّر في حق الله وحق كتابه؛ وفي هذا موعظة للمؤمنين ليتدبّروا القرآن ويخشعوا عند تلاوته وسماعه. وما ضرب من أمثال في القرآن، ومنها هذا المثل، يجعلها للناس رجاء أن يتفكّروا فيؤمنوا ويهتدوا. ثم أخبر تعالى عن جلاله وكماله بذكر أسمائه وصفاته: هو الله الذي لا معبود بحق إلا هو، عالم الغيب والشهادة: السر والعلن والموجود والمعدوم، هو الرحمن الذي وسعت رحمته كل شيء، الرحيم بعباده المؤمنين، الملك الذي له ملك السماوات والأرض، القدّوس الطاهر المنزّه عن كل نقص وعيب، السلام ذو السلامة من كل نقص المفيض السلام على من يشاء من عباده، المؤمن المصدّق رسله بما آتاهم من المعجزات، المصدّق عباده المؤمنين، المهيمن على خلقه الرقيب عليهم، لا يخرج شيء من أعمالهم عن إرادته وإذنه، العزيز الغالب على أمره، الجبّار للكل على مراده، المتكبّر على كل خلقه، وله الكبرياء في السماوات والأرض. سبحان الله عما يشركون، نزّه تعالى نفسه عما يشرك به المشركون. هو الله الخالق المقدّر للخلق، البارئ له، المصوّر له في الصورة التي أراد، له الأسماء الحسنى، وهي مائة اسم إلا اسماً واحداً كما أخبر رسول الله ﷺ في صحيح البخاري، وأسماؤه متضمّنة صفاته، وكل أسمائه حسنى وكل صفاته عليا، يسبّح له ما في السماوات والأرض، وهو العزيز الحكيم.", "h": ["بيان ما حواه القرآن من العظات والعبر والأمر والنهي والوعد والوعيد، الأمر الذي لو أن جبلاً رُكّب فيه الإدراك والتمييز كالإنسان ونزل عليه القرآن لخشع وتصدّع من خشية الله.", "استحسان ضرب الأمثال للتنبيه والتعليم والإرشاد.", "تقرير التوحيد، وأنه لا إله إلا الله وأن محمداً رسول الله.", "إثبات أسماء الله تعالى، وأنها كلها حسنى، وأنها متضمّنة صفات عليا.", "ذكر أسمائه تعالى تعليم لعباده بها ليدعوه بها ويتوسّلوا بها إليه."], "k": "«لرأيته خاشعاً متصدّعاً من خشية الله»… الجبل لو عقله لتصدّع، وقلبي يسمعه فلا يتحرّك؛ فأين الخلل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 407;
insert into public.tdb_cards(topic, i, body) select 407, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١ – ١٤", "q": "۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نَافَقُواْ يَقُولُونَ لِإِخۡوَٰنِهِمُ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَئِنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِيعُ فِيكُمۡ أَحَدًا أَبَدٗا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ ﴿١١﴾ لَئِنۡ أُخۡرِجُواْ لَا يَخۡرُجُونَ مَعَهُمۡ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمۡ وَلَئِن نَّصَرُوهُمۡ لَيُوَلُّنَّ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يُنصَرُونَ ﴿١٢﴾ لَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ﴿١٣﴾ لَا يُقَٰتِلُونَكُمۡ جَمِيعًا إِلَّا فِي قُرٗى مُّحَصَّنَةٍ أَوۡ مِن وَرَآءِ جُدُرِۭۚ بَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ﴿١٤﴾", "w": [["ألم تر إلى الذين نافقوا", "ألم تنظر إلى الذين أظهروا الإيمان وأخفوا في نفوسهم الكفر؟"], ["يقولون لإخوانهم الذين كفروا من أهل الكتاب", "يهود بني النضير."], ["لئن أُخرجتم لنخرجنّ معكم", "لئن أُخرجتم من دياركم بالمدينة نخرج معكم ولا نبقى بعدكم."], ["وإن قوتلتم لننصرنّكم", "إن قاتلكم محمد ﷺ وأصحابه لننصرنّكم بالرجال والسلاح."], ["والله يشهد إنهم لكاذبون", "فيما وعدوا به إخوانهم من بني النضير."], ["ولئن نصروهم ليولّنّ الأدبار", "وعلى فرض أنهم نصروهم ليولّنّ الأدبار، ثم لا يُنصر المنافقون واليهود."], ["لأنتم أشد رهبة في صدورهم من الله", "تالله لأنتم أشد خوفاً في صدورهم من الله، لأن الله يؤخّر عذابهم وأنتم تعجّلونه لهم."], ["ذلك بأنهم قوم لا يفقهون", "لظلمة كفرهم وعدم استعدادهم للفهم عن الله ورسوله."], ["لا يقاتلونكم جميعاً", "لا يقاتلكم يهود بني النضير مجتمعين."], ["إلا في قرى محصّنة", "بالأسوار العالية."], ["أو من وراء جُدُر", "من وراء المباني والجدران، أما المواجهة فلا يقدرون عليها."], ["بأسهم بينهم شديد", "العداوة بينهم شديدة، والبغضاء أشد."], ["تحسبهم جميعاً وقلوبهم شتّى", "تحسبهم مجتمعين، وقلوبهم متفرقة خلاف ما تحسبهم عليه."], ["ذلك بأنهم قوم لا يعقلون", "إذ لو كانوا يعقلون لاجتمعوا على الحق."]], "m": "ما زال السياق في الحديث عن غزوة بني النضير: ألم تنظر يا رسولنا إلى الذين نافقوا، وهم عبد الله بن أُبيّ بن سلول وجماعة معه، إذ بعثوا إلى بني النضير حين نزل بساحتهم رسول الله ﷺ لحربهم: أن اثبتوا وتمنّعوا، فإن قوتلتم قاتلنا معكم، وإن أُخرجتم خرجنا معكم، غير أنهم لم يفوا لهم، ولم يأتهم منهم أحد، وقذف الله الرعب في قلوب اليهود فسألوا رسول الله ﷺ أن يجليهم ويكفّ عن دمائهم على أن لهم ما حملت الإبل من أموالهم إلا السلاح. والله يشهد إنهم لكاذبون فيما قالوا لهم، وفعلاً لم يقاتلوا معهم ولم يخرجوا معهم، وعلى فرض أنهم نصروهم ليولّنّ الأدبار هاربين، ثم لا يُنصر اليهود ولا المنافقون. لأنتم أشد رهبة في صدور المنافقين من الله، لأنهم يرون أن الله يؤجّل عذابهم، وأما المؤمنون فيأخذونهم بسرعة إذا أعلنوا عن كفرهم. ذلك بيان لجبنهم وخوفهم الشديد من الرسول ﷺ والمؤمنين، إذ لو كانوا يفقهون لما خافوا العبد ولم يخافوا المعبود. لا يقاتلكم اليهود والمنافقون مجتمعين إلا في قرى محصّنة بأسوار وحصون أو من وراء الجدران، العداوة بينهم قوية والبغضاء شديدة، تحسبهم في الظاهر مجتمعين لكن قلوبهم متفرقة لا تجتمع على غير عداوة الإسلام وأهله، وذلك لكثرة أطماعهم وأغراضهم وأنانيتهم، ذلك بأنهم قوم لا يعقلون، إذ لو كانوا يعقلون لما حاربوا الحق وكفروا به وهم يعلمون.", "h": ["تقرير حقيقة، وهي أن الكفر ملة واحدة، وأن الكافرين إخوان.", "خلف الوعد آية النفاق وعلامته البارزة.", "الجبن والخوف صفة من صفات اليهود اللازمة لهم، لا تنفكّ عنهم.", "عامة الكفار يبدون متحدين ضد الإسلام، وهم كذلك، ولكنهم فيما بينهم تمزّقهم العداوات وتقطّعهم الأطماع وسوء الأغراض والنيات."], "k": "«لأنتم أشد رهبة في صدورهم من الله»… هل أخاف من نظرة الناس أكثر مما أخاف من نظر الله إليّ؟"}, {"lbl": "الآيات ١٥ – ٢٠", "q": "كَمَثَلِ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَرِيبٗاۖ ذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١٥﴾ كَمَثَلِ ٱلشَّيۡطَٰنِ إِذۡ قَالَ لِلۡإِنسَٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيٓءٞ مِّنكَ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ ﴿١٦﴾ فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِي ٱلنَّارِ خَٰلِدَيۡنِ فِيهَاۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ ﴿١٧﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٨﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿١٩﴾ لَا يَسۡتَوِيٓ أَصۡحَٰبُ ٱلنَّارِ وَأَصۡحَٰبُ ٱلۡجَنَّةِۚ أَصۡحَٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَآئِزُونَ ﴿٢٠﴾", "w": [["كمثل الذين من قبلهم قريباً", "مثل يهود بني النضير في ترك الإيمان ومحاربة الرسول ﷺ كمثل إخوانهم بني قينقاع."], ["ذاقوا وبال أمرهم ولهم عذاب أليم", "ذاقوا عاقبة كفرهم وحربهم لرسول الله، ولهم عذاب أليم في الآخرة."], ["كمثل الشيطان إذ قال للإنسان اكفر", "ومثلهم أيضاً في سماعهم من المنافقين وخذلانهم لهم كمثل الشيطان إذ قال للإنسان: اكفر."], ["فلما كفر قال إني بريء منك", "قال له الشيطان بعد أن كفّره: إني بريء منك."], ["وذلك جزاء الظالمين", "خلودهما في النار، الغاوي والمغوي، ذلك جزاؤهما وجزاء الظالمين."], ["ولتنظر نفس ما قدّمت لغد", "لينظر كل أحد ما قدّم ليوم القيامة من خير وشر."], ["ولا تكونوا كالذين نسوا الله", "ولا تكونوا أيها المؤمنون كالذين نسوا الله فتركوا طاعته."], ["فأنساهم أنفسهم", "فعاقبهم بأن أنساهم أنفسهم فلم يعملوا لها خيراً قط."], ["لا يستوي أصحاب النار وأصحاب الجنة", "أصحاب الجنة فائزون بالسلامة من المرهوب والظفر بالمرغوب، وأصحاب النار خاسرون، فكيف يستويان؟"]], "m": "هذه الآيات في بقية الحديث عن بني النضير: مثلهم في هزيمتهم بعد نقضهم العهد كمثل الذين من قبلهم قريباً في الزمان والمكان، وهم بنو قينقاع، إذ نقضوا عهدهم فأخرجهم رسول الله ﷺ، فذاقوا عاقبة نقضهم وكفرهم في الدنيا، ولهم في الآخرة عذاب أليم. ومثلهم مع المنافقين كمثل الشيطان إذ قال للإنسان: اكفر بوسائله الخاصة، فلما كفر الإنسان تبرّأ منه الشيطان وقال: إني بريء منك إني أخاف الله رب العالمين؛ كذلك حال بني النضير مع المنافقين، حرّضوهم على الحرب وواعدوهم أن يكونوا معهم ثم خذلوهم. فكان عاقبة الإنسان والشيطان أنهما في النار خالدين فيها، وذلك جزاء الظالمين. وبعد نهاية قصة بني النضير نادى تعالى المؤمنين ليوجّههم: يا أيها الذين آمنوا اتقوا الله بفعل أوامره واجتناب نواهيه، ولينظر أحدكم في خاصة نفسه ماذا قدّم لغد، أي ليوم القيامة، واتقوا الله، أعاد الأمر بالتقوى لأن التقوى ملاك الأمر ومفتاح دار السلام، إن الله خبير بما تعملون، يشجّعهم على مراقبته. ولا تكونوا كأناس تركوا العمل بطاعة الله وطاعة رسوله فعاقبهم ربهم بأن أنساهم أنفسهم فلم يعملوا لها خيراً، وأصبحوا بذلك فاسقين. لا يستوي أصحاب النار في الدركات السفلى وأصحاب الجنة في الفراديس العلا، إذ أصحاب الجنة فائزون، وأصحاب النار خاسرون.", "h": ["ضرب مثل لحال الكافرين في عدم الاتعاظ بحال غيرهم.", "التحذير من سبل الشيطان، وهي الإغراء بالمعاصي وتزيينها، فإذا وقع العبد في الهلكة تبرّأ الشيطان منه وتركه في محنته وعذابه.", "وجوب التقوى بفعل الأوامر وترك النواهي.", "وجوب مراقبة الله تعالى، والنظر يومياً فيما قدّم الإنسان للآخرة وما أخّر.", "التحذير من نسيان الله تعالى المقتضي لعصيانه، فإن عقوبته خطيرة، وهي أن يُنسي الله العبد نفسه فلا يقدّم لها خيراً قط، فيهلك ويخسر خسراناً مبيناً.", "عدم التساوي بين أهل النار وأهل الجنة؛ إذ أصحاب النار لم ينجوا من المرهوب وهو النار، ولم يظفروا بالمرغوب وهو الجنة، وأصحاب الجنة على العكس."], "k": "«ولتنظر نفس ما قدّمت لغد»… قبل أن أنام الليلة: ماذا قدّمت اليوم لغدي؟"}, {"lbl": "الآيات ٢١ – ٢٤", "q": "لَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ ٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ يَتَفَكَّرُونَ ﴿٢١﴾ هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ ﴿٢٢﴾ هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَيۡمِنُ ٱلۡعَزِيزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ ﴿٢٣﴾ هُوَ ٱللَّهُ ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ يُسَبِّحُ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٤﴾", "w": [["لو أنزلنا هذا القرآن على جبل", "وجعلنا فيه تمييزاً وعقلاً وإدراكاً."], ["لرأيته خاشعاً متصدّعاً", "لرأيت ذلك الجبل متشقّقاً متطامناً ذليلاً."], ["من خشية الله", "من خوف الله، خشية ألا يكون أدّى حقه من التعظيم."], ["وتلك الأمثال نضربها للناس", "مثل هذا المثل نضرب الأمثال للناس."], ["لعلهم يتفكّرون", "فيؤمنون ويوحّدون ويطيعون."], ["هو الله الذي لا إله إلا هو", "المعبود بحق الذي لا معبود بحق إلا هو عز وجل."], ["عالم الغيب والشهادة", "عالم السر والعلانية."], ["هو الرحمن الرحيم", "رحمن الدنيا والآخرة ورحيمهما."], ["الملك القدّوس", "الذي يملك كل شيء ويحكم كل شيء، الطاهر المنزّه عما لا يليق به."], ["السلام المؤمن المهيمن", "ذو السلامة من كل نقص، المصدّق رسله بالمعجزات، الرقيب الشهيد على عباده بأعمالهم."], ["العزيز الجبّار المتكبّر", "العزيز في انتقامه، الجبّار لغيره على مراده، المتكبّر على خلقه."], ["سبحان الله عما يشركون", "تنزيهاً لله تعالى عما يشركون من الآلهة الباطلة."], ["هو الله الخالق البارئ المصوّر", "الخالق لكل المخلوقات، المنشئ لها، مصوّرها ومركّبها على هيئات مختلفة."], ["له الأسماء الحسنى", "تسعة وتسعون اسماً، كلها حسنى في غاية الحسن."], ["يسبّح له ما في السماوات والأرض", "ينزّهه بلسان القال والحال جميع ما في السماوات والأرض."], ["وهو العزيز الحكيم", "الغالب على أمره، الحكيم في جميع تدبيره."]], "m": "لما أمر تعالى في الآيات السابقة ونهى ووعظ وذكّر بما لا مزيد عليه، أخبر أنه لو أنزل هذا القرآن العظيم على جبل بعد أن خلق فيه إدراكاً وتمييزاً كما خلق ذلك في الإنسان، لرأيت ذلك الجبل خاشعاً ذليلاً متصدّعاً من الخوف من الله، لعله قصّر في حق الله وحق كتابه؛ وفي هذا موعظة للمؤمنين ليتدبّروا القرآن ويخشعوا عند تلاوته وسماعه. وما ضرب من أمثال في القرآن، ومنها هذا المثل، يجعلها للناس رجاء أن يتفكّروا فيؤمنوا ويهتدوا. ثم أخبر تعالى عن جلاله وكماله بذكر أسمائه وصفاته: هو الله الذي لا معبود بحق إلا هو، عالم الغيب والشهادة: السر والعلن والموجود والمعدوم، هو الرحمن الذي وسعت رحمته كل شيء، الرحيم بعباده المؤمنين، الملك الذي له ملك السماوات والأرض، القدّوس الطاهر المنزّه عن كل نقص وعيب، السلام ذو السلامة من كل نقص المفيض السلام على من يشاء من عباده، المؤمن المصدّق رسله بما آتاهم من المعجزات، المصدّق عباده المؤمنين، المهيمن على خلقه الرقيب عليهم، لا يخرج شيء من أعمالهم عن إرادته وإذنه، العزيز الغالب على أمره، الجبّار للكل على مراده، المتكبّر على كل خلقه، وله الكبرياء في السماوات والأرض. سبحان الله عما يشركون، نزّه تعالى نفسه عما يشرك به المشركون. هو الله الخالق المقدّر للخلق، البارئ له، المصوّر له في الصورة التي أراد، له الأسماء الحسنى، وهي مائة اسم إلا اسماً واحداً كما أخبر رسول الله ﷺ في صحيح البخاري، وأسماؤه متضمّنة صفاته، وكل أسمائه حسنى وكل صفاته عليا، يسبّح له ما في السماوات والأرض، وهو العزيز الحكيم.", "h": ["بيان ما حواه القرآن من العظات والعبر والأمر والنهي والوعد والوعيد، الأمر الذي لو أن جبلاً رُكّب فيه الإدراك والتمييز كالإنسان ونزل عليه القرآن لخشع وتصدّع من خشية الله.", "استحسان ضرب الأمثال للتنبيه والتعليم والإرشاد.", "تقرير التوحيد، وأنه لا إله إلا الله وأن محمداً رسول الله.", "إثبات أسماء الله تعالى، وأنها كلها حسنى، وأنها متضمّنة صفات عليا.", "ذكر أسمائه تعالى تعليم لعباده بها ليدعوه بها ويتوسّلوا بها إليه."], "k": "«لرأيته خاشعاً متصدّعاً من خشية الله»… الجبل لو عقله لتصدّع، وقلبي يسمعه فلا يتحرّك؛ فأين الخلل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (408, 60, 1, 6, 'سورة الممتحنة ١ – ٦', 'الممتحنة: قد كانت لكم أسوة حسنة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 408) = $j$[{"lbl": "الآيات ١ – ٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمۡ أَن تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدٗا فِي سَبِيلِي وَٱبۡتِغَآءَ مَرۡضَاتِيۚ تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡۚ وَمَن يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ ﴿١﴾ إِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ ﴿٢﴾ لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ يَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٣﴾", "w": [["لا تتخذوا عدوّي وعدوّكم", "الكفار والمشركين."], ["أولياء تُلقون إليهم بالمودة", "أنصاراً توادّونهم."], ["وقد كفروا بما جاءكم من الحق", "الإسلام عقيدة وشريعة."], ["يُخرجون الرسول وإياكم", "بالتضييق عليكم حتى خرجتم فارّين بدينكم."], ["أن تؤمنوا بالله ربكم", "لأجل أن آمنتم بربكم."], ["إن كنتم خرجتم جهاداً في سبيلي وابتغاء مرضاتي", "فلا تتخذوهم أولياء ولا تبادلوهم المودة."], ["تُسرّون إليهم بالمودة", "توصلون إليهم خبر خروج الرسول لغزوهم بطريقة سرية."], ["ومن يفعله منكم", "ومن يوادّهم فينقل إليهم أسرار النبي ﷺ في حروبه وغيرها."], ["فقد ضلّ سواء السبيل", "أخطأ طريق الحق الموصل إلى الإسعاد."], ["إن يثقفوكم", "إن يظفروا بكم متمكّنين منكم."], ["يكونوا لكم أعداء", "لا يعترفون لكم بمودة."], ["ويبسطوا إليكم أيديهم وألسنتهم بالسوء", "بالضرب والقتل، وبالسب والشتم."], ["وودّوا لو تكفرون", "أحبّوا لو تكفرون بدينكم ونبيكم وتعودون إلى الشرك."], ["لن تنفعكم أرحامكم ولا أولادكم", "إن توادّوهم من أجل أن يراعوا لكم أقرباءكم وأولادكم بينهم، فاعلموا أنهم لن ينفعوكم."], ["يوم القيامة يفصل بينكم", "فتكونون في الجنة، ويكون المشركون من أقربائكم في النار."]], "m": "نزلت هذه الآيات في شأن حاطب بن أبي بلتعة، وكان من المهاجرين الذين شهدوا بدراً؛ روى مسلم عن علي رضي الله عنه قال: بعثنا رسول الله ﷺ أنا والزبير والمقداد فقال: «ائتوا روضة خاخ، فإن بها ظعينة معها كتاب فخذوه منها»، فانطلقنا فإذا نحن بالظعينة، فقلنا: أخرجي الكتاب، فأخرجته من عقاصها، فأتينا به رسول الله ﷺ، فإذا فيه من حاطب إلى ناس من المشركين بمكة يخبرهم ببعض أمر رسول الله ﷺ، فقال: «يا حاطب، ما هذا؟» فقال: لا تعجل عليّ يا رسول الله، إني كنت امرأً ملصقاً في قريش، وكان من معك من المهاجرين لهم قرابات يحمون بها أهليهم، فأحببت أن أتخذ فيهم يداً يحمون بها قرابتي، ولم أفعله كفراً ولا ارتداداً عن ديني، فقال النبي ﷺ: «صدق»، فقال عمر: دعني يا رسول الله أضرب عنق هذا المنافق، فقال: «إنه شهد بدراً، وما يدريك لعل الله اطّلع على أهل بدر فقال: اعملوا ما شئتم فقد غفرت لكم»، فأنزل الله: يا من صدّقتم الله ورسوله لا تتخذوا عدوّي وعدوّكم من الكفار أنصاراً تلقون إليهم أسرار النبي ﷺ الحربية، والحال أنهم قد كفروا بما جاءكم من الحق، يخرجون الرسول وإياكم من دياركم بالمضايقة من أجل أن آمنتم بربكم؛ أمثل هؤلاء تتخذونهم أولياء؟ إن كنتم خرجتم مجاهدين في سبيلي طلباً لرضاي فلا تتخذوهم أولياء، تخفون إليهم المودة بنقل أخبار الرسول السرية، وأنا أعلم بما أخفيتم وما أعلنتم، وها قد أطلعت رسولي على رسالتكم إلى مشركي مكة التي تفضح عزمه على غزوهم مفاجأة حتى يفتح مكة بدون كثير إراقة دم. ومن يفعل ذلك منكم فقد أخطأ وسط الطريق. إنهم أعداؤكم حقاً، إن يظفروا بكم يبسطوا إليكم أيديهم بالضرب والقتل، وألسنتهم بالسب والشتم، وتمنّوا كفركم. لن تنفعكم أرحامكم ولا أولادكم الذين واددتم الكفار من أجلهم، إذ حاطب كتب الكتاب من أجل قرابته وأولاده، يوم القيامة يفصل بينكم: تكونون في الجنة، ويكون أقرباؤكم المشركون في النار، فما الفائدة إذاً من المعصية من أجلهم؟ والله بما تعملون بصير فراقبوه.", "h": ["حرمة موالاة الكافرين بالنصرة والتأييد والمودة دون المسلمين.", "الذي ينقل أسرار المسلمين الحربية إلى الكافرين على خطر عظيم وإن صام وصلّى.", "بيان أن الكافرين لا يرحمون المؤمنين متى تمكّنوا منهم، لأن قلوبهم عمياء لا تعرف معروفاً ولا منكراً، لظلمة الكفر في نفوسهم وعدم مراقبتهم لله عز وجل.", "فضل أهل بدر وكرامتهم على الله عز وجل.", "قبول عذر الصادقين الصالحين ذوي السبق في الإسلام إذا عثر أحدهم اجتهاداً منه.", "عدم انتفاع المرء بقرابته يوم القيامة إذا كان مسلماً وهم كافرون."], "k": "«لن تنفعكم أرحامكم ولا أولادكم»… كم مرة قدّمت رضا أحد من أهلي على رضا الله؟"}, {"lbl": "الآيات ٤ – ٦", "q": "قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَـٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا قَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَيۡءٖۖ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴿٤﴾ رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٥﴾ لَقَدۡ كَانَ لَكُمۡ فِيهِمۡ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿٦﴾", "w": [["قد كانت لكم أسوة حسنة", "قدوة صالحة أيها المؤمنون."], ["في إبراهيم والذين معه", "من المؤمنين، فائتسوا بهم."], ["إذ قالوا لقومهم", "المشركين."], ["إنا برآء منكم ومما تعبدون من دون الله", "نحن متبرّئون منكم ومن أوثانكم التي تعبدونها."], ["كفرنا بكم", "جحدنا بكم، فلم نعترف لكم بقرابة ولا ولاء."], ["وبدا بيننا وبينكم العداوة والبغضاء أبداً", "ظهر ذلك واضحاً جلياً لا لبس فيه."], ["حتى تؤمنوا بالله وحده", "ستستمر عداوتنا لكم وبغضنا إلى غاية إيمانكم بالله وحده."], ["وإليك أنبنا", "رجعنا في أمورنا كلها."], ["ربنا لا تجعلنا فتنة للذين كفروا", "بأن تظهرهم علينا فيفتنونا في ديننا، ويفتتنون بنا فيرون أنهم على حق لما يغلبوننا."], ["لقد كان لكم فيهم أسوة حسنة", "في إبراهيم والذين معه."], ["لمن كان يرجو الله واليوم الآخر", "لمن كان يؤمن بالله ويرجو ما عنده يوم القيامة."], ["ومن يتولّ", "لم يقبل ما أرشدناه إليه من الإيمان والصبر."], ["فإن الله هو الغني الحميد", "ليس في حاجة إلى إيمانه وصبره، غني بذاته، محمود بآلائه وإنعامه."]], "m": "لما حرّم تعالى على المؤمنين موالاة الكافرين، مع وجود حاجة قد تدعو إلى موالاتهم كما جاء في اعتذار حاطب، أراد أن يشجّعهم على معاداة الكافرين، فأعلمهم بأن لهم قدوة حسنة في إبراهيم خليله والمؤمنين معه، فإنهم على قلّتهم وكثرة عدوهم، وعلى ضعفهم وقوة خصومهم، تبرّؤوا من أعداء الله وتنكّروا لأية صلة تربطهم بهم، فقالوا: إنا برآء منكم ومما تعبدون من دون الله من أصنام وأوثان، كفرنا بكم فلم نعترف لكم بوجود يقتضي مودتنا ونصرتنا لكم، وظهر بيننا وبينكم العداوة والبغضاء بصورة مكشوفة، لأننا موحّدون وأنتم مشركون، وسوف تستمر هذه المعاداة حتى تؤمنوا بالله وحده. فائتسوا أيها المسلمون بإمام الموحّدين إبراهيم، إلا ما كان من استغفار إبراهيم لأبيه، فلا تأتسوا به ولا تستغفروا لموتاكم المشركين، فإن إبراهيم قد ترك ذلك لما علم أن أباه يموت كافراً، وكان هذا عن وعد قطعه له ساعة المفارقة إذ قال في سورة مريم: «سلام عليك سأستغفر لك ربي». ربنا عليك توكّلنا وإليك رجعنا من الكفر إلى الإيمان، وإليك المصير، ربنا لا تظهرهم علينا فيفتنونا في ديننا ويردّونا إلى الكفر، ويفتتنون بنا فيرون لما غلبونا أنهم على حق، فيزدادون كفراً، واغفر لنا ربنا ذنوبنا، إنك أنت العزيز الحكيم؛ وهذا الابتهال من الجائز أن يكون مما قاله إبراهيم والمؤمنون معه، وأن يكون إرشاداً من الله للمؤمنين أن يقولوه. لقد كان لكم فيهم أسوة حسنة لمن كان يرجو الله واليوم الآخر، إذ هم الذين ينتفعون بالعبر لحياة قلوبهم بالإيمان، ومن يتولّ عن الأخذ بهذه الأسوة فيوالي الكافرين فإن الله غني عن إيمانه وولايته، حميد بآلائه وإنعامه على خلقه.", "h": ["وجوب الاقتداء بالصالحين والائتساء بهم في الصالحات.", "حرمة موالاة الكافرين، ووجوب معاداتهم ولو كانوا أقرب قريب.", "كل عداوة وبغضاء تنتهي برجوع العبد إلى الإيمان والتوحيد بعد الكفر والشرك.", "لا يجوز الاقتداء في غير الحق والمعروف، فإذا أخطأ العبد الصالح فلا يُتابَع على الخطأ.", "وجوب تقوية المؤمنين بكل أسباب القوة لأمرين: الأول خشية أن يغلبهم الكافرون فيفتنوهم في دينهم، والثاني حتى لا يظن الكافرون الغالبون أنهم على حق بسبب ظهورهم على المسلمين فيزدادوا كفراً، فيكون المسلمون سبباً في ذلك فيأثمون للسببية."], "k": "«ربنا لا تجعلنا فتنة للذين كفروا»… ضعفي وتقصيري قد يصدّ غيري عن الحق؛ فهل أنا دعوة أم فتنة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 408;
insert into public.tdb_cards(topic, i, body) select 408, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمۡ أَن تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدٗا فِي سَبِيلِي وَٱبۡتِغَآءَ مَرۡضَاتِيۚ تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡۚ وَمَن يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ ﴿١﴾ إِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ ﴿٢﴾ لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ يَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٣﴾", "w": [["لا تتخذوا عدوّي وعدوّكم", "الكفار والمشركين."], ["أولياء تُلقون إليهم بالمودة", "أنصاراً توادّونهم."], ["وقد كفروا بما جاءكم من الحق", "الإسلام عقيدة وشريعة."], ["يُخرجون الرسول وإياكم", "بالتضييق عليكم حتى خرجتم فارّين بدينكم."], ["أن تؤمنوا بالله ربكم", "لأجل أن آمنتم بربكم."], ["إن كنتم خرجتم جهاداً في سبيلي وابتغاء مرضاتي", "فلا تتخذوهم أولياء ولا تبادلوهم المودة."], ["تُسرّون إليهم بالمودة", "توصلون إليهم خبر خروج الرسول لغزوهم بطريقة سرية."], ["ومن يفعله منكم", "ومن يوادّهم فينقل إليهم أسرار النبي ﷺ في حروبه وغيرها."], ["فقد ضلّ سواء السبيل", "أخطأ طريق الحق الموصل إلى الإسعاد."], ["إن يثقفوكم", "إن يظفروا بكم متمكّنين منكم."], ["يكونوا لكم أعداء", "لا يعترفون لكم بمودة."], ["ويبسطوا إليكم أيديهم وألسنتهم بالسوء", "بالضرب والقتل، وبالسب والشتم."], ["وودّوا لو تكفرون", "أحبّوا لو تكفرون بدينكم ونبيكم وتعودون إلى الشرك."], ["لن تنفعكم أرحامكم ولا أولادكم", "إن توادّوهم من أجل أن يراعوا لكم أقرباءكم وأولادكم بينهم، فاعلموا أنهم لن ينفعوكم."], ["يوم القيامة يفصل بينكم", "فتكونون في الجنة، ويكون المشركون من أقربائكم في النار."]], "m": "نزلت هذه الآيات في شأن حاطب بن أبي بلتعة، وكان من المهاجرين الذين شهدوا بدراً؛ روى مسلم عن علي رضي الله عنه قال: بعثنا رسول الله ﷺ أنا والزبير والمقداد فقال: «ائتوا روضة خاخ، فإن بها ظعينة معها كتاب فخذوه منها»، فانطلقنا فإذا نحن بالظعينة، فقلنا: أخرجي الكتاب، فأخرجته من عقاصها، فأتينا به رسول الله ﷺ، فإذا فيه من حاطب إلى ناس من المشركين بمكة يخبرهم ببعض أمر رسول الله ﷺ، فقال: «يا حاطب، ما هذا؟» فقال: لا تعجل عليّ يا رسول الله، إني كنت امرأً ملصقاً في قريش، وكان من معك من المهاجرين لهم قرابات يحمون بها أهليهم، فأحببت أن أتخذ فيهم يداً يحمون بها قرابتي، ولم أفعله كفراً ولا ارتداداً عن ديني، فقال النبي ﷺ: «صدق»، فقال عمر: دعني يا رسول الله أضرب عنق هذا المنافق، فقال: «إنه شهد بدراً، وما يدريك لعل الله اطّلع على أهل بدر فقال: اعملوا ما شئتم فقد غفرت لكم»، فأنزل الله: يا من صدّقتم الله ورسوله لا تتخذوا عدوّي وعدوّكم من الكفار أنصاراً تلقون إليهم أسرار النبي ﷺ الحربية، والحال أنهم قد كفروا بما جاءكم من الحق، يخرجون الرسول وإياكم من دياركم بالمضايقة من أجل أن آمنتم بربكم؛ أمثل هؤلاء تتخذونهم أولياء؟ إن كنتم خرجتم مجاهدين في سبيلي طلباً لرضاي فلا تتخذوهم أولياء، تخفون إليهم المودة بنقل أخبار الرسول السرية، وأنا أعلم بما أخفيتم وما أعلنتم، وها قد أطلعت رسولي على رسالتكم إلى مشركي مكة التي تفضح عزمه على غزوهم مفاجأة حتى يفتح مكة بدون كثير إراقة دم. ومن يفعل ذلك منكم فقد أخطأ وسط الطريق. إنهم أعداؤكم حقاً، إن يظفروا بكم يبسطوا إليكم أيديهم بالضرب والقتل، وألسنتهم بالسب والشتم، وتمنّوا كفركم. لن تنفعكم أرحامكم ولا أولادكم الذين واددتم الكفار من أجلهم، إذ حاطب كتب الكتاب من أجل قرابته وأولاده، يوم القيامة يفصل بينكم: تكونون في الجنة، ويكون أقرباؤكم المشركون في النار، فما الفائدة إذاً من المعصية من أجلهم؟ والله بما تعملون بصير فراقبوه.", "h": ["حرمة موالاة الكافرين بالنصرة والتأييد والمودة دون المسلمين.", "الذي ينقل أسرار المسلمين الحربية إلى الكافرين على خطر عظيم وإن صام وصلّى.", "بيان أن الكافرين لا يرحمون المؤمنين متى تمكّنوا منهم، لأن قلوبهم عمياء لا تعرف معروفاً ولا منكراً، لظلمة الكفر في نفوسهم وعدم مراقبتهم لله عز وجل.", "فضل أهل بدر وكرامتهم على الله عز وجل.", "قبول عذر الصادقين الصالحين ذوي السبق في الإسلام إذا عثر أحدهم اجتهاداً منه.", "عدم انتفاع المرء بقرابته يوم القيامة إذا كان مسلماً وهم كافرون."], "k": "«لن تنفعكم أرحامكم ولا أولادكم»… كم مرة قدّمت رضا أحد من أهلي على رضا الله؟"}, {"lbl": "الآيات ٤ – ٦", "q": "قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَـٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا قَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَيۡءٖۖ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴿٤﴾ رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٥﴾ لَقَدۡ كَانَ لَكُمۡ فِيهِمۡ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿٦﴾", "w": [["قد كانت لكم أسوة حسنة", "قدوة صالحة أيها المؤمنون."], ["في إبراهيم والذين معه", "من المؤمنين، فائتسوا بهم."], ["إذ قالوا لقومهم", "المشركين."], ["إنا برآء منكم ومما تعبدون من دون الله", "نحن متبرّئون منكم ومن أوثانكم التي تعبدونها."], ["كفرنا بكم", "جحدنا بكم، فلم نعترف لكم بقرابة ولا ولاء."], ["وبدا بيننا وبينكم العداوة والبغضاء أبداً", "ظهر ذلك واضحاً جلياً لا لبس فيه."], ["حتى تؤمنوا بالله وحده", "ستستمر عداوتنا لكم وبغضنا إلى غاية إيمانكم بالله وحده."], ["وإليك أنبنا", "رجعنا في أمورنا كلها."], ["ربنا لا تجعلنا فتنة للذين كفروا", "بأن تظهرهم علينا فيفتنونا في ديننا، ويفتتنون بنا فيرون أنهم على حق لما يغلبوننا."], ["لقد كان لكم فيهم أسوة حسنة", "في إبراهيم والذين معه."], ["لمن كان يرجو الله واليوم الآخر", "لمن كان يؤمن بالله ويرجو ما عنده يوم القيامة."], ["ومن يتولّ", "لم يقبل ما أرشدناه إليه من الإيمان والصبر."], ["فإن الله هو الغني الحميد", "ليس في حاجة إلى إيمانه وصبره، غني بذاته، محمود بآلائه وإنعامه."]], "m": "لما حرّم تعالى على المؤمنين موالاة الكافرين، مع وجود حاجة قد تدعو إلى موالاتهم كما جاء في اعتذار حاطب، أراد أن يشجّعهم على معاداة الكافرين، فأعلمهم بأن لهم قدوة حسنة في إبراهيم خليله والمؤمنين معه، فإنهم على قلّتهم وكثرة عدوهم، وعلى ضعفهم وقوة خصومهم، تبرّؤوا من أعداء الله وتنكّروا لأية صلة تربطهم بهم، فقالوا: إنا برآء منكم ومما تعبدون من دون الله من أصنام وأوثان، كفرنا بكم فلم نعترف لكم بوجود يقتضي مودتنا ونصرتنا لكم، وظهر بيننا وبينكم العداوة والبغضاء بصورة مكشوفة، لأننا موحّدون وأنتم مشركون، وسوف تستمر هذه المعاداة حتى تؤمنوا بالله وحده. فائتسوا أيها المسلمون بإمام الموحّدين إبراهيم، إلا ما كان من استغفار إبراهيم لأبيه، فلا تأتسوا به ولا تستغفروا لموتاكم المشركين، فإن إبراهيم قد ترك ذلك لما علم أن أباه يموت كافراً، وكان هذا عن وعد قطعه له ساعة المفارقة إذ قال في سورة مريم: «سلام عليك سأستغفر لك ربي». ربنا عليك توكّلنا وإليك رجعنا من الكفر إلى الإيمان، وإليك المصير، ربنا لا تظهرهم علينا فيفتنونا في ديننا ويردّونا إلى الكفر، ويفتتنون بنا فيرون لما غلبونا أنهم على حق، فيزدادون كفراً، واغفر لنا ربنا ذنوبنا، إنك أنت العزيز الحكيم؛ وهذا الابتهال من الجائز أن يكون مما قاله إبراهيم والمؤمنون معه، وأن يكون إرشاداً من الله للمؤمنين أن يقولوه. لقد كان لكم فيهم أسوة حسنة لمن كان يرجو الله واليوم الآخر، إذ هم الذين ينتفعون بالعبر لحياة قلوبهم بالإيمان، ومن يتولّ عن الأخذ بهذه الأسوة فيوالي الكافرين فإن الله غني عن إيمانه وولايته، حميد بآلائه وإنعامه على خلقه.", "h": ["وجوب الاقتداء بالصالحين والائتساء بهم في الصالحات.", "حرمة موالاة الكافرين، ووجوب معاداتهم ولو كانوا أقرب قريب.", "كل عداوة وبغضاء تنتهي برجوع العبد إلى الإيمان والتوحيد بعد الكفر والشرك.", "لا يجوز الاقتداء في غير الحق والمعروف، فإذا أخطأ العبد الصالح فلا يُتابَع على الخطأ.", "وجوب تقوية المؤمنين بكل أسباب القوة لأمرين: الأول خشية أن يغلبهم الكافرون فيفتنوهم في دينهم، والثاني حتى لا يظن الكافرون الغالبون أنهم على حق بسبب ظهورهم على المسلمين فيزدادوا كفراً، فيكون المسلمون سبباً في ذلك فيأثمون للسببية."], "k": "«ربنا لا تجعلنا فتنة للذين كفروا»… ضعفي وتقصيري قد يصدّ غيري عن الحق؛ فهل أنا دعوة أم فتنة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (409, 60, 7, 13, 'سورة الممتحنة ٧ – ١٣', 'الممتحنة: أن تبرّوهم وتقسطوا إليهم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 409) = $j$[{"lbl": "الآيات ٧ – ٩", "q": "۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةٗۚ وَٱللَّهُ قَدِيرٞۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٧﴾ لَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ﴿٨﴾ إِنَّمَا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمۡ فِي ٱلدِّينِ وَأَخۡرَجُوكُم مِّن دِيَٰرِكُمۡ وَظَٰهَرُواْ عَلَىٰٓ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن يَتَوَلَّهُمۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٩﴾", "w": [["عسى الله أن يجعل بينكم وبين الذين عاديتم منهم مودة", "من كفار قريش بمكة، طاعة لله، محبةً وولاءً، بأن يوفّقهم للإسلام فيصبحوا أولياءكم."], ["والله قدير", "على ذلك، وقد فعل، فأسلم بعد الفتح أهل مكة إلا قليلاً منهم."], ["لم يقاتلوكم في الدين", "من أجل الدين."], ["أن تبرّوهم", "تحسنوا إليهم."], ["وتقسطوا إليهم", "تعدلوا فيهم فتنصفوهم."], ["إن الله يحب المقسطين", "المنصفين العادلين في أحكامهم ومن ولّوا."], ["وظاهروا على إخراجكم", "عاونوا وناصروا العدو على إخراجكم من دياركم."], ["أن تولّوهم", "تتولّوهم بالنصرة والمحبة."], ["فأولئك هم الظالمون", "لأنهم وضعوا الولاية في غير موضعها، والظلم وضع الشيء في غير موضعه."]], "m": "ما زال السياق في بيان حكم الموالاة للكافرين؛ فإنه لما حرّم تعالى ذلك، وكان للمؤمنين قرابات كافرة قاطعوهم استجابة لنداء ربهم، بشّرهم بأنه قادر على أن يجعل بينهم وبين أقربائهم مودة بأن يوفّقهم للإسلام، وهو على ذلك قدير، وقد فعل وله الحمد، ففتح على رسوله مكة وآمن أهلها إلا قليلاً، فكانت المودة والإخاء، والله غفور رحيم، تاب عليهم بعد أن هداهم وغفر لهم. لا ينهاكم الله عن الذين لم يقاتلوكم من أجل دينكم ولم يخرجوكم من دياركم بمضايقتكم أن تبرّوهم بالإحسان إليهم بطعام أو كسوة أو إركاب، وتقسطوا إليهم بأن تنصفوهم، وهذا عام في كل الظروف الزمانية والمكانية وفي كل الكفار بالشروط التي ذكرها تعالى: أولاً: ألا يقاتلونا من أجل ديننا، ثانياً: ألا يخرجونا من ديارنا بمضايقتنا وإلجائنا إلى الهجرة، ثالثاً: ألا يعاونوا عدواً من أعدائنا بأي معونة ولو بالمشورة والرأي. إن الله يحب المقسطين، ترغيب لهم في العدل والإنصاف حتى مع الكافر. إنما ينهاكم الله عن موالاة الذين قاتلوكم في الدين وأخرجوكم من دياركم وأعانوا على إخراجكم، ومن يتولّهم منكم معرضاً عن هذا الإرشاد الإلهي فأولئك هم الظالمون المتعرّضون لعذاب الله، لوضعهم الموالاة في غير موضعها.", "h": ["بيان حكم الموالاة الممنوعة والمباحة في الإسلام.", "الترغيب في العدل والإنصاف بعد وجوبهما، للمساعدة على القيام بهما.", "تقرير ما قال أهل العلم: أن «عسى» من الله تفيد وقوع ما يُرجى بها لا محالة، بخلافها من غير الله فهي للترجّي والتوقّع، وقد يقع ما يُترجّى بها وقد لا يقع."], "k": "«أن تبرّوهم وتقسطوا إليهم إن الله يحب المقسطين»… العدل مطلوب حتى مع المخالف؛ فهل أنصف من أختلف معه؟"}, {"lbl": "الآيتان ١٠ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِيمَٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّآ أَنفَقُواْۚ وَلَا جُنَاحَ عَلَيۡكُمۡ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّۚ وَلَا تُمۡسِكُواْ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُواْ مَآ أَنفَقۡتُمۡ وَلۡيَسۡـَٔلُواْ مَآ أَنفَقُواْۚ ذَٰلِكُمۡ حُكۡمُ ٱللَّهِ يَحۡكُمُ بَيۡنَكُمۡۖ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿١٠﴾ وَإِن فَاتَكُمۡ شَيۡءٞ مِّنۡ أَزۡوَٰجِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُواْ ٱلَّذِينَ ذَهَبَتۡ أَزۡوَٰجُهُم مِّثۡلَ مَآ أَنفَقُواْۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ ﴿١١﴾", "w": [["إذا جاءكم المؤمنات مهاجرات", "المؤمنات بألسنتهن، مهاجرات من الكفار."], ["فامتحنوهن", "اختبروهن بالحلف أنهن ما خرجن إلا رغبة في الإسلام، لا بغضاً لأزواجهن ولا عشقاً لرجال من المسلمين."], ["فإن علمتموهن مؤمنات", "صادقات في إيمانهن بحسب حلفهن."], ["فلا ترجعوهن إلى الكفار", "لا تردّوهن إلى الكفار بمكة."], ["لا هنّ حلّ لهم ولا هم يحلّون لهن", "لا المؤمنات يحللن لأزواجهن الكافرين، ولا الكافرون يحلّون لأزواجهم المؤمنات."], ["وآتوهم ما أنفقوا", "وأعطوا الكفار أزواج المؤمنات المهاجرات المهور التي أعطوها لهن."], ["ولا جناح عليكم أن تنكحوهن إذا آتيتموهن أجورهن", "مهورهن، وإن لم يتم طلاق من أزواجهن لانفساخ العقد بالإسلام، وبعد انقضاء العدة في المدخول بها، وباقي شروط النكاح."], ["ولا تمسكوا بعصم الكوافر", "زوجاتكم، لقطع إسلامكم للعصمة الزوجية، وكذا من ارتدّت ولحقت بدار الكفر."], ["واسألوا ما أنفقتم", "اطلبوا ما أنفقتم عليهن من مهور في حال الارتداد."], ["وليسألوا ما أنفقوا", "على المهاجرات من مهور في حال إسلامهن."], ["وإن فاتكم شيء من أزواجكم إلى الكفار فعاقبتم", "بأن فرّت امرأة أحدكم إلى الكفار ولم يعطوكم مهرها، فغزوتم فغنمتم منهم."], ["فآتوا الذين ذهبت أزواجهم مثل ما أنفقوا", "فأعطوا الذين ذهبت أزواجهم إلى الكفار مثل ما أنفقوا عليهن من مهور."], ["واتقوا الله الذي أنتم به مؤمنون", "خافوه فأدّوا فرائضه واجتنبوا نواهيه."]], "m": "نزلت الآيتان بعد صلح الحديبية، إذ تضمّنت وثيقة الصلح أن من جاء الرسول ﷺ من مكة من الرجال ردّه إليها ولو كان مسلماً، ولم ينصّ على النساء، وأثناء ذلك جاءت أم كلثوم بنت عقبة بن أبي معيط مهاجرة إلى المدينة، فلحق بها أخواها عمارة والوليد ليردّاها، فنزلت الآية فلم يردّها ﷺ. يا من آمنتم بالله وبمحمد ﷺ نبياً ورسولاً، إذا جاءكم المؤمنات مهاجرات من دار الكفر إلى دار الإسلام فامتحنوهن، الله أعلم بإيمانهن، فإن غلب على ظنكم أنهن مؤمنات فلا ترجعوهن إلى الكفار، وصورة الامتحان أن يقال لها: احلفي بالله الذي لا إله إلا هو ما خرجتِ إلا رغبة في الإسلام، لا بغضاً لزوجك ولا عشقاً لرجل مسلم. لا هن حلّ لهم ولا هم يحلّون لهن، لأن الإسلام فصم العصمة بين الزوجين، إذ حرّم الله نكاح المشركات وإنكاح المشركين. وإذا جاء زوجها المشرك يطالب بها فأعطوه ما أنفق عليها من مهر، والذي يعطيه جماعة المسلمين وإمامهم. ولا جناح عليكم أن تتزوّجوهن إذا آتيتموهن مهورهن مع باقي شروط النكاح من ولي وشاهدين وانقضاء العدة في المدخول بها. ولا تمسكوا بعصم الكوافر: إذا أسلم الرجل وبقيت امرأته مشركة انقطعت عصمة الزوجية، وكذا إذا ارتدّت امرأة مسلمة ولحقت بدار الكفر. واطلبوا ما أنفقتم على المرتدة من مهر، وليطلبوا هم ما أنفقوا على نسائهم اللائي أسلمن وهاجرن إليكم، ذلكم حكم الله يحكم بينكم، والله عليم بخلقه وحاجاتهم، حكيم في قضائه، فليُسلَّم له الحكم وليُرضَ به. وإن ذهبت بعض نسائكم إلى الكفار مرتدّات، وطالبتم بالمهور فلم يعطوكم، ثم غزوتم وغنمتم، فأعطوا من الغنيمة قبل قسمتها الذي ذهبت زوجته مثل ما أنفق، واتقوا الله الذي أنتم به مؤمنون.", "h": ["وجوب امتحان المهاجرة، فإن عُلم إسلامها لا يحل إرجاعها إلى زوجها الكافر، لأنها لا تحل له، ويُعطى ما أنفق عليها من مهر، ويجوز بعد ذلك نكاحها بمهر وولي وشاهدين؛ إن كانت مدخولاً بها فبعد انقضاء عدتها، وإلا فلا حرج في الزواج بها فوراً.", "حرمة نكاح المشركة.", "لا يجوز الإبقاء على عصمة الزوجة المشركة؛ وللزوج المسلم الذي بقيت زوجته على الكفر أو ارتدّت بعد إسلامها أن يطالب بما أنفق عليها من مهر، وللزوج الكافر الذي أسلمت زوجته وهاجرت أن يسأل كذلك ما أنفق عليها.", "من ذهبت زوجته ولم يُردّ عليه شيء مما أنفق عليها، ثم غزا المسلمون تلك البلاد وغنموا، فإنه يُعطى ما أنفقه من الغنيمة قبل قسمتها، وإن لم تكن غنيمة فجماعة المسلمين وإمامهم يساعدونه ببعض ما أنفق من باب التكافل والتعاون.", "وجوب تقوى الله تعالى بتطبيق شرعه وإنفاذ أحكامه والرضا بها."], "k": "«ذلكم حكم الله يحكم بينكم»… حتى في أدق شؤون البيت والمال حكمه حاضر؛ فهل أرضى به حين يخالف هواي؟"}, {"lbl": "الآيتان ١٢ – ١٣", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا جَآءَكَ ٱلۡمُؤۡمِنَٰتُ يُبَايِعۡنَكَ عَلَىٰٓ أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ شَيۡـٔٗا وَلَا يَسۡرِقۡنَ وَلَا يَزۡنِينَ وَلَا يَقۡتُلۡنَ أَوۡلَٰدَهُنَّ وَلَا يَأۡتِينَ بِبُهۡتَٰنٖ يَفۡتَرِينَهُۥ بَيۡنَ أَيۡدِيهِنَّ وَأَرۡجُلِهِنَّ وَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ فَبَايِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١٢﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِمۡ قَدۡ يَئِسُواْ مِنَ ٱلۡأٓخِرَةِ كَمَا يَئِسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَٰبِ ٱلۡقُبُورِ ﴿١٣﴾", "w": [["إذا جاءك المؤمنات يبايعنك", "يوم الفتح، والرسول ﷺ على الصفا وعمر أسفل منه."], ["على أن لا يشركن بالله شيئاً", "أي شيء من الشرك أو الشركاء."], ["ولا يقتلن أولادهن", "كما كان أهل الجاهلية يقتلون البنات وأداً لهن."], ["ولا يأتين ببهتان يفترينه بين أيديهن وأرجلهن", "بكذب يكذبنه، فيأتين بولد ملقوط وينسبنه إلى الزوج وهو ليس بولده."], ["ولا يعصينك في معروف", "فيما عرفه الشرع صالحاً حسناً فأمر به، أو منكراً محرّماً فنهى عنه."], ["فبايعهن", "اقبل بيعتهن."], ["واستغفر لهن الله", "اطلب من الله تعالى لهن المغفرة لما سلف من ذنوبهن."], ["قوماً غضب الله عليهم", "اليهود."], ["قد يئسوا من الآخرة", "من ثوابها مع إيقانهم بها، وذلك لعنادهم النبي ﷺ."], ["كما يئس الكفار من أصحاب القبور", "كيأس من سبقهم من اليهود الذين كفروا بعيسى وماتوا على ذلك."]], "m": "هذه آية بيعة النساء؛ فقد بايع عليها رسول الله ﷺ نساء قريش يوم الفتح وهو جالس على الصفا، وعمر أسفل منه، وطُلب إليه أن يمدّ يده فقال: «إني لا أصافح النساء»، فبايعهن على ألّا يشركن بالله شيئاً، ولا يسرقن، ولا يزنين، ولا يقتلن أولادهن كما كان نساء الجاهلية يئدن بناتهن، ولا يأتين ببهتان يفترينه بين أيديهن وأرجلهن، أي لا يُلحقن بأزواجهن غير أولادهم، ولا يعصينك في معروف بصورة عامة، وفي النياحة بصورة خاصة، إذ كان النساء في الجاهلية ينحن على الأموات ويشققن الثياب ويخدشن الوجوه، فبايعهن واستغفر لهن الله فيما مضى من ذنوبهن، إن الله غفور رحيم. ثم قال: يا من صدّقتم الله ورسوله لا تتولّوا قوماً غضب الله عليهم، وهم اليهود، لا تتولّوهم بالنصرة والمحبة، وقد يئسوا من ثواب الآخرة بدخول الجنة، وذلك لعنادهم رسول الله ﷺ وكفرهم به مع علمهم أنه رسول الله، كما يئس إخوانهم الذين ماتوا قبلهم من دخول الجنة، إذ كفروا بعيسى ﵇ وحاربوه، واتّهموه ووالدته بالبهتان.", "h": ["مشروعية أخذ البيعة لإمام المسلمين، ووجوب الوفاء بها.", "حرمة الشرك، وما ذُكر معه من السرقة والزنا وقتل الأولاد والكذب والبهتان.", "حرمة النياحة، وما ذُكر معها من شق الثياب وخمش الوجوه والتحدّث مع الرجال الأجانب.", "بُعد الحرة كل البعد من الزنا، إذ قالت هند وهي تبايع: أوَتزني الحرة؟", "حرمة مصافحة النساء، لقوله ﷺ في البيعة: «إني لا أصافح النساء».", "حرمة موالاة اليهود بالنصرة والمحبة."], "k": "«ولا يعصينك في معروف»… بيعة على الطاعة في كل معروف؛ فأي معروف أؤخّره اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 409;
insert into public.tdb_cards(topic, i, body) select 409, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧ – ٩", "q": "۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةٗۚ وَٱللَّهُ قَدِيرٞۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٧﴾ لَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ﴿٨﴾ إِنَّمَا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمۡ فِي ٱلدِّينِ وَأَخۡرَجُوكُم مِّن دِيَٰرِكُمۡ وَظَٰهَرُواْ عَلَىٰٓ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن يَتَوَلَّهُمۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٩﴾", "w": [["عسى الله أن يجعل بينكم وبين الذين عاديتم منهم مودة", "من كفار قريش بمكة، طاعة لله، محبةً وولاءً، بأن يوفّقهم للإسلام فيصبحوا أولياءكم."], ["والله قدير", "على ذلك، وقد فعل، فأسلم بعد الفتح أهل مكة إلا قليلاً منهم."], ["لم يقاتلوكم في الدين", "من أجل الدين."], ["أن تبرّوهم", "تحسنوا إليهم."], ["وتقسطوا إليهم", "تعدلوا فيهم فتنصفوهم."], ["إن الله يحب المقسطين", "المنصفين العادلين في أحكامهم ومن ولّوا."], ["وظاهروا على إخراجكم", "عاونوا وناصروا العدو على إخراجكم من دياركم."], ["أن تولّوهم", "تتولّوهم بالنصرة والمحبة."], ["فأولئك هم الظالمون", "لأنهم وضعوا الولاية في غير موضعها، والظلم وضع الشيء في غير موضعه."]], "m": "ما زال السياق في بيان حكم الموالاة للكافرين؛ فإنه لما حرّم تعالى ذلك، وكان للمؤمنين قرابات كافرة قاطعوهم استجابة لنداء ربهم، بشّرهم بأنه قادر على أن يجعل بينهم وبين أقربائهم مودة بأن يوفّقهم للإسلام، وهو على ذلك قدير، وقد فعل وله الحمد، ففتح على رسوله مكة وآمن أهلها إلا قليلاً، فكانت المودة والإخاء، والله غفور رحيم، تاب عليهم بعد أن هداهم وغفر لهم. لا ينهاكم الله عن الذين لم يقاتلوكم من أجل دينكم ولم يخرجوكم من دياركم بمضايقتكم أن تبرّوهم بالإحسان إليهم بطعام أو كسوة أو إركاب، وتقسطوا إليهم بأن تنصفوهم، وهذا عام في كل الظروف الزمانية والمكانية وفي كل الكفار بالشروط التي ذكرها تعالى: أولاً: ألا يقاتلونا من أجل ديننا، ثانياً: ألا يخرجونا من ديارنا بمضايقتنا وإلجائنا إلى الهجرة، ثالثاً: ألا يعاونوا عدواً من أعدائنا بأي معونة ولو بالمشورة والرأي. إن الله يحب المقسطين، ترغيب لهم في العدل والإنصاف حتى مع الكافر. إنما ينهاكم الله عن موالاة الذين قاتلوكم في الدين وأخرجوكم من دياركم وأعانوا على إخراجكم، ومن يتولّهم منكم معرضاً عن هذا الإرشاد الإلهي فأولئك هم الظالمون المتعرّضون لعذاب الله، لوضعهم الموالاة في غير موضعها.", "h": ["بيان حكم الموالاة الممنوعة والمباحة في الإسلام.", "الترغيب في العدل والإنصاف بعد وجوبهما، للمساعدة على القيام بهما.", "تقرير ما قال أهل العلم: أن «عسى» من الله تفيد وقوع ما يُرجى بها لا محالة، بخلافها من غير الله فهي للترجّي والتوقّع، وقد يقع ما يُترجّى بها وقد لا يقع."], "k": "«أن تبرّوهم وتقسطوا إليهم إن الله يحب المقسطين»… العدل مطلوب حتى مع المخالف؛ فهل أنصف من أختلف معه؟"}, {"lbl": "الآيتان ١٠ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِيمَٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّآ أَنفَقُواْۚ وَلَا جُنَاحَ عَلَيۡكُمۡ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّۚ وَلَا تُمۡسِكُواْ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُواْ مَآ أَنفَقۡتُمۡ وَلۡيَسۡـَٔلُواْ مَآ أَنفَقُواْۚ ذَٰلِكُمۡ حُكۡمُ ٱللَّهِ يَحۡكُمُ بَيۡنَكُمۡۖ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿١٠﴾ وَإِن فَاتَكُمۡ شَيۡءٞ مِّنۡ أَزۡوَٰجِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُواْ ٱلَّذِينَ ذَهَبَتۡ أَزۡوَٰجُهُم مِّثۡلَ مَآ أَنفَقُواْۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ ﴿١١﴾", "w": [["إذا جاءكم المؤمنات مهاجرات", "المؤمنات بألسنتهن، مهاجرات من الكفار."], ["فامتحنوهن", "اختبروهن بالحلف أنهن ما خرجن إلا رغبة في الإسلام، لا بغضاً لأزواجهن ولا عشقاً لرجال من المسلمين."], ["فإن علمتموهن مؤمنات", "صادقات في إيمانهن بحسب حلفهن."], ["فلا ترجعوهن إلى الكفار", "لا تردّوهن إلى الكفار بمكة."], ["لا هنّ حلّ لهم ولا هم يحلّون لهن", "لا المؤمنات يحللن لأزواجهن الكافرين، ولا الكافرون يحلّون لأزواجهم المؤمنات."], ["وآتوهم ما أنفقوا", "وأعطوا الكفار أزواج المؤمنات المهاجرات المهور التي أعطوها لهن."], ["ولا جناح عليكم أن تنكحوهن إذا آتيتموهن أجورهن", "مهورهن، وإن لم يتم طلاق من أزواجهن لانفساخ العقد بالإسلام، وبعد انقضاء العدة في المدخول بها، وباقي شروط النكاح."], ["ولا تمسكوا بعصم الكوافر", "زوجاتكم، لقطع إسلامكم للعصمة الزوجية، وكذا من ارتدّت ولحقت بدار الكفر."], ["واسألوا ما أنفقتم", "اطلبوا ما أنفقتم عليهن من مهور في حال الارتداد."], ["وليسألوا ما أنفقوا", "على المهاجرات من مهور في حال إسلامهن."], ["وإن فاتكم شيء من أزواجكم إلى الكفار فعاقبتم", "بأن فرّت امرأة أحدكم إلى الكفار ولم يعطوكم مهرها، فغزوتم فغنمتم منهم."], ["فآتوا الذين ذهبت أزواجهم مثل ما أنفقوا", "فأعطوا الذين ذهبت أزواجهم إلى الكفار مثل ما أنفقوا عليهن من مهور."], ["واتقوا الله الذي أنتم به مؤمنون", "خافوه فأدّوا فرائضه واجتنبوا نواهيه."]], "m": "نزلت الآيتان بعد صلح الحديبية، إذ تضمّنت وثيقة الصلح أن من جاء الرسول ﷺ من مكة من الرجال ردّه إليها ولو كان مسلماً، ولم ينصّ على النساء، وأثناء ذلك جاءت أم كلثوم بنت عقبة بن أبي معيط مهاجرة إلى المدينة، فلحق بها أخواها عمارة والوليد ليردّاها، فنزلت الآية فلم يردّها ﷺ. يا من آمنتم بالله وبمحمد ﷺ نبياً ورسولاً، إذا جاءكم المؤمنات مهاجرات من دار الكفر إلى دار الإسلام فامتحنوهن، الله أعلم بإيمانهن، فإن غلب على ظنكم أنهن مؤمنات فلا ترجعوهن إلى الكفار، وصورة الامتحان أن يقال لها: احلفي بالله الذي لا إله إلا هو ما خرجتِ إلا رغبة في الإسلام، لا بغضاً لزوجك ولا عشقاً لرجل مسلم. لا هن حلّ لهم ولا هم يحلّون لهن، لأن الإسلام فصم العصمة بين الزوجين، إذ حرّم الله نكاح المشركات وإنكاح المشركين. وإذا جاء زوجها المشرك يطالب بها فأعطوه ما أنفق عليها من مهر، والذي يعطيه جماعة المسلمين وإمامهم. ولا جناح عليكم أن تتزوّجوهن إذا آتيتموهن مهورهن مع باقي شروط النكاح من ولي وشاهدين وانقضاء العدة في المدخول بها. ولا تمسكوا بعصم الكوافر: إذا أسلم الرجل وبقيت امرأته مشركة انقطعت عصمة الزوجية، وكذا إذا ارتدّت امرأة مسلمة ولحقت بدار الكفر. واطلبوا ما أنفقتم على المرتدة من مهر، وليطلبوا هم ما أنفقوا على نسائهم اللائي أسلمن وهاجرن إليكم، ذلكم حكم الله يحكم بينكم، والله عليم بخلقه وحاجاتهم، حكيم في قضائه، فليُسلَّم له الحكم وليُرضَ به. وإن ذهبت بعض نسائكم إلى الكفار مرتدّات، وطالبتم بالمهور فلم يعطوكم، ثم غزوتم وغنمتم، فأعطوا من الغنيمة قبل قسمتها الذي ذهبت زوجته مثل ما أنفق، واتقوا الله الذي أنتم به مؤمنون.", "h": ["وجوب امتحان المهاجرة، فإن عُلم إسلامها لا يحل إرجاعها إلى زوجها الكافر، لأنها لا تحل له، ويُعطى ما أنفق عليها من مهر، ويجوز بعد ذلك نكاحها بمهر وولي وشاهدين؛ إن كانت مدخولاً بها فبعد انقضاء عدتها، وإلا فلا حرج في الزواج بها فوراً.", "حرمة نكاح المشركة.", "لا يجوز الإبقاء على عصمة الزوجة المشركة؛ وللزوج المسلم الذي بقيت زوجته على الكفر أو ارتدّت بعد إسلامها أن يطالب بما أنفق عليها من مهر، وللزوج الكافر الذي أسلمت زوجته وهاجرت أن يسأل كذلك ما أنفق عليها.", "من ذهبت زوجته ولم يُردّ عليه شيء مما أنفق عليها، ثم غزا المسلمون تلك البلاد وغنموا، فإنه يُعطى ما أنفقه من الغنيمة قبل قسمتها، وإن لم تكن غنيمة فجماعة المسلمين وإمامهم يساعدونه ببعض ما أنفق من باب التكافل والتعاون.", "وجوب تقوى الله تعالى بتطبيق شرعه وإنفاذ أحكامه والرضا بها."], "k": "«ذلكم حكم الله يحكم بينكم»… حتى في أدق شؤون البيت والمال حكمه حاضر؛ فهل أرضى به حين يخالف هواي؟"}, {"lbl": "الآيتان ١٢ – ١٣", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا جَآءَكَ ٱلۡمُؤۡمِنَٰتُ يُبَايِعۡنَكَ عَلَىٰٓ أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ شَيۡـٔٗا وَلَا يَسۡرِقۡنَ وَلَا يَزۡنِينَ وَلَا يَقۡتُلۡنَ أَوۡلَٰدَهُنَّ وَلَا يَأۡتِينَ بِبُهۡتَٰنٖ يَفۡتَرِينَهُۥ بَيۡنَ أَيۡدِيهِنَّ وَأَرۡجُلِهِنَّ وَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ فَبَايِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١٢﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِمۡ قَدۡ يَئِسُواْ مِنَ ٱلۡأٓخِرَةِ كَمَا يَئِسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَٰبِ ٱلۡقُبُورِ ﴿١٣﴾", "w": [["إذا جاءك المؤمنات يبايعنك", "يوم الفتح، والرسول ﷺ على الصفا وعمر أسفل منه."], ["على أن لا يشركن بالله شيئاً", "أي شيء من الشرك أو الشركاء."], ["ولا يقتلن أولادهن", "كما كان أهل الجاهلية يقتلون البنات وأداً لهن."], ["ولا يأتين ببهتان يفترينه بين أيديهن وأرجلهن", "بكذب يكذبنه، فيأتين بولد ملقوط وينسبنه إلى الزوج وهو ليس بولده."], ["ولا يعصينك في معروف", "فيما عرفه الشرع صالحاً حسناً فأمر به، أو منكراً محرّماً فنهى عنه."], ["فبايعهن", "اقبل بيعتهن."], ["واستغفر لهن الله", "اطلب من الله تعالى لهن المغفرة لما سلف من ذنوبهن."], ["قوماً غضب الله عليهم", "اليهود."], ["قد يئسوا من الآخرة", "من ثوابها مع إيقانهم بها، وذلك لعنادهم النبي ﷺ."], ["كما يئس الكفار من أصحاب القبور", "كيأس من سبقهم من اليهود الذين كفروا بعيسى وماتوا على ذلك."]], "m": "هذه آية بيعة النساء؛ فقد بايع عليها رسول الله ﷺ نساء قريش يوم الفتح وهو جالس على الصفا، وعمر أسفل منه، وطُلب إليه أن يمدّ يده فقال: «إني لا أصافح النساء»، فبايعهن على ألّا يشركن بالله شيئاً، ولا يسرقن، ولا يزنين، ولا يقتلن أولادهن كما كان نساء الجاهلية يئدن بناتهن، ولا يأتين ببهتان يفترينه بين أيديهن وأرجلهن، أي لا يُلحقن بأزواجهن غير أولادهم، ولا يعصينك في معروف بصورة عامة، وفي النياحة بصورة خاصة، إذ كان النساء في الجاهلية ينحن على الأموات ويشققن الثياب ويخدشن الوجوه، فبايعهن واستغفر لهن الله فيما مضى من ذنوبهن، إن الله غفور رحيم. ثم قال: يا من صدّقتم الله ورسوله لا تتولّوا قوماً غضب الله عليهم، وهم اليهود، لا تتولّوهم بالنصرة والمحبة، وقد يئسوا من ثواب الآخرة بدخول الجنة، وذلك لعنادهم رسول الله ﷺ وكفرهم به مع علمهم أنه رسول الله، كما يئس إخوانهم الذين ماتوا قبلهم من دخول الجنة، إذ كفروا بعيسى ﵇ وحاربوه، واتّهموه ووالدته بالبهتان.", "h": ["مشروعية أخذ البيعة لإمام المسلمين، ووجوب الوفاء بها.", "حرمة الشرك، وما ذُكر معه من السرقة والزنا وقتل الأولاد والكذب والبهتان.", "حرمة النياحة، وما ذُكر معها من شق الثياب وخمش الوجوه والتحدّث مع الرجال الأجانب.", "بُعد الحرة كل البعد من الزنا، إذ قالت هند وهي تبايع: أوَتزني الحرة؟", "حرمة مصافحة النساء، لقوله ﷺ في البيعة: «إني لا أصافح النساء».", "حرمة موالاة اليهود بالنصرة والمحبة."], "k": "«ولا يعصينك في معروف»… بيعة على الطاعة في كل معروف؛ فأي معروف أؤخّره اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (410, 61, 1, 14, 'سورة الصف ١ – ١٤', 'الصف: لم تقولون ما لا تفعلون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 410) = $j$[{"lbl": "الآيات ١ – ٦", "q": "سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ ﴿٢﴾ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُواْ مَا لَا تَفۡعَلُونَ ﴿٣﴾ إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفّٗا كَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ ﴿٤﴾ وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ لِمَ تُؤۡذُونَنِي وَقَد تَّعۡلَمُونَ أَنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡۖ فَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٥﴾ وَإِذۡ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُم مُّصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ فَلَمَّا جَآءَهُم بِٱلۡبَيِّنَٰتِ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ ﴿٦﴾", "w": [["سبّح لله ما في السماوات وما في الأرض", "نزّه وقدّس بلسان القال والحال جميع ما في السماوات وما في الأرض من كائنات."], ["وهو العزيز الحكيم", "الغالب على أمره، الحكيم في تدبيره وصنعه."], ["لم تقولون ما لا تفعلون", "لأي شيء تقولون فعلنا كذا وكذا وأنتم لم تفعلوا؟ والاستفهام للتوبيخ."], ["كبُر مقتاً عند الله", "عظم مقتاً، والمقت أشد البغض."], ["أن تقولوا ما لا تفعلون", "قولكم ما لا تفعلون يبغضه الله أشد البغض."], ["صفّاً كأنهم بنيان مرصوص", "صافّين، ملزق بعضه ببعض لا فرجة فيه."], ["لم تؤذونني", "إذ رموه بعيب في بدنه كذباً، فوبّخهم على كذبهم وأذيّتهم له."], ["وقد تعلمون أني رسول الله إليكم", "أتؤذونني والحال أنكم تعلمون أني رسول الله إليكم؟"], ["فلما زاغوا أزاغ الله قلوبهم", "فلما عدلوا عن الحق بإيذائهم موسى، أمال الله قلوبهم عن الهدى."], ["والله لا يهدي القوم الفاسقين", "الذين توغّلوا في الفسق فما أصبحوا أهلاً للهداية."], ["يا بني إسرائيل", "أولاد يعقوب الملقّب بإسرائيل، ولم يقل يا قوم كما قال موسى، لأنه وُلد بلا أب."], ["مصدّقاً لما بين يديّ من التوراة", "لما قبلي من التوراة."], ["يأتي من بعدي اسمه أحمد", "هو محمد رسول الله ﷺ، وأحمد أحد أسمائه: محمد وأحمد والماحي والعاقب والحاشر."], ["فلما جاءهم بالبيّنات", "بالمعجزات الباهرات على صدق رسالته."], ["قالوا هذا سحر مبين", "قالوا في المعجزات إنها سحر."]], "m": "يخبر تعالى أنه قد سبّحه جميع ما في السماوات وما في الأرض بلسان القال والحال، وأنه العزيز الغالب على أمره، الحكيم في صنعه وتدبيره لملكه. ثم خاطب المؤمنين: يا أيها الذين آمنوا لم تقولون ما لا تفعلون؟ لفظ النداء عام، والمراد به جماعة من المؤمنين قالوا: لو نعلم أحب الأعمال إلى الله لفعلناه، فلما علموه ضعفوا عنه، فعاتبهم الله في هذه الآية لتبقى تشريعاً عاماً إلى يوم القيامة: فكل من يقول فعلت ولم يفعل فقد كذب، ومن قال سأفعل ولم يفعل فهو مخلف للوعد، وهكذا يربّي الله عباده على الصدق والوفاء. كبر مقتاً عند الله أن تقولوا نفعل ولم تفعلوا. إن الله يحب الذين يقاتلون في سبيله صافّين متلاصقين لا فرجة بينهم، كأنهم بنيان مرصوص لا خلل فيه، كأنه ملحم بالرصاص. واذكر إذ قال موسى لقومه من بني إسرائيل: يا قوم لم تؤذونني والحال أنكم تعلمون أني رسول الله إليكم حقاً؟ وقد آذوه بشتى أنواع الأذى بألسنتهم السليطة وآرائهم الشاذة، ومن ذلك رميهم إياه بعيب في بدنه. فلما مالوا عن الحق بعد علمه غاية العلم فآثروا الباطل على الحق، عاقبهم الله فصرف قلوبهم عن الهدى؛ وذلك سنّته تعالى فيمن عُرض عليه الخير فأباه بعد علمه به، ودُعي إليه فلم يستجب، وواصل الشر مختاراً له، عندئذ يصبح ما اختاره من الفسق أو الكفر أو الظلم طبعاً له لا يتبدّل. واذكر يا رسولنا قول عيسى ابن مريم: يا بني إسرائيل إني رسول الله إليكم مصدّقاً لما بين يديّ من التوراة، وهذا برهان على صدقي، إذ لم أخالف فيما أدعو إليه ما في التوراة، فوفاقنا دالّ على أن مصدر تشريعنا واحد، ومبشّراً برسول يأتي من بعدي اسمه أحمد، ولهذا قال رسول الله ﷺ: «أنا دعوة أبي إبراهيم وبشارة عيسى». فلما جاءهم محمد ﷺ بالحجج الدالة على صدق رسالته كفروا به وقالوا في القرآن: هذا سحر مبين، كما قالها فرعون مع موسى، وكما قالتها اليهود مع عيسى ﵇.", "h": ["بيان غنى الله تعالى عن خلقه، وأن ما شرعه لعباده من العبادات والشرائع إنما هو لفائدتهم وصالح أنفسهم، يكملون عليه أرواحاً وأخلاقاً.", "حرمة الكذب وخلف الوعد، إذ قول القائل: أفعل كذا ولم يفعل، كذب وخلف وعد، ولذا كان قوله من المقت الذي هو أشد البغض، ومن مقته الله فقد أبغضه أشد البغض.", "فضيلة الجهاد والوحدة والاتفاق، وحرمة الخلاف، والقتال والصفوف ممزّقة حسّياً أو معنوياً.", "التحذير من مواصلة الذنب بعد الذنب، فإنه يؤدّي إلى الطبع وحرمان الهداية.", "بيان كفر اليهود بعيسى ﵇، وازديادهم كفراً بكفرهم بمحمد ﷺ.", "بيان كفر النصارى إذ رفضوا بشارة عيسى وردّوها عليه، ولم يؤمنوا بالمبشَّر به محمد ﷺ."], "k": "«لم تقولون ما لا تفعلون»… كم وعداً لنفسي أو لغيري قلته ولم أفعله؟"}, {"lbl": "الآيات ٧ – ٩", "q": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ يُدۡعَىٰٓ إِلَى ٱلۡإِسۡلَٰمِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٧﴾ يُرِيدُونَ لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ﴿٨﴾ هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ﴿٩﴾", "w": [["ومن أظلم ممن افترى على الله الكذب", "لا أحد أعظم ظلماً ممن يكذب على الله فينسب إليه الولد والشريك، والقول والحكم، وهو تعالى بريء من ذلك."], ["وهو يُدعى إلى الإسلام", "والحال أن هذا المفتري يُدعى إلى الإسلام، الذي هو الاستسلام والانقياد لحكم الله وشرعه."], ["والله لا يهدي القوم الظالمين", "من ظلم ثم ظلم وواصل الظلم يصبح الظلم طبعاً له، فلا يكون قابلاً للهداية."], ["يريدون ليطفئوا نور الله بأفواههم", "يريد المشركون بكذبهم على الله وتشويه الدعوة ومحاربة أهلها إطفاء نور الله القرآن بأفواههم، وهذا محال."], ["هو الذي أرسل رسوله بالهدى", "أرسل محمداً ﷺ بالهداية للبشرية."], ["ودين الحق", "الإسلام، إذ هو الدين الحق الثابت بالوحي الصادق."], ["ليظهره على الدين كله", "لينصره على سائر الأديان."], ["ولو كره المشركون", "ولو كره نصره وظهوره على الأديان المشركون الكافرون."]], "m": "لا أظلم ممن اختلق الكذب على الله فقال: قال كذا أو شرع كذا وهو لم يقل ولم يشرع، كما هي حال مشركي قريش، نسبوا إليه الولد والشريك، وحرّموا السوائب والبحائر، وقالوا في عبادة أصنامهم: لو شاء الله ما عبدناهم، والحال أنه يُدعى إلى الإسلام؛ إذ لو كان أيام الجاهلية حيث لا رسول ولا قرآن لهان الأمر، أما أن يكذب على الله والنور غامر والوحي ينزل والرسول يدعو ويبيّن فالجرم أعظم والظلم أظلم. والله لا يهدي القوم الظالمين. يريد أولئك الكاذبون، القائلون في الرسول ساحر وفي القرآن سحر مبين، إطفاء نور الله، الذي هو القرآن وما حواه من عقائد الحق وشرائع الهدى، بأفواههم! وهل نور الله يُطفأ بالأفواه كنور شمعة أو مصباح؟ إن إطفاء نور القمر أو الشمس أيسر من إطفائه، فليكفّوا عن محاولاتهم الفاشلة، فإن الله متمّ نوره ولو كره الكافرون. هو الذي أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله، وذلك حين نزول عيسى، إذ يبطل يومها كل دين ولا يبقى إلا الإسلام، ولو كره ذلك المشركون، فإن الله مظهره لا محالة.", "h": ["عظم جرم الكذب على الله، وأنه من أفظع أنواع الظلم.", "حرمان الظلمة المتوغّلين في الظلم من الهداية.", "إيئاس المحاولين إبطال الإسلام وإنهاء وجوده بأنهم لا يقدرون، إذ الله تعالى أراد إظهاره، فهو ظاهر منصور لا محالة.", "تقرير نبوة محمد ﷺ."], "k": "«والله متمّ نوره»… النور سيتمّ بي أو بغيري؛ فهل أريد أن أكون من حامليه؟"}, {"lbl": "الآيات ١٠ – ١٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَٰرَةٖ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمٖ ﴿١٠﴾ تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿١١﴾ يَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّـٰتِ عَدۡنٖۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٢﴾ وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرٞ مِّنَ ٱللَّهِ وَفَتۡحٞ قَرِيبٞۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿١٣﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ لِلۡحَوَارِيِّـۧنَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّآئِفَةٞ مِّنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ وَكَفَرَت طَّآئِفَةٞۖ فَأَيَّدۡنَا ٱلَّذِينَ ءَامَنُواْ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُواْ ظَٰهِرِينَ ﴿١٤﴾", "w": [["هل أدلّكم على تجارة", "أرشدكم إلى تجارة رابحة."], ["تنجيكم من عذاب أليم", "الربح فيها نجاتكم من عذاب مؤلم."], ["تؤمنون بالله ورسوله", "تصدّقون بالله رباً وإلهاً، وبمحمد نبياً ورسولاً."], ["وتجاهدون في سبيل الله بأموالكم وأنفسكم", "تبذلون أموالكم وأرواحكم جهاداً في سبيل الله."], ["ذلكم خير لكم إن كنتم تعلمون", "الدخول في هذه الصفقة الرابحة خير لكم من تركها حرصاً على بقائكم وبقاء أموالكم، مع أنه لا بقاء لشيء."], ["يغفر لكم ذنوبكم ويدخلكم جنات", "هذا هو الربح الصافي مقابل ذلك الثمن الزائل، مع أن الكل لله واهبكم أنفسكم وأموالكم."], ["ومساكن طيبة في جنات عدن", "إقامة دائمة."], ["ذلك الفوز العظيم", "النجاة من النار ودخول الجنة هو حقاً الفوز العظيم."], ["وأخرى تحبّونها نصر من الله وفتح قريب", "وعلاوة أخرى تحبونها: نصر من الله لكم ولدينكم، وفتح قريب للأمصار والمدن."], ["وبشّر المؤمنين", "بشّر يا رسولنا المؤمنين الصادقين بذاك الفوز وهذه العلاوة."], ["كونوا أنصار الله", "لتنصروا دينه ونبيه وأولياءه."], ["كما قال عيسى ابن مريم للحواريين من أنصاري إلى الله", "فكونوا أنتم مثل الحواريين، وهم أصحاب عيسى وأول من آمن به، وكانوا اثني عشر رجلاً."], ["فآمنت طائفة من بني إسرائيل", "بعيسى ﵇، وقالوا: إنه عبد الله رُفع إلى السماء."], ["وكفرت طائفة", "قالوا: إنه ابن الله رفعه إليه."], ["فأيّدنا الذين آمنوا على عدوهم", "فاقتتلت الطائفتان، فنصرنا وقوّينا الذين آمنوا."], ["فأصبحوا ظاهرين", "غالبين عالين."]], "m": "يا من صدّقتم الله ورسوله، هل ندلّكم على تجارة عظيمة الربح ثمرتها النجاة من عذاب أليم في الدنيا والآخرة؟ رأس المال الذي تقدّمونه: إيمان بالله ورسوله حق الإيمان، وجهاد في سبيل الله بالنفس والمال، وهذه الصفقة خير لكم من عدمها إن كنتم تعلمون ربحها. والربح: النجاة من العذاب الدنيوي والأخروي أولاً، ثم مغفرة ذنوبكم، وإدخالكم جنات تجري من تحت قصورها وأشجارها الأنهار، ومساكن طيبة في جنات إقامة دائمة، ذلك الفوز العظيم، فلا فوز أعظم منه قط. ولكم علاوة على ذلك يحبّونها: نصر من الله لكم على أعدائكم، ولدينكم على سائر الأديان، وفتح قريب لمكة ولباقي المدن، وبشّر المؤمنين يا رسولنا بحصول ما ذكرناه، وقد تمّ لهم كاملاً ولله الحمد. ثم ناداهم نداءً ثانياً بعنوان الإيمان، إذ الإيمان هو الطاقة المحرّكة الدافعة: كونوا أنصار الله في دينه ونبيه وأوليائه، كما قال الحواريون لما دعاهم عيسى لنصرته قائلاً: من أنصاري إلى الله؟ فأجابوه: نحن أنصار الله، فكونوا أنتم أيها المسلمون مثلهم، وقد كانوا رضي الله عنهم كما طُلب منهم. فآمنت طائفة من بني إسرائيل بأن عيسى عبد الله ورسوله رفعه ربه إلى السماء، وكفرت طائفة فقالت: عيسى ابن الله، فاقتتلوا، فأيّدنا ونصرنا الذين آمنوا على عدوهم فأصبحوا غالبين، إلى أن احتال اليهود على إفساد الدين الذي جاء به عيسى، فلم يبق من المؤيدين إلا قليلون، وعلا الكفر والتثليث، واستمر ذلك إلى أن بعث الله محمداً ﷺ، فانضمّ إلى الإسلام من انضم من النصارى فأصبحوا بالإسلام ظاهرين، والإسلام تعهّد الله بحفظه إلى يوم القيامة، فمن أراده وجده صافياً كما نزل في كتاب الله وسنة رسوله ﷺ.", "h": ["فضل الجهاد بالمال والنفس، وأنه أعظم تجارة رابحة.", "تحقيق بشرى المؤمنين التي أمر الله رسوله أن يبشّرهم بها، فكان هذا برهاناً على صحة الإسلام.", "بيان استجابة أصحاب رسول الله ﷺ لما طُلب منهم من نصرة رسول الله ﷺ ودينه والمؤمنين معه، وهي نصرة الله تعالى المطلوبة."], "k": "«هل أدلّكم على تجارة تنجيكم من عذاب أليم»… أحسب أرباحي في الدنيا بدقة؛ فهل أحسب هذه التجارة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 410;
insert into public.tdb_cards(topic, i, body) select 410, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ ﴿٢﴾ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُواْ مَا لَا تَفۡعَلُونَ ﴿٣﴾ إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفّٗا كَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ ﴿٤﴾ وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ لِمَ تُؤۡذُونَنِي وَقَد تَّعۡلَمُونَ أَنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡۖ فَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٥﴾ وَإِذۡ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُم مُّصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ فَلَمَّا جَآءَهُم بِٱلۡبَيِّنَٰتِ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ ﴿٦﴾", "w": [["سبّح لله ما في السماوات وما في الأرض", "نزّه وقدّس بلسان القال والحال جميع ما في السماوات وما في الأرض من كائنات."], ["وهو العزيز الحكيم", "الغالب على أمره، الحكيم في تدبيره وصنعه."], ["لم تقولون ما لا تفعلون", "لأي شيء تقولون فعلنا كذا وكذا وأنتم لم تفعلوا؟ والاستفهام للتوبيخ."], ["كبُر مقتاً عند الله", "عظم مقتاً، والمقت أشد البغض."], ["أن تقولوا ما لا تفعلون", "قولكم ما لا تفعلون يبغضه الله أشد البغض."], ["صفّاً كأنهم بنيان مرصوص", "صافّين، ملزق بعضه ببعض لا فرجة فيه."], ["لم تؤذونني", "إذ رموه بعيب في بدنه كذباً، فوبّخهم على كذبهم وأذيّتهم له."], ["وقد تعلمون أني رسول الله إليكم", "أتؤذونني والحال أنكم تعلمون أني رسول الله إليكم؟"], ["فلما زاغوا أزاغ الله قلوبهم", "فلما عدلوا عن الحق بإيذائهم موسى، أمال الله قلوبهم عن الهدى."], ["والله لا يهدي القوم الفاسقين", "الذين توغّلوا في الفسق فما أصبحوا أهلاً للهداية."], ["يا بني إسرائيل", "أولاد يعقوب الملقّب بإسرائيل، ولم يقل يا قوم كما قال موسى، لأنه وُلد بلا أب."], ["مصدّقاً لما بين يديّ من التوراة", "لما قبلي من التوراة."], ["يأتي من بعدي اسمه أحمد", "هو محمد رسول الله ﷺ، وأحمد أحد أسمائه: محمد وأحمد والماحي والعاقب والحاشر."], ["فلما جاءهم بالبيّنات", "بالمعجزات الباهرات على صدق رسالته."], ["قالوا هذا سحر مبين", "قالوا في المعجزات إنها سحر."]], "m": "يخبر تعالى أنه قد سبّحه جميع ما في السماوات وما في الأرض بلسان القال والحال، وأنه العزيز الغالب على أمره، الحكيم في صنعه وتدبيره لملكه. ثم خاطب المؤمنين: يا أيها الذين آمنوا لم تقولون ما لا تفعلون؟ لفظ النداء عام، والمراد به جماعة من المؤمنين قالوا: لو نعلم أحب الأعمال إلى الله لفعلناه، فلما علموه ضعفوا عنه، فعاتبهم الله في هذه الآية لتبقى تشريعاً عاماً إلى يوم القيامة: فكل من يقول فعلت ولم يفعل فقد كذب، ومن قال سأفعل ولم يفعل فهو مخلف للوعد، وهكذا يربّي الله عباده على الصدق والوفاء. كبر مقتاً عند الله أن تقولوا نفعل ولم تفعلوا. إن الله يحب الذين يقاتلون في سبيله صافّين متلاصقين لا فرجة بينهم، كأنهم بنيان مرصوص لا خلل فيه، كأنه ملحم بالرصاص. واذكر إذ قال موسى لقومه من بني إسرائيل: يا قوم لم تؤذونني والحال أنكم تعلمون أني رسول الله إليكم حقاً؟ وقد آذوه بشتى أنواع الأذى بألسنتهم السليطة وآرائهم الشاذة، ومن ذلك رميهم إياه بعيب في بدنه. فلما مالوا عن الحق بعد علمه غاية العلم فآثروا الباطل على الحق، عاقبهم الله فصرف قلوبهم عن الهدى؛ وذلك سنّته تعالى فيمن عُرض عليه الخير فأباه بعد علمه به، ودُعي إليه فلم يستجب، وواصل الشر مختاراً له، عندئذ يصبح ما اختاره من الفسق أو الكفر أو الظلم طبعاً له لا يتبدّل. واذكر يا رسولنا قول عيسى ابن مريم: يا بني إسرائيل إني رسول الله إليكم مصدّقاً لما بين يديّ من التوراة، وهذا برهان على صدقي، إذ لم أخالف فيما أدعو إليه ما في التوراة، فوفاقنا دالّ على أن مصدر تشريعنا واحد، ومبشّراً برسول يأتي من بعدي اسمه أحمد، ولهذا قال رسول الله ﷺ: «أنا دعوة أبي إبراهيم وبشارة عيسى». فلما جاءهم محمد ﷺ بالحجج الدالة على صدق رسالته كفروا به وقالوا في القرآن: هذا سحر مبين، كما قالها فرعون مع موسى، وكما قالتها اليهود مع عيسى ﵇.", "h": ["بيان غنى الله تعالى عن خلقه، وأن ما شرعه لعباده من العبادات والشرائع إنما هو لفائدتهم وصالح أنفسهم، يكملون عليه أرواحاً وأخلاقاً.", "حرمة الكذب وخلف الوعد، إذ قول القائل: أفعل كذا ولم يفعل، كذب وخلف وعد، ولذا كان قوله من المقت الذي هو أشد البغض، ومن مقته الله فقد أبغضه أشد البغض.", "فضيلة الجهاد والوحدة والاتفاق، وحرمة الخلاف، والقتال والصفوف ممزّقة حسّياً أو معنوياً.", "التحذير من مواصلة الذنب بعد الذنب، فإنه يؤدّي إلى الطبع وحرمان الهداية.", "بيان كفر اليهود بعيسى ﵇، وازديادهم كفراً بكفرهم بمحمد ﷺ.", "بيان كفر النصارى إذ رفضوا بشارة عيسى وردّوها عليه، ولم يؤمنوا بالمبشَّر به محمد ﷺ."], "k": "«لم تقولون ما لا تفعلون»… كم وعداً لنفسي أو لغيري قلته ولم أفعله؟"}, {"lbl": "الآيات ٧ – ٩", "q": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ يُدۡعَىٰٓ إِلَى ٱلۡإِسۡلَٰمِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٧﴾ يُرِيدُونَ لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ﴿٨﴾ هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ﴿٩﴾", "w": [["ومن أظلم ممن افترى على الله الكذب", "لا أحد أعظم ظلماً ممن يكذب على الله فينسب إليه الولد والشريك، والقول والحكم، وهو تعالى بريء من ذلك."], ["وهو يُدعى إلى الإسلام", "والحال أن هذا المفتري يُدعى إلى الإسلام، الذي هو الاستسلام والانقياد لحكم الله وشرعه."], ["والله لا يهدي القوم الظالمين", "من ظلم ثم ظلم وواصل الظلم يصبح الظلم طبعاً له، فلا يكون قابلاً للهداية."], ["يريدون ليطفئوا نور الله بأفواههم", "يريد المشركون بكذبهم على الله وتشويه الدعوة ومحاربة أهلها إطفاء نور الله القرآن بأفواههم، وهذا محال."], ["هو الذي أرسل رسوله بالهدى", "أرسل محمداً ﷺ بالهداية للبشرية."], ["ودين الحق", "الإسلام، إذ هو الدين الحق الثابت بالوحي الصادق."], ["ليظهره على الدين كله", "لينصره على سائر الأديان."], ["ولو كره المشركون", "ولو كره نصره وظهوره على الأديان المشركون الكافرون."]], "m": "لا أظلم ممن اختلق الكذب على الله فقال: قال كذا أو شرع كذا وهو لم يقل ولم يشرع، كما هي حال مشركي قريش، نسبوا إليه الولد والشريك، وحرّموا السوائب والبحائر، وقالوا في عبادة أصنامهم: لو شاء الله ما عبدناهم، والحال أنه يُدعى إلى الإسلام؛ إذ لو كان أيام الجاهلية حيث لا رسول ولا قرآن لهان الأمر، أما أن يكذب على الله والنور غامر والوحي ينزل والرسول يدعو ويبيّن فالجرم أعظم والظلم أظلم. والله لا يهدي القوم الظالمين. يريد أولئك الكاذبون، القائلون في الرسول ساحر وفي القرآن سحر مبين، إطفاء نور الله، الذي هو القرآن وما حواه من عقائد الحق وشرائع الهدى، بأفواههم! وهل نور الله يُطفأ بالأفواه كنور شمعة أو مصباح؟ إن إطفاء نور القمر أو الشمس أيسر من إطفائه، فليكفّوا عن محاولاتهم الفاشلة، فإن الله متمّ نوره ولو كره الكافرون. هو الذي أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله، وذلك حين نزول عيسى، إذ يبطل يومها كل دين ولا يبقى إلا الإسلام، ولو كره ذلك المشركون، فإن الله مظهره لا محالة.", "h": ["عظم جرم الكذب على الله، وأنه من أفظع أنواع الظلم.", "حرمان الظلمة المتوغّلين في الظلم من الهداية.", "إيئاس المحاولين إبطال الإسلام وإنهاء وجوده بأنهم لا يقدرون، إذ الله تعالى أراد إظهاره، فهو ظاهر منصور لا محالة.", "تقرير نبوة محمد ﷺ."], "k": "«والله متمّ نوره»… النور سيتمّ بي أو بغيري؛ فهل أريد أن أكون من حامليه؟"}, {"lbl": "الآيات ١٠ – ١٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَٰرَةٖ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمٖ ﴿١٠﴾ تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿١١﴾ يَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّـٰتِ عَدۡنٖۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١٢﴾ وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرٞ مِّنَ ٱللَّهِ وَفَتۡحٞ قَرِيبٞۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿١٣﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ لِلۡحَوَارِيِّـۧنَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّآئِفَةٞ مِّنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ وَكَفَرَت طَّآئِفَةٞۖ فَأَيَّدۡنَا ٱلَّذِينَ ءَامَنُواْ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُواْ ظَٰهِرِينَ ﴿١٤﴾", "w": [["هل أدلّكم على تجارة", "أرشدكم إلى تجارة رابحة."], ["تنجيكم من عذاب أليم", "الربح فيها نجاتكم من عذاب مؤلم."], ["تؤمنون بالله ورسوله", "تصدّقون بالله رباً وإلهاً، وبمحمد نبياً ورسولاً."], ["وتجاهدون في سبيل الله بأموالكم وأنفسكم", "تبذلون أموالكم وأرواحكم جهاداً في سبيل الله."], ["ذلكم خير لكم إن كنتم تعلمون", "الدخول في هذه الصفقة الرابحة خير لكم من تركها حرصاً على بقائكم وبقاء أموالكم، مع أنه لا بقاء لشيء."], ["يغفر لكم ذنوبكم ويدخلكم جنات", "هذا هو الربح الصافي مقابل ذلك الثمن الزائل، مع أن الكل لله واهبكم أنفسكم وأموالكم."], ["ومساكن طيبة في جنات عدن", "إقامة دائمة."], ["ذلك الفوز العظيم", "النجاة من النار ودخول الجنة هو حقاً الفوز العظيم."], ["وأخرى تحبّونها نصر من الله وفتح قريب", "وعلاوة أخرى تحبونها: نصر من الله لكم ولدينكم، وفتح قريب للأمصار والمدن."], ["وبشّر المؤمنين", "بشّر يا رسولنا المؤمنين الصادقين بذاك الفوز وهذه العلاوة."], ["كونوا أنصار الله", "لتنصروا دينه ونبيه وأولياءه."], ["كما قال عيسى ابن مريم للحواريين من أنصاري إلى الله", "فكونوا أنتم مثل الحواريين، وهم أصحاب عيسى وأول من آمن به، وكانوا اثني عشر رجلاً."], ["فآمنت طائفة من بني إسرائيل", "بعيسى ﵇، وقالوا: إنه عبد الله رُفع إلى السماء."], ["وكفرت طائفة", "قالوا: إنه ابن الله رفعه إليه."], ["فأيّدنا الذين آمنوا على عدوهم", "فاقتتلت الطائفتان، فنصرنا وقوّينا الذين آمنوا."], ["فأصبحوا ظاهرين", "غالبين عالين."]], "m": "يا من صدّقتم الله ورسوله، هل ندلّكم على تجارة عظيمة الربح ثمرتها النجاة من عذاب أليم في الدنيا والآخرة؟ رأس المال الذي تقدّمونه: إيمان بالله ورسوله حق الإيمان، وجهاد في سبيل الله بالنفس والمال، وهذه الصفقة خير لكم من عدمها إن كنتم تعلمون ربحها. والربح: النجاة من العذاب الدنيوي والأخروي أولاً، ثم مغفرة ذنوبكم، وإدخالكم جنات تجري من تحت قصورها وأشجارها الأنهار، ومساكن طيبة في جنات إقامة دائمة، ذلك الفوز العظيم، فلا فوز أعظم منه قط. ولكم علاوة على ذلك يحبّونها: نصر من الله لكم على أعدائكم، ولدينكم على سائر الأديان، وفتح قريب لمكة ولباقي المدن، وبشّر المؤمنين يا رسولنا بحصول ما ذكرناه، وقد تمّ لهم كاملاً ولله الحمد. ثم ناداهم نداءً ثانياً بعنوان الإيمان، إذ الإيمان هو الطاقة المحرّكة الدافعة: كونوا أنصار الله في دينه ونبيه وأوليائه، كما قال الحواريون لما دعاهم عيسى لنصرته قائلاً: من أنصاري إلى الله؟ فأجابوه: نحن أنصار الله، فكونوا أنتم أيها المسلمون مثلهم، وقد كانوا رضي الله عنهم كما طُلب منهم. فآمنت طائفة من بني إسرائيل بأن عيسى عبد الله ورسوله رفعه ربه إلى السماء، وكفرت طائفة فقالت: عيسى ابن الله، فاقتتلوا، فأيّدنا ونصرنا الذين آمنوا على عدوهم فأصبحوا غالبين، إلى أن احتال اليهود على إفساد الدين الذي جاء به عيسى، فلم يبق من المؤيدين إلا قليلون، وعلا الكفر والتثليث، واستمر ذلك إلى أن بعث الله محمداً ﷺ، فانضمّ إلى الإسلام من انضم من النصارى فأصبحوا بالإسلام ظاهرين، والإسلام تعهّد الله بحفظه إلى يوم القيامة، فمن أراده وجده صافياً كما نزل في كتاب الله وسنة رسوله ﷺ.", "h": ["فضل الجهاد بالمال والنفس، وأنه أعظم تجارة رابحة.", "تحقيق بشرى المؤمنين التي أمر الله رسوله أن يبشّرهم بها، فكان هذا برهاناً على صحة الإسلام.", "بيان استجابة أصحاب رسول الله ﷺ لما طُلب منهم من نصرة رسول الله ﷺ ودينه والمؤمنين معه، وهي نصرة الله تعالى المطلوبة."], "k": "«هل أدلّكم على تجارة تنجيكم من عذاب أليم»… أحسب أرباحي في الدنيا بدقة؛ فهل أحسب هذه التجارة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (411, 62, 1, 11, 'سورة الجمعة ١ – ١١', 'الجمعة: فاسعوا إلى ذكر الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 411) = $j$[{"lbl": "الآيات ١ – ٤", "q": "يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿١﴾ هُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّـۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ ﴿٢﴾ وَءَاخَرِينَ مِنۡهُمۡ لَمَّا يَلۡحَقُواْ بِهِمۡۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٣﴾ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٤﴾", "w": [["يسبّح لله ما في السماوات وما في الأرض", "ينزّه الله تعالى عما لا يليق به ما في السماوات والأرض من سائر الكائنات بلسان القال والحال."], ["في الأميين", "العرب، لندرة من كان يقرأ منهم ويكتب."], ["رسولاً منهم", "محمداً ﷺ، إذ هو عربي قرشي هاشمي."], ["ويزكّيهم", "يطهّرهم أرواحاً وأخلاقاً."], ["ويعلّمهم الكتاب والحكمة", "هدى الكتاب وأسرار هدايته."], ["وإن كانوا من قبل لفي ضلال مبين", "وإن كانوا من قبل بعثة الرسول في ضلال الشرك والجاهلية."], ["وآخرين منهم لمّا يلحقوا بهم", "وآخرين مؤمنين صالحين لم يحضروا حياة رسول الله ﷺ، وهم كل من لم يحضرها من العرب والعجم."], ["ذلك فضل الله يؤتيه من يشاء", "كون الصحابة حازوا فضل السبق فضل يؤتيه من يشاء، فليكن الرضا وسؤال الله من فضله."]], "m": "يخبر تعالى عن نفسه أنه يسبّحه، أي ينزّهه عن كل ما لا يليق بجلاله وكماله، ما في السماوات وما في الأرض بلسان الحال والقال، كقوله: «وإن من شيء إلا يسبّح بحمده ولكن لا تفقهون تسبيحهم»، ومع هذا شرع لنا ذكره وتسبيحه وجعله عوناً لنا على تحمّل المشاق، ووعد على لسان رسوله بالجزاء العظيم عليه، في مثل قوله ﷺ: «من قال سبحان الله وبحمده مائة مرة غُفرت ذنوبه ولو كانت مثل زبد البحر»، وقوله: «كلمتان ثقيلتان في الميزان، خفيفتان على اللسان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم». الملك القدّوس: المالك الحاكم المتصرّف في سائر خلقه، المنزّه عن كل نقص، العزيز الغالب على أمره، الحكيم في صنعه وتدبيره. هو الذي بعث في الأمة العربية الأمية رسولاً منهم، هو محمد ﷺ، عربي قرشي هاشمي معروف النسب إلى عدنان من ولد إسماعيل بن إبراهيم الخليل، يتلو عليهم آيات الله لهدايتهم وإصلاحهم، ويطهّرهم أرواحاً وأخلاقاً وأجساماً من كل ما يدنّس الجسم والنفس ويفسد الخلق، ويعلّمهم معاني الكتاب وما حواه من شرائع وأحكام، ويعلّمهم الحكمة والإصابة والسداد في كل شؤونهم، والحال أنهم كانوا من قبل بعثته في ضلال مبين: في العقائد والآداب والأخلاق والحكم والسياسة. وآخرين من العرب والعجم جاؤوا من بعدهم، التابعين وتابعيهم إلى يوم القيامة، آمنوا وتعلّموا الكتاب والحكمة، لم يلحقوا بهم في الفضل، لأن الصحابة فازوا بالسبق إلى الإيمان وبصحبة رسول الله ﷺ، وذلك فضل الله يؤتيه من يشاء، والله ذو الفضل العظيم.", "h": ["تقرير التوحيد.", "تقرير النبوة المحمدية.", "بيان فضل الصحابة على غيرهم.", "شرف الإيمان والمتابعة للرسول ﷺ وأصحابه رضي الله عنهم."], "k": "«يتلو عليهم آياته ويزكّيهم»… التلاوة بلا تزكية ناقصة؛ فهل تغيّرني الآيات التي أقرؤها؟"}, {"lbl": "الآيات ٥ – ٨", "q": "مَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥﴾ قُلۡ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓاْ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ ﴿٦﴾ وَلَا يَتَمَنَّوۡنَهُۥٓ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ ﴿٧﴾ قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِي تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَٰقِيكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٨﴾", "w": [["مثل الذين حُمّلوا التوراة", "كُلّفوا بالعمل بها عقائد وعبادات وقضاءً وآداباً وأخلاقاً."], ["ثم لم يحملوها", "لم يعملوا بما فيها، ومن ذلك نعت النبي ﷺ والأمر بالإيمان به، فجحدوه وحرّفوه."], ["كمثل الحمار يحمل أسفاراً", "كتباً من العلم وهو لا يدري ما فيها."], ["بئس مثل القوم الذين كذّبوا بآيات الله", "المصدّقة لنبي محمد ﷺ."], ["قل يا أيها الذين هادوا", "اليهود المتديّنون باليهودية."], ["إن زعمتم أنكم أولياء لله من دون الناس", "وأنكم أبناء الله وأحباؤه، وأن الجنة خاصة بكم."], ["فتمنّوا الموت إن كنتم صادقين", "مؤثرين الآخرة على الدنيا، ومبدأ الآخرة الموت، فتمنّوه إذاً."], ["بما قدّمت أيديهم", "بسبب ما قدّموه من الكفر والتكذيب بالنبي ﷺ لا يتمنّونه."], ["والله عليم بالظالمين", "ولازم علمه بهم أنه يجزيهم بظلمهم العذاب."], ["تفرّون منه", "لأنكم لا تتمنّونه أبداً، وذلك عين الفرار منه."], ["فإنه ملاقيكم", "حيثما اتجهتم فإنه ملاقيكم وجهاً لوجه."], ["ثم تُردّون إلى عالم الغيب والشهادة", "إلى الله تعالى يوم القيامة."]], "m": "مثل الذين كُلّفوا بالعمل بالتوراة من اليهود ثم لم يعملوا بما فيها من أحكام وشرائع، ومن ذلك جحدهم لنعوت النبي محمد ﷺ والأمر بالإيمان به واتباعه عند ظهوره، كمثل الحمار يحمل على ظهره أسفاراً من كتب العلم النافع وهو لا يعقل ما يحمل ولا يدري ماذا عليه من الخير، لأنه لا يقرأ ولا يفهم. بئس مثل القوم الذين كذّبوا بآيات الله المصدّقة للنبي محمد ﷺ، والله لا يهدي القوم الظالمين، ولهذا ما هداهم إلى الإسلام لتوغّلهم في الظلم والكفر. قل يا رسولنا: يا من يدّعون أنهم على الملة اليهودية، إن زعمتم أنكم أولياء لله من دون الناس، حيث ادّعيتم أنكم أبناء الله وأحباؤه وأن الجنة لكم دون غيركم، فتمنّوا الموت إن كنتم صادقين، إذ الموت طريق الدار الآخرة. ولا يتمنّونه أبداً، أخبر تعالى وهو العليم أنهم لا يتمنّونه في يوم من الأيام، بسبب ما قدّمت أيديهم من الذنوب الموجبة للعذاب، والله عليم بالظالمين وسيجزيهم. قل لهم يا رسولنا: إن الموت الذي تفرّون منه فإنه ملاقيكم لا محالة حيثما كنتم، ثم تُردّون إلى الله عالم الغيب والشهادة، الذي يعلم ما غاب في السماء والأرض وما يسرّ عباده وما يعلنون، فينبّئكم بما كنتم تعملون ويجزيكم الجزاء العادل.", "h": ["ذمّ من يحفظ كتاب الله ولم يعمل بما فيه.", "التنديد بالظلم والظالمين.", "بيان كذب اليهود وتدجيلهم في أنهم أولياء الله وأن الجنة خالصة لهم.", "بيان أن ذوي الجرائم أكثر الناس خوفاً من الموت وفراراً منه."], "k": "«كمثل الحمار يحمل أسفاراً»… أحمل في صدري آيات كثيرة؛ فكم منها أعمل به؟"}, {"lbl": "الآيات ٩ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٩﴾ فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ﴿١٠﴾ وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ مَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿١١﴾", "w": [["إذا نودي للصلاة", "إذا أذّن المؤذن لها عند جلوس الإمام على المنبر."], ["من يوم الجمعة", "في يوم الجمعة، وذلك بعد الزوال."], ["فاسعوا إلى ذكر الله", "امضوا إلى الصلاة."], ["وذروا البيع", "اتركوه، وإذا لم يكن بيع لم يكن شراء."], ["وابتغوا من فضل الله", "اطلبوا الرزق من الله تعالى بالسعي والعمل."], ["لعلكم تفلحون", "تنجون من النار وتدخلون الجنة."], ["انفضّوا إليها", "خرجوا إلى التجارة."], ["وتركوك قائماً", "على المنبر تخطب يوم الجمعة."], ["ما عند الله خير من اللهو ومن التجارة", "ما عند الله من الثواب في الدار الآخرة خير من اللهو ومن التجارة."], ["والله خير الرازقين", "فاطلبوا الرزق منه بطاعته واتباع هداه."]], "m": "يا من صدّقتم الله ورسوله، إذا أذّن المؤذن بعد زوال يوم الجمعة وجلس الإمام على المنبر، فامضوا إلى ذكر الله، الذي هو الصلاة والخطبة، إذ بهما يُذكر الله، وذروا البيع، إذ هو الغالب من أعمال الناس، وإلا فسائر الأعمال يجب إيقافها والمضيّ إلى الصلاة، ذلكم خير ثواباً وعاقبة إن كنتم تعلمون. فإذا أُدّيت الصلاة وفُرغ منها فلكم أن تتفرّقوا حيث شئتم في أعمال الدين والدنيا تطلبون من فضل الله، واذكروا الله كثيراً أثناء انتشاركم في أعمالكم ولا تنسوه، رجاء فلاحكم في دنياكم وآخرتكم. وإذا رأوا تجارة أو لهواً انفضّوا إليها: نزلت في عادة أهل المدينة إذا جاءت قافلة تجارية تحمل الميرة يستقبلونها بشيء من اللهو كضرب الطبول، وصادف قدومها يوم الجمعة، فلما انقضت الصلاة وطلع رسول الله ﷺ على المنبر يخطب، وكانت الخطبة يومئذ بعد الصلاة، خرج الناس يتسلّلون حتى لم يبق معه إلا اثنا عشر رجلاً وامرأة، فنزلت هذه الآية تعيب عليهم خروجهم وتركهم نبيهم قائماً يخطب. قل يا نبينا: ما عند الله من ثواب الآخرة خير من اللهو والتجارة، والله خير الرازقين، فاطلبوا الرزق منه بطاعته وطاعة رسوله، ولا يتكرّر منكم مثل هذا الصنيع.", "h": ["وجوب صلاة الجمعة، ووجوب المضيّ إليها عند النداء الثاني الذي يكون والإمام على المنبر.", "حرمة البيع والشراء وسائر العقود إذا شرع المؤذن يؤذّن الأذان الثاني.", "الترغيب في ذكر الله والإكثار منه، والمرء يبيع ويشتري ويعمل ويصنع ولسانه ذاكر.", "ينبغي ألا يقلّ المصلون الذين تصح صلاة الجمعة بهم عن اثني عشر رجلاً، أخذاً من حادثة انفضاض الناس عن الرسول ﷺ وهو يخطب."], "k": "«واذكروا الله كثيراً لعلكم تفلحون»… في السوق والعمل أيضاً؛ فهل يذكره لساني وأنا مشغول؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 411;
insert into public.tdb_cards(topic, i, body) select 411, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿١﴾ هُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّـۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ ﴿٢﴾ وَءَاخَرِينَ مِنۡهُمۡ لَمَّا يَلۡحَقُواْ بِهِمۡۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٣﴾ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٤﴾", "w": [["يسبّح لله ما في السماوات وما في الأرض", "ينزّه الله تعالى عما لا يليق به ما في السماوات والأرض من سائر الكائنات بلسان القال والحال."], ["في الأميين", "العرب، لندرة من كان يقرأ منهم ويكتب."], ["رسولاً منهم", "محمداً ﷺ، إذ هو عربي قرشي هاشمي."], ["ويزكّيهم", "يطهّرهم أرواحاً وأخلاقاً."], ["ويعلّمهم الكتاب والحكمة", "هدى الكتاب وأسرار هدايته."], ["وإن كانوا من قبل لفي ضلال مبين", "وإن كانوا من قبل بعثة الرسول في ضلال الشرك والجاهلية."], ["وآخرين منهم لمّا يلحقوا بهم", "وآخرين مؤمنين صالحين لم يحضروا حياة رسول الله ﷺ، وهم كل من لم يحضرها من العرب والعجم."], ["ذلك فضل الله يؤتيه من يشاء", "كون الصحابة حازوا فضل السبق فضل يؤتيه من يشاء، فليكن الرضا وسؤال الله من فضله."]], "m": "يخبر تعالى عن نفسه أنه يسبّحه، أي ينزّهه عن كل ما لا يليق بجلاله وكماله، ما في السماوات وما في الأرض بلسان الحال والقال، كقوله: «وإن من شيء إلا يسبّح بحمده ولكن لا تفقهون تسبيحهم»، ومع هذا شرع لنا ذكره وتسبيحه وجعله عوناً لنا على تحمّل المشاق، ووعد على لسان رسوله بالجزاء العظيم عليه، في مثل قوله ﷺ: «من قال سبحان الله وبحمده مائة مرة غُفرت ذنوبه ولو كانت مثل زبد البحر»، وقوله: «كلمتان ثقيلتان في الميزان، خفيفتان على اللسان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم». الملك القدّوس: المالك الحاكم المتصرّف في سائر خلقه، المنزّه عن كل نقص، العزيز الغالب على أمره، الحكيم في صنعه وتدبيره. هو الذي بعث في الأمة العربية الأمية رسولاً منهم، هو محمد ﷺ، عربي قرشي هاشمي معروف النسب إلى عدنان من ولد إسماعيل بن إبراهيم الخليل، يتلو عليهم آيات الله لهدايتهم وإصلاحهم، ويطهّرهم أرواحاً وأخلاقاً وأجساماً من كل ما يدنّس الجسم والنفس ويفسد الخلق، ويعلّمهم معاني الكتاب وما حواه من شرائع وأحكام، ويعلّمهم الحكمة والإصابة والسداد في كل شؤونهم، والحال أنهم كانوا من قبل بعثته في ضلال مبين: في العقائد والآداب والأخلاق والحكم والسياسة. وآخرين من العرب والعجم جاؤوا من بعدهم، التابعين وتابعيهم إلى يوم القيامة، آمنوا وتعلّموا الكتاب والحكمة، لم يلحقوا بهم في الفضل، لأن الصحابة فازوا بالسبق إلى الإيمان وبصحبة رسول الله ﷺ، وذلك فضل الله يؤتيه من يشاء، والله ذو الفضل العظيم.", "h": ["تقرير التوحيد.", "تقرير النبوة المحمدية.", "بيان فضل الصحابة على غيرهم.", "شرف الإيمان والمتابعة للرسول ﷺ وأصحابه رضي الله عنهم."], "k": "«يتلو عليهم آياته ويزكّيهم»… التلاوة بلا تزكية ناقصة؛ فهل تغيّرني الآيات التي أقرؤها؟"}, {"lbl": "الآيات ٥ – ٨", "q": "مَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥﴾ قُلۡ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓاْ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ ﴿٦﴾ وَلَا يَتَمَنَّوۡنَهُۥٓ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ ﴿٧﴾ قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِي تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَٰقِيكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٨﴾", "w": [["مثل الذين حُمّلوا التوراة", "كُلّفوا بالعمل بها عقائد وعبادات وقضاءً وآداباً وأخلاقاً."], ["ثم لم يحملوها", "لم يعملوا بما فيها، ومن ذلك نعت النبي ﷺ والأمر بالإيمان به، فجحدوه وحرّفوه."], ["كمثل الحمار يحمل أسفاراً", "كتباً من العلم وهو لا يدري ما فيها."], ["بئس مثل القوم الذين كذّبوا بآيات الله", "المصدّقة لنبي محمد ﷺ."], ["قل يا أيها الذين هادوا", "اليهود المتديّنون باليهودية."], ["إن زعمتم أنكم أولياء لله من دون الناس", "وأنكم أبناء الله وأحباؤه، وأن الجنة خاصة بكم."], ["فتمنّوا الموت إن كنتم صادقين", "مؤثرين الآخرة على الدنيا، ومبدأ الآخرة الموت، فتمنّوه إذاً."], ["بما قدّمت أيديهم", "بسبب ما قدّموه من الكفر والتكذيب بالنبي ﷺ لا يتمنّونه."], ["والله عليم بالظالمين", "ولازم علمه بهم أنه يجزيهم بظلمهم العذاب."], ["تفرّون منه", "لأنكم لا تتمنّونه أبداً، وذلك عين الفرار منه."], ["فإنه ملاقيكم", "حيثما اتجهتم فإنه ملاقيكم وجهاً لوجه."], ["ثم تُردّون إلى عالم الغيب والشهادة", "إلى الله تعالى يوم القيامة."]], "m": "مثل الذين كُلّفوا بالعمل بالتوراة من اليهود ثم لم يعملوا بما فيها من أحكام وشرائع، ومن ذلك جحدهم لنعوت النبي محمد ﷺ والأمر بالإيمان به واتباعه عند ظهوره، كمثل الحمار يحمل على ظهره أسفاراً من كتب العلم النافع وهو لا يعقل ما يحمل ولا يدري ماذا عليه من الخير، لأنه لا يقرأ ولا يفهم. بئس مثل القوم الذين كذّبوا بآيات الله المصدّقة للنبي محمد ﷺ، والله لا يهدي القوم الظالمين، ولهذا ما هداهم إلى الإسلام لتوغّلهم في الظلم والكفر. قل يا رسولنا: يا من يدّعون أنهم على الملة اليهودية، إن زعمتم أنكم أولياء لله من دون الناس، حيث ادّعيتم أنكم أبناء الله وأحباؤه وأن الجنة لكم دون غيركم، فتمنّوا الموت إن كنتم صادقين، إذ الموت طريق الدار الآخرة. ولا يتمنّونه أبداً، أخبر تعالى وهو العليم أنهم لا يتمنّونه في يوم من الأيام، بسبب ما قدّمت أيديهم من الذنوب الموجبة للعذاب، والله عليم بالظالمين وسيجزيهم. قل لهم يا رسولنا: إن الموت الذي تفرّون منه فإنه ملاقيكم لا محالة حيثما كنتم، ثم تُردّون إلى الله عالم الغيب والشهادة، الذي يعلم ما غاب في السماء والأرض وما يسرّ عباده وما يعلنون، فينبّئكم بما كنتم تعملون ويجزيكم الجزاء العادل.", "h": ["ذمّ من يحفظ كتاب الله ولم يعمل بما فيه.", "التنديد بالظلم والظالمين.", "بيان كذب اليهود وتدجيلهم في أنهم أولياء الله وأن الجنة خالصة لهم.", "بيان أن ذوي الجرائم أكثر الناس خوفاً من الموت وفراراً منه."], "k": "«كمثل الحمار يحمل أسفاراً»… أحمل في صدري آيات كثيرة؛ فكم منها أعمل به؟"}, {"lbl": "الآيات ٩ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٩﴾ فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ﴿١٠﴾ وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ مَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿١١﴾", "w": [["إذا نودي للصلاة", "إذا أذّن المؤذن لها عند جلوس الإمام على المنبر."], ["من يوم الجمعة", "في يوم الجمعة، وذلك بعد الزوال."], ["فاسعوا إلى ذكر الله", "امضوا إلى الصلاة."], ["وذروا البيع", "اتركوه، وإذا لم يكن بيع لم يكن شراء."], ["وابتغوا من فضل الله", "اطلبوا الرزق من الله تعالى بالسعي والعمل."], ["لعلكم تفلحون", "تنجون من النار وتدخلون الجنة."], ["انفضّوا إليها", "خرجوا إلى التجارة."], ["وتركوك قائماً", "على المنبر تخطب يوم الجمعة."], ["ما عند الله خير من اللهو ومن التجارة", "ما عند الله من الثواب في الدار الآخرة خير من اللهو ومن التجارة."], ["والله خير الرازقين", "فاطلبوا الرزق منه بطاعته واتباع هداه."]], "m": "يا من صدّقتم الله ورسوله، إذا أذّن المؤذن بعد زوال يوم الجمعة وجلس الإمام على المنبر، فامضوا إلى ذكر الله، الذي هو الصلاة والخطبة، إذ بهما يُذكر الله، وذروا البيع، إذ هو الغالب من أعمال الناس، وإلا فسائر الأعمال يجب إيقافها والمضيّ إلى الصلاة، ذلكم خير ثواباً وعاقبة إن كنتم تعلمون. فإذا أُدّيت الصلاة وفُرغ منها فلكم أن تتفرّقوا حيث شئتم في أعمال الدين والدنيا تطلبون من فضل الله، واذكروا الله كثيراً أثناء انتشاركم في أعمالكم ولا تنسوه، رجاء فلاحكم في دنياكم وآخرتكم. وإذا رأوا تجارة أو لهواً انفضّوا إليها: نزلت في عادة أهل المدينة إذا جاءت قافلة تجارية تحمل الميرة يستقبلونها بشيء من اللهو كضرب الطبول، وصادف قدومها يوم الجمعة، فلما انقضت الصلاة وطلع رسول الله ﷺ على المنبر يخطب، وكانت الخطبة يومئذ بعد الصلاة، خرج الناس يتسلّلون حتى لم يبق معه إلا اثنا عشر رجلاً وامرأة، فنزلت هذه الآية تعيب عليهم خروجهم وتركهم نبيهم قائماً يخطب. قل يا نبينا: ما عند الله من ثواب الآخرة خير من اللهو والتجارة، والله خير الرازقين، فاطلبوا الرزق منه بطاعته وطاعة رسوله، ولا يتكرّر منكم مثل هذا الصنيع.", "h": ["وجوب صلاة الجمعة، ووجوب المضيّ إليها عند النداء الثاني الذي يكون والإمام على المنبر.", "حرمة البيع والشراء وسائر العقود إذا شرع المؤذن يؤذّن الأذان الثاني.", "الترغيب في ذكر الله والإكثار منه، والمرء يبيع ويشتري ويعمل ويصنع ولسانه ذاكر.", "ينبغي ألا يقلّ المصلون الذين تصح صلاة الجمعة بهم عن اثني عشر رجلاً، أخذاً من حادثة انفضاض الناس عن الرسول ﷺ وهو يخطب."], "k": "«واذكروا الله كثيراً لعلكم تفلحون»… في السوق والعمل أيضاً؛ فهل يذكره لساني وأنا مشغول؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (412, 63, 1, 11, 'سورة المنافقون ١ – ١١', 'المنافقون: ولله العزة ولرسوله وللمؤمنين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 412) = $j$[{"lbl": "الآيات ١ – ٤", "q": "إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ ﴿١﴾ ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ ﴿٢﴾ ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ ﴿٣﴾ ۞وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبٞ مُّسَنَّدَةٞۖ يَحۡسَبُونَ كُلَّ صَيۡحَةٍ عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ ﴿٤﴾", "w": [["إذا جاءك المنافقون", "إذا حضر مجلسك المنافقون كعبد الله بن أُبيّ وأصحابه."], ["قالوا نشهد إنك لرسول الله", "قالوا ذلك بألسنتهم، وقلوبهم على خلافه."], ["والله يشهد إن المنافقين لكاذبون", "والله يعلم أن المنافقين كاذبون بما أضمروه من أنك غير رسول الله."], ["اتخذوا أيمانهم جُنّة", "سترة ستروا بها أموالهم وحقنوا بها دماءهم."], ["فصدّوا عن سبيل الله", "فصدّوا بها عن الجهاد فيهم."], ["إنهم ساء ما كانوا يعملون", "قبُح ما كانوا يعملونه من النفاق."], ["ذلك بأنهم آمنوا ثم كفروا", "سوء عملهم بأنهم آمنوا بألسنتهم ثم كفروا بقلوبهم واستمروا على ذلك."], ["فطُبع على قلوبهم", "خُتم عليها بالكفر."], ["فهم لا يفقهون", "لا يعرفون معنى الإيمان ولا صحته."], ["تعجبك أجسامهم", "لجمالها، إذ كان ابن أُبيّ جسيماً صحيحاً صبيحاً."], ["وإن يقولوا تسمع لقولهم", "لفصاحتهم وذلاقة ألسنتهم."], ["كأنهم خشب مسنّدة", "كأنهم من عظم أجسامهم وترك التفهّم خشب مسنّدة، أشباح بلا أرواح، وأجسام بلا أحلام."], ["يحسبون كل صيحة عليهم", "يظنّون كل صوت عالٍ يسمعونه عليهم، لما في قلوبهم من الرعب أن ينزل فيهم ما يفضحهم."], ["هم العدوّ فاحذرهم", "العدو التام العداوة، فاحذرهم أن يفشوا سرّك أو يريدوك بسوء."], ["قاتلهم الله أنّى يؤفكون", "لعنهم الله، كيف يُصرفون عن الإيمان وهم يشاهدون أنواره؟"]], "m": "لنزول هذه السورة سبب، هو أن زيد بن أرقم رضي الله عنه قال: كنت مع عمّي فسمعت عبد الله بن أُبيّ بن سلول يقول: لا تنفقوا على من عند رسول الله حتى ينفضّوا، وقال: لئن رجعنا إلى المدينة ليخرجنّ الأعزّ منها الأذل، فذكرت ذلك لعمّي فذكره لرسول الله ﷺ، فأرسل إلى ابن أُبيّ وأصحابه فحلفوا ما قالوا، فصدّقهم رسول الله ﷺ وكذّبني، فأصابني همّ لم يصبني مثله، فجلست في بيتي، فأنزل الله عز وجل: «إذا جاءك المنافقون» إلى قوله: «الأعزّ منها الأذل»، فأرسل إليّ رسول الله ﷺ ثم قال: «إن الله قد صدّقك». إذا حضر مجلسك المنافقون قالوا بألسنتهم دون قلوبهم: نشهد إنك لرسول الله، والله يعلم إنك لرسوله سواء شهدوا أم لم يشهدوا، والله يشهد إنهم لكاذبون لعدم مطابقة قولهم لاعتقادهم. جعلوا أيمانهم الكاذبة سترة كجُنّة المقاتل، وقوا بها أنفسهم وأزواجهم وذرياتهم من القتل والسبي، وبذلك صدّوا عن سبيل الله أنفسهم ومن يقتدي بهم، وصدّوا المؤمنين عن جهادهم بما أظهروه من إيمان صوري كاذب، إنهم ساء ما كانوا يعملون. وقبح سلوكهم ناتج عن كونهم آمنوا ثم شكّوا وارتابوا فنافقوا، فطُبع على قلوبهم فهم لا يفقهون معنى الإيمان، وهذا شأن من توغّل في الكفر أن يُختم على قلبه. وإذا رأيتهم يا رسولنا تعجبك أجسامهم لجمالها، وإن يقولوا تسمع لقولهم لفصاحتهم، كأنهم لطول أجسامهم وعدم فهمهم وقلة الخير فيهم خشب مسنّدة على جدار لا تنفع. يحسبون كل صيحة عليهم، لخوفهم والرعب المتمكّن من نفوسهم نتيجة ما يضمرون من كفر وبغض للإسلام، فإذا سمعوا صيحة في معسكر أو صوت منشد ضالّة توقّعوا أنهم معنيّون بذلك، شأن الخائن، وأكثر ما يخافون أن ينزل القرآن بفضيحتهم. هم العدو فاحذرهم يا رسولنا، إن قلوبهم مع أعدائك. قاتلهم الله، كيف يُصرفون عن الحق وأنواره تغمرهم: القرآن ينزل، والرسول يعلّم ويزكّي، وآثار ذلك في المؤمنين ظاهرة؟", "h": ["بيان أن الكذب ما خالف الاعتقاد وإن طابق الواقع.", "التحذير من الاستمرار على المعصية، فإنه يوجب الطبع على القلب ويحرم صاحبه الهداية.", "التحذير من الاغترار بالمظاهر، كحسن الهندام وفصاحة اللسان.", "الكشف عن نفسية الخائن والظالم والمجرم، وهي الخوف والتخوّف من كل صوت أو كلمة خشية أن يكون ذلك بياناً لحالهم وكشفاً لجرائمهم."], "k": "«تعجبك أجسامهم… كأنهم خشب مسنّدة»… المظهر لا يزن شيئاً عنده؛ فبماذا أهتم أكثر: بمظهري أم بقلبي؟"}, {"lbl": "الآيات ٥ – ٨", "q": "وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡاْ رُءُوسَهُمۡ وَرَأَيۡتَهُمۡ يَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ ﴿٥﴾ سَوَآءٌ عَلَيۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٦﴾ هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّواْۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ ﴿٧﴾ يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ ﴿٨﴾", "w": [["وإذا قيل لهم تعالوا يستغفر لكم رسول الله", "تعالوا معتذرين."], ["لوّوا رؤوسهم", "رفضوا الاعتذار إلى رسول الله ﷺ."], ["ورأيتهم يصدّون وهم مستكبرون", "يعرضون عما دُعوا إليه وهم مستكبرون."], ["سواء عليهم أستغفرت لهم أم لم تستغفر لهم", "يا رسولنا."], ["لن يغفر الله لهم", "ايأس من مغفرة الله لهم."], ["إن الله لا يهدي القوم الفاسقين", "لأن من سنّة الله أنه لا يهدي القوم المتوغّلين في الفسق، وهم كذلك."], ["هم الذين يقولون", "لأهل المدينة."], ["لا تنفقوا على من عند رسول الله", "من المهاجرين."], ["حتى ينفضّوا", "يتفرّقوا عنه."], ["لئن رجعنا إلى المدينة", "من غزوة كانوا فيها، هي غزوة بني المصطلق."], ["ليُخرجنّ الأعزّ منها الأذل", "يعنون بالأعزّ أنفسهم، وبالأذل المؤمنين."], ["ولله العزة ولرسوله وللمؤمنين", "الغلبة والعلو والظهور."]], "m": "ما زال السياق في الحديث عن المنافقين: لما قال ابن أُبيّ ما قال من كلمات خبيثة في غزوة بني المصطلق، ومنها قوله في المهاجرين: سمّن كلبك يأكلك، وقوله: لا تنفقوا على من عند رسول الله حتى يتفرّقوا عنه، وقوله: لئن رجعنا إلى المدينة ليخرجنّ الأعزّ، يعني نفسه ورفاقه، الأذلَّ، يعني المهاجرين والأنصار، وأُخبر به رسول الله ﷺ، فجاء فحلف بالله ما قال شيئاً من ذلك، فنزلت هذه السورة تكذّبه، فجاءه من قال له: يا أبا الحُباب، إنه قد نزل فيك آي شداد، فاذهب إلى رسول الله ﷺ يستغفر لك، فلوى رأسه وقال: أمرتموني أن أؤمن فآمنت، وأمرتموني أن أعطي زكاة مالي فأعطيت، فما بقي إلا أن أسجد لمحمد! فنزلت: وإذا قيل لهم تعالوا معتذرين يستغفر لكم رسول الله لوّوا رؤوسهم رافضين، ورأيتهم يصدّون عنك وهم مستكبرون. سواء عليهم أستغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم، فأيأس رسوله من المغفرة لهم، وعلّل ذلك بأن الله لا يهدي القوم الفاسقين، وابن أُبيّ من أكثرهم فسقاً، إذ جمع بين الكذب والحلف الكاذب والنفاق والكبر والكفر الباطني. هم الذين يقولون: لا تنفقوا على المهاجرين حتى يتفرّقوا عن رسول الله، ولله خزائن السماوات والأرض، فجميع الأرزاق بيده، والمنافق نفسه رزقه على الله، ولكن المنافقين لا يفقهون. والقولة الثانية: لئن رجعنا إلى المدينة ليخرجنّ الأعزّ منها الأذل؛ قالها في غزوة بني المصطلق التي هزم الله فيها بني المصطلق، واصطفى رسول الله ﷺ جويرية بنت سيدهم الحارث فأعتقها وتزوّجها، فأعتق المؤمنون ما بأيديهم من السبي إكراماً لأصهار نبيهم، فقالت عائشة: ما أعلم امرأة كانت أعظم بركة على قومها من جويرية. وفي هذه الغزاة تلاحى أنصاري ومهاجر على الماء، فقال ابن أُبيّ قولته، وغاب عن ذهنه أن العزة لله ولرسوله وللمؤمنين، ولكن المنافقين لا يعلمون. ولما بلغ الغزاة المدينة وقف عبد الله بن عبد الله بن أُبيّ، وكان مؤمناً صادقاً من خيرة الأنصار، في عرض الطريق واستلّ سيفه، فلما جاء أبوه قال له: والله لا تمرّ حتى تقول: محمد الأعزّ وأنا الأذل، فلم يبرح حتى قالها.", "h": ["لا ينفع الاستغفار للكافر ولا الصلاة عليه بحال.", "ذمّ الإعراض والاستكبار عن التوبة والاستغفار؛ فمن قيل له: استغفر الله، فليستغفر ولا يتكبّر، بل عليه أن يقول: أستغفر الله، أو: اللهم اغفر لي.", "مصادر الرزق كلها بيد الله تعالى، فليُطلب الرزق بطاعة الله ورسوله لا بمعصيتهما.", "العزة الحقة لله ولرسوله وللمؤمنين، فلذا يجب على المؤمن ألا يذلّ ولا يهون لكافر."], "k": "«وإذا قيل لهم تعالوا يستغفر لكم… لوّوا رؤوسهم»… حين يُقال لي: استغفر، هل أستغفر فوراً أم أبرّر؟"}, {"lbl": "الآيات ٩ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٩﴾ وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِينَ ﴿١٠﴾ وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١١﴾", "w": [["لا تلهكم أموالكم ولا أولادكم", "لا تشغلكم."], ["عن ذكر الله", "كالصلاة والحج وقراءة القرآن، وذكر الله بالقلب واللسان."], ["ومن يفعل ذلك فأولئك هم الخاسرون", "ومن ألهته أمواله وأولاده عن أداء الفرائض فقد خسر ثواب الآخرة."], ["وأنفقوا مما رزقناكم", "النفقة الواجبة كالزكاة وفي الجهاد، والمستحبة."], ["لولا أخّرتني إلى أجل قريب", "هلّا أخّرتني؟ يطلب التأخير ولا يُقبل منه."], ["فأصّدّق وأكن من الصالحين", "حتى أزكّي وأحج وأكثر من النوافل والأعمال الصالحة."]], "m": "نادى تعالى المؤمنين لينصح لهم ألا تكون حالهم كحال المنافقين الذين تقدّم تأديبهم: يا من آمنتم بالله ورسوله لا تشغلكم أموالكم ولا أولادكم عن ذكر الله بأداء فرائضه واجتناب نواهيه والإكثار من طاعته والتقرّب إليه بأنواع القرب. ثم خوّفهم نصحاً لهم: ومن ألهته أمواله وأولاده عن عبادة الله فأولئك هم الخاسرون يوم القيامة بحرمانهم من الجنة ونعيمها ووجودهم في دار العذاب، لا أهل لهم فيها ولا ولد. وبالغ في إرشادهم فقال: وأنفقوا مما رزقناكم مبادرين الأجل، فإنكم لا تدرون متى تموتون، من قبل أن يأتي أحدكم الموت فيقول متمنّياً طالباً: يا رب لولا أخّرتني إلى وقت قريب من هذا فأتصدّق بمالي، وأكن من الصالحين فأحج وأتقرّب إليك بما تحب. ولن يؤخّر الله نفساً إذا جاء أجلها، وهذا حكمه الأزلي، والله خبير بما تعملون، يحضّ المؤمنين على إصلاح أعمالهم والتزوّد لآخرتهم بإعلامهم بأنه مطّلع على أعمالهم خبير بها.", "h": ["حرمة التشاغل بالمال والولد مع تضييع بعض الفرائض والواجبات.", "حرمة تأخير الحج مع القدرة على أدائه تسويفاً وتماطلاً، مع الإيمان بفرضيته.", "وجوب الزكاة، والترغيب في الصدقات الخاصة كصدقة الجهاد، والعامة على الفقراء.", "تقرير عقيدة البعث والجزاء."], "k": "«لولا أخّرتني إلى أجل قريب فأصّدّق»… أنا الآن في ذلك الأجل الذي سيتمناه غيري؛ فماذا أنتظر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 412;
insert into public.tdb_cards(topic, i, body) select 412, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ ﴿١﴾ ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ ﴿٢﴾ ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ ﴿٣﴾ ۞وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبٞ مُّسَنَّدَةٞۖ يَحۡسَبُونَ كُلَّ صَيۡحَةٍ عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ ﴿٤﴾", "w": [["إذا جاءك المنافقون", "إذا حضر مجلسك المنافقون كعبد الله بن أُبيّ وأصحابه."], ["قالوا نشهد إنك لرسول الله", "قالوا ذلك بألسنتهم، وقلوبهم على خلافه."], ["والله يشهد إن المنافقين لكاذبون", "والله يعلم أن المنافقين كاذبون بما أضمروه من أنك غير رسول الله."], ["اتخذوا أيمانهم جُنّة", "سترة ستروا بها أموالهم وحقنوا بها دماءهم."], ["فصدّوا عن سبيل الله", "فصدّوا بها عن الجهاد فيهم."], ["إنهم ساء ما كانوا يعملون", "قبُح ما كانوا يعملونه من النفاق."], ["ذلك بأنهم آمنوا ثم كفروا", "سوء عملهم بأنهم آمنوا بألسنتهم ثم كفروا بقلوبهم واستمروا على ذلك."], ["فطُبع على قلوبهم", "خُتم عليها بالكفر."], ["فهم لا يفقهون", "لا يعرفون معنى الإيمان ولا صحته."], ["تعجبك أجسامهم", "لجمالها، إذ كان ابن أُبيّ جسيماً صحيحاً صبيحاً."], ["وإن يقولوا تسمع لقولهم", "لفصاحتهم وذلاقة ألسنتهم."], ["كأنهم خشب مسنّدة", "كأنهم من عظم أجسامهم وترك التفهّم خشب مسنّدة، أشباح بلا أرواح، وأجسام بلا أحلام."], ["يحسبون كل صيحة عليهم", "يظنّون كل صوت عالٍ يسمعونه عليهم، لما في قلوبهم من الرعب أن ينزل فيهم ما يفضحهم."], ["هم العدوّ فاحذرهم", "العدو التام العداوة، فاحذرهم أن يفشوا سرّك أو يريدوك بسوء."], ["قاتلهم الله أنّى يؤفكون", "لعنهم الله، كيف يُصرفون عن الإيمان وهم يشاهدون أنواره؟"]], "m": "لنزول هذه السورة سبب، هو أن زيد بن أرقم رضي الله عنه قال: كنت مع عمّي فسمعت عبد الله بن أُبيّ بن سلول يقول: لا تنفقوا على من عند رسول الله حتى ينفضّوا، وقال: لئن رجعنا إلى المدينة ليخرجنّ الأعزّ منها الأذل، فذكرت ذلك لعمّي فذكره لرسول الله ﷺ، فأرسل إلى ابن أُبيّ وأصحابه فحلفوا ما قالوا، فصدّقهم رسول الله ﷺ وكذّبني، فأصابني همّ لم يصبني مثله، فجلست في بيتي، فأنزل الله عز وجل: «إذا جاءك المنافقون» إلى قوله: «الأعزّ منها الأذل»، فأرسل إليّ رسول الله ﷺ ثم قال: «إن الله قد صدّقك». إذا حضر مجلسك المنافقون قالوا بألسنتهم دون قلوبهم: نشهد إنك لرسول الله، والله يعلم إنك لرسوله سواء شهدوا أم لم يشهدوا، والله يشهد إنهم لكاذبون لعدم مطابقة قولهم لاعتقادهم. جعلوا أيمانهم الكاذبة سترة كجُنّة المقاتل، وقوا بها أنفسهم وأزواجهم وذرياتهم من القتل والسبي، وبذلك صدّوا عن سبيل الله أنفسهم ومن يقتدي بهم، وصدّوا المؤمنين عن جهادهم بما أظهروه من إيمان صوري كاذب، إنهم ساء ما كانوا يعملون. وقبح سلوكهم ناتج عن كونهم آمنوا ثم شكّوا وارتابوا فنافقوا، فطُبع على قلوبهم فهم لا يفقهون معنى الإيمان، وهذا شأن من توغّل في الكفر أن يُختم على قلبه. وإذا رأيتهم يا رسولنا تعجبك أجسامهم لجمالها، وإن يقولوا تسمع لقولهم لفصاحتهم، كأنهم لطول أجسامهم وعدم فهمهم وقلة الخير فيهم خشب مسنّدة على جدار لا تنفع. يحسبون كل صيحة عليهم، لخوفهم والرعب المتمكّن من نفوسهم نتيجة ما يضمرون من كفر وبغض للإسلام، فإذا سمعوا صيحة في معسكر أو صوت منشد ضالّة توقّعوا أنهم معنيّون بذلك، شأن الخائن، وأكثر ما يخافون أن ينزل القرآن بفضيحتهم. هم العدو فاحذرهم يا رسولنا، إن قلوبهم مع أعدائك. قاتلهم الله، كيف يُصرفون عن الحق وأنواره تغمرهم: القرآن ينزل، والرسول يعلّم ويزكّي، وآثار ذلك في المؤمنين ظاهرة؟", "h": ["بيان أن الكذب ما خالف الاعتقاد وإن طابق الواقع.", "التحذير من الاستمرار على المعصية، فإنه يوجب الطبع على القلب ويحرم صاحبه الهداية.", "التحذير من الاغترار بالمظاهر، كحسن الهندام وفصاحة اللسان.", "الكشف عن نفسية الخائن والظالم والمجرم، وهي الخوف والتخوّف من كل صوت أو كلمة خشية أن يكون ذلك بياناً لحالهم وكشفاً لجرائمهم."], "k": "«تعجبك أجسامهم… كأنهم خشب مسنّدة»… المظهر لا يزن شيئاً عنده؛ فبماذا أهتم أكثر: بمظهري أم بقلبي؟"}, {"lbl": "الآيات ٥ – ٨", "q": "وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡاْ رُءُوسَهُمۡ وَرَأَيۡتَهُمۡ يَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ ﴿٥﴾ سَوَآءٌ عَلَيۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٦﴾ هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّواْۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ ﴿٧﴾ يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ ﴿٨﴾", "w": [["وإذا قيل لهم تعالوا يستغفر لكم رسول الله", "تعالوا معتذرين."], ["لوّوا رؤوسهم", "رفضوا الاعتذار إلى رسول الله ﷺ."], ["ورأيتهم يصدّون وهم مستكبرون", "يعرضون عما دُعوا إليه وهم مستكبرون."], ["سواء عليهم أستغفرت لهم أم لم تستغفر لهم", "يا رسولنا."], ["لن يغفر الله لهم", "ايأس من مغفرة الله لهم."], ["إن الله لا يهدي القوم الفاسقين", "لأن من سنّة الله أنه لا يهدي القوم المتوغّلين في الفسق، وهم كذلك."], ["هم الذين يقولون", "لأهل المدينة."], ["لا تنفقوا على من عند رسول الله", "من المهاجرين."], ["حتى ينفضّوا", "يتفرّقوا عنه."], ["لئن رجعنا إلى المدينة", "من غزوة كانوا فيها، هي غزوة بني المصطلق."], ["ليُخرجنّ الأعزّ منها الأذل", "يعنون بالأعزّ أنفسهم، وبالأذل المؤمنين."], ["ولله العزة ولرسوله وللمؤمنين", "الغلبة والعلو والظهور."]], "m": "ما زال السياق في الحديث عن المنافقين: لما قال ابن أُبيّ ما قال من كلمات خبيثة في غزوة بني المصطلق، ومنها قوله في المهاجرين: سمّن كلبك يأكلك، وقوله: لا تنفقوا على من عند رسول الله حتى يتفرّقوا عنه، وقوله: لئن رجعنا إلى المدينة ليخرجنّ الأعزّ، يعني نفسه ورفاقه، الأذلَّ، يعني المهاجرين والأنصار، وأُخبر به رسول الله ﷺ، فجاء فحلف بالله ما قال شيئاً من ذلك، فنزلت هذه السورة تكذّبه، فجاءه من قال له: يا أبا الحُباب، إنه قد نزل فيك آي شداد، فاذهب إلى رسول الله ﷺ يستغفر لك، فلوى رأسه وقال: أمرتموني أن أؤمن فآمنت، وأمرتموني أن أعطي زكاة مالي فأعطيت، فما بقي إلا أن أسجد لمحمد! فنزلت: وإذا قيل لهم تعالوا معتذرين يستغفر لكم رسول الله لوّوا رؤوسهم رافضين، ورأيتهم يصدّون عنك وهم مستكبرون. سواء عليهم أستغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم، فأيأس رسوله من المغفرة لهم، وعلّل ذلك بأن الله لا يهدي القوم الفاسقين، وابن أُبيّ من أكثرهم فسقاً، إذ جمع بين الكذب والحلف الكاذب والنفاق والكبر والكفر الباطني. هم الذين يقولون: لا تنفقوا على المهاجرين حتى يتفرّقوا عن رسول الله، ولله خزائن السماوات والأرض، فجميع الأرزاق بيده، والمنافق نفسه رزقه على الله، ولكن المنافقين لا يفقهون. والقولة الثانية: لئن رجعنا إلى المدينة ليخرجنّ الأعزّ منها الأذل؛ قالها في غزوة بني المصطلق التي هزم الله فيها بني المصطلق، واصطفى رسول الله ﷺ جويرية بنت سيدهم الحارث فأعتقها وتزوّجها، فأعتق المؤمنون ما بأيديهم من السبي إكراماً لأصهار نبيهم، فقالت عائشة: ما أعلم امرأة كانت أعظم بركة على قومها من جويرية. وفي هذه الغزاة تلاحى أنصاري ومهاجر على الماء، فقال ابن أُبيّ قولته، وغاب عن ذهنه أن العزة لله ولرسوله وللمؤمنين، ولكن المنافقين لا يعلمون. ولما بلغ الغزاة المدينة وقف عبد الله بن عبد الله بن أُبيّ، وكان مؤمناً صادقاً من خيرة الأنصار، في عرض الطريق واستلّ سيفه، فلما جاء أبوه قال له: والله لا تمرّ حتى تقول: محمد الأعزّ وأنا الأذل، فلم يبرح حتى قالها.", "h": ["لا ينفع الاستغفار للكافر ولا الصلاة عليه بحال.", "ذمّ الإعراض والاستكبار عن التوبة والاستغفار؛ فمن قيل له: استغفر الله، فليستغفر ولا يتكبّر، بل عليه أن يقول: أستغفر الله، أو: اللهم اغفر لي.", "مصادر الرزق كلها بيد الله تعالى، فليُطلب الرزق بطاعة الله ورسوله لا بمعصيتهما.", "العزة الحقة لله ولرسوله وللمؤمنين، فلذا يجب على المؤمن ألا يذلّ ولا يهون لكافر."], "k": "«وإذا قيل لهم تعالوا يستغفر لكم… لوّوا رؤوسهم»… حين يُقال لي: استغفر، هل أستغفر فوراً أم أبرّر؟"}, {"lbl": "الآيات ٩ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٩﴾ وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِينَ ﴿١٠﴾ وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١١﴾", "w": [["لا تلهكم أموالكم ولا أولادكم", "لا تشغلكم."], ["عن ذكر الله", "كالصلاة والحج وقراءة القرآن، وذكر الله بالقلب واللسان."], ["ومن يفعل ذلك فأولئك هم الخاسرون", "ومن ألهته أمواله وأولاده عن أداء الفرائض فقد خسر ثواب الآخرة."], ["وأنفقوا مما رزقناكم", "النفقة الواجبة كالزكاة وفي الجهاد، والمستحبة."], ["لولا أخّرتني إلى أجل قريب", "هلّا أخّرتني؟ يطلب التأخير ولا يُقبل منه."], ["فأصّدّق وأكن من الصالحين", "حتى أزكّي وأحج وأكثر من النوافل والأعمال الصالحة."]], "m": "نادى تعالى المؤمنين لينصح لهم ألا تكون حالهم كحال المنافقين الذين تقدّم تأديبهم: يا من آمنتم بالله ورسوله لا تشغلكم أموالكم ولا أولادكم عن ذكر الله بأداء فرائضه واجتناب نواهيه والإكثار من طاعته والتقرّب إليه بأنواع القرب. ثم خوّفهم نصحاً لهم: ومن ألهته أمواله وأولاده عن عبادة الله فأولئك هم الخاسرون يوم القيامة بحرمانهم من الجنة ونعيمها ووجودهم في دار العذاب، لا أهل لهم فيها ولا ولد. وبالغ في إرشادهم فقال: وأنفقوا مما رزقناكم مبادرين الأجل، فإنكم لا تدرون متى تموتون، من قبل أن يأتي أحدكم الموت فيقول متمنّياً طالباً: يا رب لولا أخّرتني إلى وقت قريب من هذا فأتصدّق بمالي، وأكن من الصالحين فأحج وأتقرّب إليك بما تحب. ولن يؤخّر الله نفساً إذا جاء أجلها، وهذا حكمه الأزلي، والله خبير بما تعملون، يحضّ المؤمنين على إصلاح أعمالهم والتزوّد لآخرتهم بإعلامهم بأنه مطّلع على أعمالهم خبير بها.", "h": ["حرمة التشاغل بالمال والولد مع تضييع بعض الفرائض والواجبات.", "حرمة تأخير الحج مع القدرة على أدائه تسويفاً وتماطلاً، مع الإيمان بفرضيته.", "وجوب الزكاة، والترغيب في الصدقات الخاصة كصدقة الجهاد، والعامة على الفقراء.", "تقرير عقيدة البعث والجزاء."], "k": "«لولا أخّرتني إلى أجل قريب فأصّدّق»… أنا الآن في ذلك الأجل الذي سيتمناه غيري؛ فماذا أنتظر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (413, 64, 1, 10, 'سورة التغابن ١ – ١٠', 'التغابن: ذلك يوم التغابن', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 413) = $j$[{"lbl": "الآيات ١ – ٤", "q": "يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿١﴾ هُوَ ٱلَّذِي خَلَقَكُمۡ فَمِنكُمۡ كَافِرٞ وَمِنكُم مُّؤۡمِنٞۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٢﴾ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ ﴿٣﴾ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٤﴾", "w": [["يسبّح لله", "ينزّه الله ويقدّسه عن كل ما لا يليق بجلاله وكماله."], ["ما في السماوات وما في الأرض", "من سائر المخلوقات بلسان الحال والقال."], ["له الملك وله الحمد", "له دون غيره الملك الدائم الحق، وله الحمد العام."], ["وهو على كل شيء قدير", "ذو قدرة كاملة على فعل ما أراد ويريد."], ["فمنكم كافر ومنكم مؤمن", "فبعضكم مؤمن موقن بربه ولقائه، وبعضكم كافر جاحد، والواقع شاهد."], ["وصوّركم فأحسن صوركم", "صوّركم في الأرحام فأحسن صوركم."], ["وإليه المصير", "المرجع يوم القيامة."], ["والله عليم بذات الصدور", "بما في الصدور من الضمائر والسرائر."]], "m": "يخبر تعالى معلّماً عباده بربوبيته الموجبة لعبادته وطاعته وطاعة رسوله: بأنه يسبّحه جميع خلائقه في الملكوت الأعلى والأسفل، وأن له الملك وهو الملك الحق، وله الحمد وهو الثناء الجميل، وأنه على فعل كل شيء قدير لا يعجزه شيء، وأنه خالق الكل، فمن عباده المؤمن به ومنهم الكافر كما هو الواقع، وأنه بما يعمل عباده من خير أو شر بصير وسيجزي الكل بأعمالهم. وأنه خلق السماوات والأرض بالحق لا للّهو ولا للعبث، بل ليُذكر ويُشكر، وأنه صوّر العباد في الأرحام فأحسن صورهم وجمّلها، فهي أجمل المخلوقات الأرضية على الإطلاق، وأنه إليه لا إلى غيره المرجع يوم القيامة فيحاسب ويجزي. وأنه يعلم ما في السماوات والأرض، ويعلم ما يسرّ عباده من أعمال وأقوال ونيات وما يعلنون، وأنه عليم بذات الصدور من أسرار وخواطر ونيات. أخبر عباده بهذا ليؤمنوا به ويعبدوه دون غيره فيكملوا ويسعدوا بعبادته.", "h": ["تعليم الله تعالى عباده وتعريفهم بجلاله وكماله ليؤمنوا به ويعبدوه، ليكملوا ويسعدوا في الحياتين بالإيمان به وبطاعته وطاعة رسوله.", "تقرير عقيدة القضاء والقدر، إذ المؤمن مؤمن والكافر كافر مكتوب ذلك في كتاب المقادير، ثم يظهره تعالى في عالم الشهادة قائماً على سننه في خلقه.", "وجوب مراقبة الله تعالى والحياء منه، لأنه عليم بذات الصدور."], "k": "«وصوّركم فأحسن صوركم»… أحسن صورتي بلا طلب مني؛ فهل أشكره عليها أم أنشغل بعيوبها؟"}, {"lbl": "الآيتان ٥ – ٦", "q": "أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُ فَذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٥﴾ ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرٞ يَهۡدُونَنَا فَكَفَرُواْ وَتَوَلَّواْۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِيٌّ حَمِيدٞ ﴿٦﴾", "w": [["ألم يأتكم نبأ الذين كفروا من قبل", "ألم يأتكم يا كفار قريش خبر الذين كفروا من قبلكم؟"], ["فذاقوا وبال أمرهم", "عقوبة كفرهم في الدنيا."], ["ولهم عذاب أليم", "في الآخرة."], ["ذلك بأنه كانت تأتيهم رسلهم بالبيّنات", "العذاب في الدنيا والآخرة بسبب أنها كانت تأتيهم رسلهم بالحجج القواطع الدالة على صحة رسالاتهم."], ["فقالوا أبشر يهدوننا", "ردّوا عليهم ساخرين مكذّبين: أبشر يهدوننا؟"], ["فكفروا وتولّوا", "كفروا برسلهم وأعرضوا عنهم."], ["واستغنى الله", "عن إيمانهم."], ["والله غني حميد", "غني عن خلقه، محمود بأفعاله وآلائه على خلقه."]], "m": "بعد أن بيّن تعالى للناس مظاهر ربوبيته الموجبة لألوهيته، قرّر في هاتين الآيتين نبوة نبيه محمد ﷺ فقال لكفار مكة: ألم يأتكم خبر الذين كفروا من قبل كقوم عاد وثمود وأصحاب مدين، فذاقوا عقوبة كفرهم، فأُهلكوا في الدنيا بعذاب استئصالي، ولهم في الآخرة عذاب أليم؟ ثم بيّن سبب ذلك: أنه كانت تأتيهم رسلهم بالحجج والبراهين على أنهم رسل إليهم، وأنه لا إله إلا الله، فيقابلونهم بالسخرية والإعراض فيقولون: كيف يكون بشر مثلنا يهدوننا؟ وبذلك كفروا وتولّوا عن الإيمان، واستغنى الله عن إيمانهم فأهلكهم، والله غني عنهم وعن سائر خلقه، حميد بأفعاله الشاهدة بكماله وجلاله.", "h": ["توبيخ من يستحق التوبيخ، وتأنيب من يستحق التأنيب.", "التكذيب للرسل والكفر بتوحيد الله موجب للعقوبة في الدنيا والعذاب في الآخرة.", "تقرير نبوة رسول الله ﷺ وإثباتها، لأن شأنه شأن الرسل من قبله."], "k": "«والله غني حميد»… لا يحتاج إيماني، أنا الذي أحتاجه؛ فهل أعبده بقلب المحتاج؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "زَعَمَ ٱلَّذِينَ كَفَرُوٓاْ أَن لَّن يُبۡعَثُواْۚ قُلۡ بَلَىٰ وَرَبِّي لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿٧﴾ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِيٓ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٨﴾ يَوۡمَ يَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٩﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَاۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٠﴾", "w": [["زعم الذين كفروا أن لن يُبعثوا", "قالوا كاذبين: إنهم لن يُبعثوا أحياء من قبورهم."], ["قل بلى وربي لتُبعثُنّ ثم لتُنبّؤنّ بما عملتم", "قل لهم يا رسولنا: بلى لتبعثنّ ثم لتخبرنّ بما عملتم."], ["وذلك على الله يسير", "بعثكم وحسابكم ومجازاتكم بأعمالكم شيء يسير على الله."], ["والنور الذي أنزلنا", "وآمنوا بالقرآن الذي أنزلناه."], ["ليوم الجمع", "يوم القيامة، إذ هو يوم الجمع."], ["ذلك يوم التغابن", "يغبن المؤمنون الكافرين بأخذ منازل الكفار في الجنة، ويأخذ الكفار منازل المؤمنين في النار."], ["ذلك الفوز العظيم", "تكفيره تعالى عنهم سيئاتهم وإدخالهم جنات تجري من تحتها الأنهار هو الفوز العظيم."], ["وبئس المصير", "قبُح المصير الذي صاروا إليه، وهو كونهم أهلاً للجحيم."]], "m": "ما زال السياق في مطلب هداية قريش؛ بعد أن ذكّرهم بمصير الكافرين من قبلهم، دعاهم هنا إلى الإيمان بأعظم أصل من أصول الهداية البشرية، وهو الإيمان بالبعث والجزاء، وهم ينكرونه ويعاندون فيه، فقال: زعم الذين كفروا، والزعم ادعاء باطل وقول إلى الكذب أقرب منه إلى الصدق، أنهم إذا ماتوا لن يُبعثوا أحياء. قل لهم يا رسولنا: بلى وربي لتُبعثنّ ثم لتُنبّؤنّ بما عملتم، وذلك على الله سهل هيّن. وبعد هذه اللفتة دعاهم دعوة كريمة إلى طريق سعادتهم: فآمنوا بالله ورسوله والنور الذي أنزلنا وهو القرآن، واعملوا الصالحات وتباعدوا عن السيئات، والله بما تعملون خبير وسيجزيكم بأعمالكم يوم يجمعكم ليوم الجمع، ذلك يوم التغابن الحقيقي، حيث يرث أهل الجنة منازل أهل النار في الجنة، ويرث أهل النار منازل أهل الجنة في النار، إذ أوجد الله لكل إنسان منزلاً في الجنة وآخر في النار، فمن آمن وعمل صالحاً دخل الجنة وحاز منزله ومنزل إنسان آخر هو في النار، فحصل بذلك الغبن. ثم قال تعالى واعداً عامة الناس عربهم وعجمهم: ومن يؤمن بالله ويعمل صالحاً يكفّر عنه سيئاته ويدخله جنات تجري من تحتها الأنهار خالدين فيها أبداً، ذلك الفوز العظيم، لأنه نجاة من النار ودخول الجنة. والذين كفروا بالله ورسوله ولقائه وكذّبوا بالقرآن وما فيه من شرائع، والتكذيب مانع من العمل الصالح قطعاً، أولئك أصحاب النار خالدين فيها وبئس المصير؛ هذا وعيده المقابل لوعده السابق.", "h": ["تقرير البعث والجزاء.", "تقرير التوحيد والنبوة.", "بيان كون القرآن نوراً، فلا هداية في هذه الحياة إلا به، فمن طلبها في غيره ما اهتدى.", "الترغيب في الإيمان والعمل الصالح، وبيان أنهما مفتاح دار السلام.", "التحذير من الكفر والتكذيب بالقرآن وشرائعه وأحكامه، فإن ذلك يقود إلى النار."], "k": "«ذلك يوم التغابن»… الخاسر الحقيقي من باع منزله في الجنة بلذة عابرة؛ فبكم أبيع منزلي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 413;
insert into public.tdb_cards(topic, i, body) select 413, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿١﴾ هُوَ ٱلَّذِي خَلَقَكُمۡ فَمِنكُمۡ كَافِرٞ وَمِنكُم مُّؤۡمِنٞۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٢﴾ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ ﴿٣﴾ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٤﴾", "w": [["يسبّح لله", "ينزّه الله ويقدّسه عن كل ما لا يليق بجلاله وكماله."], ["ما في السماوات وما في الأرض", "من سائر المخلوقات بلسان الحال والقال."], ["له الملك وله الحمد", "له دون غيره الملك الدائم الحق، وله الحمد العام."], ["وهو على كل شيء قدير", "ذو قدرة كاملة على فعل ما أراد ويريد."], ["فمنكم كافر ومنكم مؤمن", "فبعضكم مؤمن موقن بربه ولقائه، وبعضكم كافر جاحد، والواقع شاهد."], ["وصوّركم فأحسن صوركم", "صوّركم في الأرحام فأحسن صوركم."], ["وإليه المصير", "المرجع يوم القيامة."], ["والله عليم بذات الصدور", "بما في الصدور من الضمائر والسرائر."]], "m": "يخبر تعالى معلّماً عباده بربوبيته الموجبة لعبادته وطاعته وطاعة رسوله: بأنه يسبّحه جميع خلائقه في الملكوت الأعلى والأسفل، وأن له الملك وهو الملك الحق، وله الحمد وهو الثناء الجميل، وأنه على فعل كل شيء قدير لا يعجزه شيء، وأنه خالق الكل، فمن عباده المؤمن به ومنهم الكافر كما هو الواقع، وأنه بما يعمل عباده من خير أو شر بصير وسيجزي الكل بأعمالهم. وأنه خلق السماوات والأرض بالحق لا للّهو ولا للعبث، بل ليُذكر ويُشكر، وأنه صوّر العباد في الأرحام فأحسن صورهم وجمّلها، فهي أجمل المخلوقات الأرضية على الإطلاق، وأنه إليه لا إلى غيره المرجع يوم القيامة فيحاسب ويجزي. وأنه يعلم ما في السماوات والأرض، ويعلم ما يسرّ عباده من أعمال وأقوال ونيات وما يعلنون، وأنه عليم بذات الصدور من أسرار وخواطر ونيات. أخبر عباده بهذا ليؤمنوا به ويعبدوه دون غيره فيكملوا ويسعدوا بعبادته.", "h": ["تعليم الله تعالى عباده وتعريفهم بجلاله وكماله ليؤمنوا به ويعبدوه، ليكملوا ويسعدوا في الحياتين بالإيمان به وبطاعته وطاعة رسوله.", "تقرير عقيدة القضاء والقدر، إذ المؤمن مؤمن والكافر كافر مكتوب ذلك في كتاب المقادير، ثم يظهره تعالى في عالم الشهادة قائماً على سننه في خلقه.", "وجوب مراقبة الله تعالى والحياء منه، لأنه عليم بذات الصدور."], "k": "«وصوّركم فأحسن صوركم»… أحسن صورتي بلا طلب مني؛ فهل أشكره عليها أم أنشغل بعيوبها؟"}, {"lbl": "الآيتان ٥ – ٦", "q": "أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُ فَذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٥﴾ ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرٞ يَهۡدُونَنَا فَكَفَرُواْ وَتَوَلَّواْۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِيٌّ حَمِيدٞ ﴿٦﴾", "w": [["ألم يأتكم نبأ الذين كفروا من قبل", "ألم يأتكم يا كفار قريش خبر الذين كفروا من قبلكم؟"], ["فذاقوا وبال أمرهم", "عقوبة كفرهم في الدنيا."], ["ولهم عذاب أليم", "في الآخرة."], ["ذلك بأنه كانت تأتيهم رسلهم بالبيّنات", "العذاب في الدنيا والآخرة بسبب أنها كانت تأتيهم رسلهم بالحجج القواطع الدالة على صحة رسالاتهم."], ["فقالوا أبشر يهدوننا", "ردّوا عليهم ساخرين مكذّبين: أبشر يهدوننا؟"], ["فكفروا وتولّوا", "كفروا برسلهم وأعرضوا عنهم."], ["واستغنى الله", "عن إيمانهم."], ["والله غني حميد", "غني عن خلقه، محمود بأفعاله وآلائه على خلقه."]], "m": "بعد أن بيّن تعالى للناس مظاهر ربوبيته الموجبة لألوهيته، قرّر في هاتين الآيتين نبوة نبيه محمد ﷺ فقال لكفار مكة: ألم يأتكم خبر الذين كفروا من قبل كقوم عاد وثمود وأصحاب مدين، فذاقوا عقوبة كفرهم، فأُهلكوا في الدنيا بعذاب استئصالي، ولهم في الآخرة عذاب أليم؟ ثم بيّن سبب ذلك: أنه كانت تأتيهم رسلهم بالحجج والبراهين على أنهم رسل إليهم، وأنه لا إله إلا الله، فيقابلونهم بالسخرية والإعراض فيقولون: كيف يكون بشر مثلنا يهدوننا؟ وبذلك كفروا وتولّوا عن الإيمان، واستغنى الله عن إيمانهم فأهلكهم، والله غني عنهم وعن سائر خلقه، حميد بأفعاله الشاهدة بكماله وجلاله.", "h": ["توبيخ من يستحق التوبيخ، وتأنيب من يستحق التأنيب.", "التكذيب للرسل والكفر بتوحيد الله موجب للعقوبة في الدنيا والعذاب في الآخرة.", "تقرير نبوة رسول الله ﷺ وإثباتها، لأن شأنه شأن الرسل من قبله."], "k": "«والله غني حميد»… لا يحتاج إيماني، أنا الذي أحتاجه؛ فهل أعبده بقلب المحتاج؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "زَعَمَ ٱلَّذِينَ كَفَرُوٓاْ أَن لَّن يُبۡعَثُواْۚ قُلۡ بَلَىٰ وَرَبِّي لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿٧﴾ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِيٓ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٨﴾ يَوۡمَ يَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٩﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَاۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٠﴾", "w": [["زعم الذين كفروا أن لن يُبعثوا", "قالوا كاذبين: إنهم لن يُبعثوا أحياء من قبورهم."], ["قل بلى وربي لتُبعثُنّ ثم لتُنبّؤنّ بما عملتم", "قل لهم يا رسولنا: بلى لتبعثنّ ثم لتخبرنّ بما عملتم."], ["وذلك على الله يسير", "بعثكم وحسابكم ومجازاتكم بأعمالكم شيء يسير على الله."], ["والنور الذي أنزلنا", "وآمنوا بالقرآن الذي أنزلناه."], ["ليوم الجمع", "يوم القيامة، إذ هو يوم الجمع."], ["ذلك يوم التغابن", "يغبن المؤمنون الكافرين بأخذ منازل الكفار في الجنة، ويأخذ الكفار منازل المؤمنين في النار."], ["ذلك الفوز العظيم", "تكفيره تعالى عنهم سيئاتهم وإدخالهم جنات تجري من تحتها الأنهار هو الفوز العظيم."], ["وبئس المصير", "قبُح المصير الذي صاروا إليه، وهو كونهم أهلاً للجحيم."]], "m": "ما زال السياق في مطلب هداية قريش؛ بعد أن ذكّرهم بمصير الكافرين من قبلهم، دعاهم هنا إلى الإيمان بأعظم أصل من أصول الهداية البشرية، وهو الإيمان بالبعث والجزاء، وهم ينكرونه ويعاندون فيه، فقال: زعم الذين كفروا، والزعم ادعاء باطل وقول إلى الكذب أقرب منه إلى الصدق، أنهم إذا ماتوا لن يُبعثوا أحياء. قل لهم يا رسولنا: بلى وربي لتُبعثنّ ثم لتُنبّؤنّ بما عملتم، وذلك على الله سهل هيّن. وبعد هذه اللفتة دعاهم دعوة كريمة إلى طريق سعادتهم: فآمنوا بالله ورسوله والنور الذي أنزلنا وهو القرآن، واعملوا الصالحات وتباعدوا عن السيئات، والله بما تعملون خبير وسيجزيكم بأعمالكم يوم يجمعكم ليوم الجمع، ذلك يوم التغابن الحقيقي، حيث يرث أهل الجنة منازل أهل النار في الجنة، ويرث أهل النار منازل أهل الجنة في النار، إذ أوجد الله لكل إنسان منزلاً في الجنة وآخر في النار، فمن آمن وعمل صالحاً دخل الجنة وحاز منزله ومنزل إنسان آخر هو في النار، فحصل بذلك الغبن. ثم قال تعالى واعداً عامة الناس عربهم وعجمهم: ومن يؤمن بالله ويعمل صالحاً يكفّر عنه سيئاته ويدخله جنات تجري من تحتها الأنهار خالدين فيها أبداً، ذلك الفوز العظيم، لأنه نجاة من النار ودخول الجنة. والذين كفروا بالله ورسوله ولقائه وكذّبوا بالقرآن وما فيه من شرائع، والتكذيب مانع من العمل الصالح قطعاً، أولئك أصحاب النار خالدين فيها وبئس المصير؛ هذا وعيده المقابل لوعده السابق.", "h": ["تقرير البعث والجزاء.", "تقرير التوحيد والنبوة.", "بيان كون القرآن نوراً، فلا هداية في هذه الحياة إلا به، فمن طلبها في غيره ما اهتدى.", "الترغيب في الإيمان والعمل الصالح، وبيان أنهما مفتاح دار السلام.", "التحذير من الكفر والتكذيب بالقرآن وشرائعه وأحكامه، فإن ذلك يقود إلى النار."], "k": "«ذلك يوم التغابن»… الخاسر الحقيقي من باع منزله في الجنة بلذة عابرة؛ فبكم أبيع منزلي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (414, 64, 11, 18, 'سورة التغابن ١١ – ١٨', 'التغابن: فاتقوا الله ما استطعتم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 414) = $j$[{"lbl": "الآيات ١١ – ١٣", "q": "مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١١﴾ وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۚ فَإِن تَوَلَّيۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿١٢﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٣﴾", "w": [["ما أصاب من مصيبة إلا بإذن الله", "ما أصابت أحداً من الناس مصيبة إلا بقضاء الله تعالى."], ["ومن يؤمن بالله يهد قلبه", "ومن يصدّق بالله فيعلم أنه لا تصيبه مصيبة إلا بإذنه تعالى يهد قلبه للتسليم والرضا بقضائه، فيسترجع ويصبر."], ["فإن تولّيتم", "عن طاعة الله ورسوله فلا ضرر على رسولنا في تولّيكم، إذ عليه إبلاغكم لا هدايتكم."]], "m": "في هذه الآية ردّ على الكافرين الذين يقولون: لو كان المسلمون على حق لصانهم الله من المصائب في الدنيا، فأخبر تعالى أنه ما من أحد تصيبه مصيبة في نفس أو ولد أو مال إلا وهي بقضاء الله وتقديره ذلك عليه، ومن يؤمن بالله رباً وإلهاً عليماً حكيماً، وأن ما أصابه لم يكن ليخطئه وما أخطأه لم يكن ليصيبه، يهد قلبه فيصبر ويسترجع فيؤجر وتخف عنده المصيبة، بخلاف الكافر بالله وقضائه وقدره. والله بكل شيء عليم، فلا يحدث حدث في الكون إلا بعلمه وإذنه، وهذه حال تقتضي الرضا بالقضاء والتسليم لله فيما يقضي به على عبده، وفي ذلك خير كثير لا يعرفه إلا أصحاب الرضا. وأطيعوا الله وأطيعوا الرسول، لأن كمال الإنسان وسعادته مرتبطان بهذه الطاعة التي هي تطبيق نظام دقيق ينتج صفاء روح وزكاة نفس يتأهّل بها العبد للجنة، فإن أعرضتم عن هذه الدعوة فلا ضرر على رسولنا، إذ عليه البلاغ المبين وقد بلّغ، وأما هدايتكم فلم يُكلّف بها إذ لا يقدر عليها. الله الذي أمركم بطاعته لا إله إلا هو، لأنه الخالق الرازق المدبّر لحياتكم، وعلى الله فليتوكّل المؤمنون، فإنه يكفي المتوكّل عليه كل ما يهمّه من أمر دنياه وآخرته.", "h": ["تقرير عقيدة القضاء والقدر.", "الصبر عند نزول المصيبة، والرضا والتسليم لله تعالى في قضائه وحكمه، ومن تكن هذه حاله يهد الله قلبه ويرزقه الصبر ويعظم له الأجر ويلطف به في مصيبته، وإن هو استرجع قائلاً: إنا لله وإنا إليه راجعون، أخلفه الله عما فقده وآجره.", "وجوب طاعة الله وطاعة رسوله في الأمر والنهي.", "تقرير التوحيد.", "وجوب التوكّل على الله تعالى، وهو فعل المأمور وترك المنهيّ وتفويض الأمر لله بعد ذلك، ولن يكون إلا خيراً بإذن الله تعالى."], "k": "«ومن يؤمن بالله يهد قلبه»… في المصيبة القادمة، هل سيسبق لساني الاسترجاع أم الاعتراض؟"}, {"lbl": "الآيات ١٤ – ١٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ مِنۡ أَزۡوَٰجِكُمۡ وَأَوۡلَٰدِكُمۡ عَدُوّٗا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُواْ وَتَصۡفَحُواْ وَتَغۡفِرُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٤﴾ إِنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ﴿١٥﴾ فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٦﴾ إِن تُقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ ﴿١٧﴾ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١٨﴾", "w": [["إن من أزواجكم وأولادكم عدواً لكم", "من بعض أزواجكم وبعض أولادكم عدواً يشغلكم عن طاعة الله، أو ينازعكم في أمر الدين أو الدنيا."], ["فاحذروهم", "أن تطيعوهم في التخلّف عن فعل الخير، كترك الهجرة أو الجهاد أو صلاة الجماعة أو التصدّق على ذوي الحاجة."], ["وإن تعفوا", "عمّن ثبّطكم عن الخير من زوجة وولد."], ["وتصفحوا وتغفروا", "وتعرضوا عنهم وتغفروا لهم ما عملوه معكم من تأخيركم عن الخير."], ["فإن الله غفور رحيم", "يغفر لمن يغفر، ويرحم من يرحم."], ["إنما أموالكم وأولادكم فتنة", "بلاء واختبار لكم، فاحذروا أن يصرفوكم عن طاعة الله أو يوقعوكم في معصيته."], ["والله عنده أجر عظيم", "فآثروا ما عنده تعالى على ما عندكم من مال وولد."], ["فاتقوا الله ما استطعتم", "افعلوا ما تقدرون عليه من أوامره، واجتنبوا نواهيه كلها."], ["ومن يوق شحّ نفسه", "ومن يقه الله شحّ نفسه فيعافيه من البخل والحرص."], ["يضاعفه لكم", "الدرهم بسبعمائة."], ["والله شكور حليم", "يجازي على الطاعة، ولا يعاجل بالعقوبة."]], "m": "نزلت هذه الآيات في أناس كان لهم أزواج وأولاد عاقوهم عن الهجرة والجهاد فترة، فلما تغلّبوا عليهم وهاجروا ووجدوا الذين سبقوهم قد تفقّهوا في الدين، تأسّفوا وهمّوا أن يعاقبوا أزواجهم وأولادهم بنوع من العقاب، فأنزل الله: يا أيها المؤمنون إن من بعض أزواجكم وأولادكم، لا كلهم، إذ منهم من يكون عوناً على طاعة الله، عدواً لكم يصرفكم عن طاعة الله والتزوّد للآخرة، فكونوا منهم على حذر أن تطيعوهم في التخلّف عن فعل الخير، وإن تعفوا وتصفحوا وتغفروا لمن شغلوكم عن طاعة الله، فلم تعاقبوهم ولم تعاتبوهم، بل التمستم لهم العذر، يكافئكم الله بمثله فيعفو عنكم ويغفر لكم. إنما أموالكم وأولادكم كلها فتنة واختبار من الله لكم: هل تحسنون التصرّف فيهم فلا تعصون الله لأجلهم، أو تسيئون فيحملكم حبهم على التفريط في طاعة الله؟ والله عنده أجر عظيم، فآثروا الباقي على الفاني. فاتقوا الله ما استطعتم: هذا من إحسانه تعالى إلى عباده، إذ علم أن بعضهم سوف يعانون مشقة في التوفيق بين المصلحتين، فأمرهم أن يتّقوه في حدود ما يطيقون، وخير الأمور الوسط، فلا يفرّط في ولده وماله، ولا يفرّط في علّة وجوده وسبب نجاته، وهي عبادة الله. واسمعوا وأطيعوا وأنفقوا في طاعة الله خيراً لأنفسكم. ومن يوق شحّ نفسه فأولئك هم المفلحون؛ أعلمهم أن عدم الإنفاق ناتج عن شحّ النفس، وشحّ النفس لا يقي منه إلا الله، فالجؤوا إليه، وتوسّلوا إليه بالإنفاق قليلاً قليلاً حتى يحصل الشفاء من هذا المرض. إن تقرضوا الله قرضاً حسناً يضاعفه لكم ويغفر لكم؛ سمّاها قرضاً والقرض مردود، واشتراط الحسن أن يكون المال حلالاً والنفس طيبة به. والله شكور، يعطي على القليل الكثير، حليم لا يعاجل بالعقوبة، عالم الغيب والشهادة، لا يغيب عنه شيء من أموركم، فمعاملته مضمونة لا يُخاف ضياعها، العزيز الحكيم.", "h": ["بيان أن من بعض الزوجات والأولاد عدواً، فعلى المؤمن أن يحذر ذلك ليسلم من شرّهم.", "الترغيب في العفو والصفح والمغفرة على من أساء أو ظلم.", "التحذير من فتنة المال والولد، ووجوب التيقّظ حتى لا يهلك المرء بولده وماله.", "وجوب تقوى الله بفعل الواجبات وترك المنهيات في حدود الطاقة البشرية.", "الترغيب في الإنفاق في سبيل الله تعالى، والتحذير من الشح فإنه داء خطير."], "k": "«فاتقوا الله ما استطعتم»… لا يطلب مني المستحيل، بل ما أستطيع؛ فهل أبذل فعلاً كل ما أستطيع؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 414;
insert into public.tdb_cards(topic, i, body) select 414, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١ – ١٣", "q": "مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١١﴾ وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۚ فَإِن تَوَلَّيۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿١٢﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١٣﴾", "w": [["ما أصاب من مصيبة إلا بإذن الله", "ما أصابت أحداً من الناس مصيبة إلا بقضاء الله تعالى."], ["ومن يؤمن بالله يهد قلبه", "ومن يصدّق بالله فيعلم أنه لا تصيبه مصيبة إلا بإذنه تعالى يهد قلبه للتسليم والرضا بقضائه، فيسترجع ويصبر."], ["فإن تولّيتم", "عن طاعة الله ورسوله فلا ضرر على رسولنا في تولّيكم، إذ عليه إبلاغكم لا هدايتكم."]], "m": "في هذه الآية ردّ على الكافرين الذين يقولون: لو كان المسلمون على حق لصانهم الله من المصائب في الدنيا، فأخبر تعالى أنه ما من أحد تصيبه مصيبة في نفس أو ولد أو مال إلا وهي بقضاء الله وتقديره ذلك عليه، ومن يؤمن بالله رباً وإلهاً عليماً حكيماً، وأن ما أصابه لم يكن ليخطئه وما أخطأه لم يكن ليصيبه، يهد قلبه فيصبر ويسترجع فيؤجر وتخف عنده المصيبة، بخلاف الكافر بالله وقضائه وقدره. والله بكل شيء عليم، فلا يحدث حدث في الكون إلا بعلمه وإذنه، وهذه حال تقتضي الرضا بالقضاء والتسليم لله فيما يقضي به على عبده، وفي ذلك خير كثير لا يعرفه إلا أصحاب الرضا. وأطيعوا الله وأطيعوا الرسول، لأن كمال الإنسان وسعادته مرتبطان بهذه الطاعة التي هي تطبيق نظام دقيق ينتج صفاء روح وزكاة نفس يتأهّل بها العبد للجنة، فإن أعرضتم عن هذه الدعوة فلا ضرر على رسولنا، إذ عليه البلاغ المبين وقد بلّغ، وأما هدايتكم فلم يُكلّف بها إذ لا يقدر عليها. الله الذي أمركم بطاعته لا إله إلا هو، لأنه الخالق الرازق المدبّر لحياتكم، وعلى الله فليتوكّل المؤمنون، فإنه يكفي المتوكّل عليه كل ما يهمّه من أمر دنياه وآخرته.", "h": ["تقرير عقيدة القضاء والقدر.", "الصبر عند نزول المصيبة، والرضا والتسليم لله تعالى في قضائه وحكمه، ومن تكن هذه حاله يهد الله قلبه ويرزقه الصبر ويعظم له الأجر ويلطف به في مصيبته، وإن هو استرجع قائلاً: إنا لله وإنا إليه راجعون، أخلفه الله عما فقده وآجره.", "وجوب طاعة الله وطاعة رسوله في الأمر والنهي.", "تقرير التوحيد.", "وجوب التوكّل على الله تعالى، وهو فعل المأمور وترك المنهيّ وتفويض الأمر لله بعد ذلك، ولن يكون إلا خيراً بإذن الله تعالى."], "k": "«ومن يؤمن بالله يهد قلبه»… في المصيبة القادمة، هل سيسبق لساني الاسترجاع أم الاعتراض؟"}, {"lbl": "الآيات ١٤ – ١٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ مِنۡ أَزۡوَٰجِكُمۡ وَأَوۡلَٰدِكُمۡ عَدُوّٗا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُواْ وَتَصۡفَحُواْ وَتَغۡفِرُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٤﴾ إِنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ﴿١٥﴾ فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٦﴾ إِن تُقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ ﴿١٧﴾ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١٨﴾", "w": [["إن من أزواجكم وأولادكم عدواً لكم", "من بعض أزواجكم وبعض أولادكم عدواً يشغلكم عن طاعة الله، أو ينازعكم في أمر الدين أو الدنيا."], ["فاحذروهم", "أن تطيعوهم في التخلّف عن فعل الخير، كترك الهجرة أو الجهاد أو صلاة الجماعة أو التصدّق على ذوي الحاجة."], ["وإن تعفوا", "عمّن ثبّطكم عن الخير من زوجة وولد."], ["وتصفحوا وتغفروا", "وتعرضوا عنهم وتغفروا لهم ما عملوه معكم من تأخيركم عن الخير."], ["فإن الله غفور رحيم", "يغفر لمن يغفر، ويرحم من يرحم."], ["إنما أموالكم وأولادكم فتنة", "بلاء واختبار لكم، فاحذروا أن يصرفوكم عن طاعة الله أو يوقعوكم في معصيته."], ["والله عنده أجر عظيم", "فآثروا ما عنده تعالى على ما عندكم من مال وولد."], ["فاتقوا الله ما استطعتم", "افعلوا ما تقدرون عليه من أوامره، واجتنبوا نواهيه كلها."], ["ومن يوق شحّ نفسه", "ومن يقه الله شحّ نفسه فيعافيه من البخل والحرص."], ["يضاعفه لكم", "الدرهم بسبعمائة."], ["والله شكور حليم", "يجازي على الطاعة، ولا يعاجل بالعقوبة."]], "m": "نزلت هذه الآيات في أناس كان لهم أزواج وأولاد عاقوهم عن الهجرة والجهاد فترة، فلما تغلّبوا عليهم وهاجروا ووجدوا الذين سبقوهم قد تفقّهوا في الدين، تأسّفوا وهمّوا أن يعاقبوا أزواجهم وأولادهم بنوع من العقاب، فأنزل الله: يا أيها المؤمنون إن من بعض أزواجكم وأولادكم، لا كلهم، إذ منهم من يكون عوناً على طاعة الله، عدواً لكم يصرفكم عن طاعة الله والتزوّد للآخرة، فكونوا منهم على حذر أن تطيعوهم في التخلّف عن فعل الخير، وإن تعفوا وتصفحوا وتغفروا لمن شغلوكم عن طاعة الله، فلم تعاقبوهم ولم تعاتبوهم، بل التمستم لهم العذر، يكافئكم الله بمثله فيعفو عنكم ويغفر لكم. إنما أموالكم وأولادكم كلها فتنة واختبار من الله لكم: هل تحسنون التصرّف فيهم فلا تعصون الله لأجلهم، أو تسيئون فيحملكم حبهم على التفريط في طاعة الله؟ والله عنده أجر عظيم، فآثروا الباقي على الفاني. فاتقوا الله ما استطعتم: هذا من إحسانه تعالى إلى عباده، إذ علم أن بعضهم سوف يعانون مشقة في التوفيق بين المصلحتين، فأمرهم أن يتّقوه في حدود ما يطيقون، وخير الأمور الوسط، فلا يفرّط في ولده وماله، ولا يفرّط في علّة وجوده وسبب نجاته، وهي عبادة الله. واسمعوا وأطيعوا وأنفقوا في طاعة الله خيراً لأنفسكم. ومن يوق شحّ نفسه فأولئك هم المفلحون؛ أعلمهم أن عدم الإنفاق ناتج عن شحّ النفس، وشحّ النفس لا يقي منه إلا الله، فالجؤوا إليه، وتوسّلوا إليه بالإنفاق قليلاً قليلاً حتى يحصل الشفاء من هذا المرض. إن تقرضوا الله قرضاً حسناً يضاعفه لكم ويغفر لكم؛ سمّاها قرضاً والقرض مردود، واشتراط الحسن أن يكون المال حلالاً والنفس طيبة به. والله شكور، يعطي على القليل الكثير، حليم لا يعاجل بالعقوبة، عالم الغيب والشهادة، لا يغيب عنه شيء من أموركم، فمعاملته مضمونة لا يُخاف ضياعها، العزيز الحكيم.", "h": ["بيان أن من بعض الزوجات والأولاد عدواً، فعلى المؤمن أن يحذر ذلك ليسلم من شرّهم.", "الترغيب في العفو والصفح والمغفرة على من أساء أو ظلم.", "التحذير من فتنة المال والولد، ووجوب التيقّظ حتى لا يهلك المرء بولده وماله.", "وجوب تقوى الله بفعل الواجبات وترك المنهيات في حدود الطاقة البشرية.", "الترغيب في الإنفاق في سبيل الله تعالى، والتحذير من الشح فإنه داء خطير."], "k": "«فاتقوا الله ما استطعتم»… لا يطلب مني المستحيل، بل ما أستطيع؛ فهل أبذل فعلاً كل ما أستطيع؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (415, 65, 1, 12, 'سورة الطلاق ١ – ١٢', 'الطلاق: ومن يتّق الله يجعل له مخرجاً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 415) = $j$[{"lbl": "الآية ١", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ ٱلۡعِدَّةَۖ وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرٗا ﴿١﴾", "w": [["يا أيها النبي", "أراد الله بالنداء النبي ﷺ وأمته، بدليل ما بعده."], ["إذا طلّقتم النساء", "إذا أردتم طلاقهن."], ["فطلّقوهن لعدّتهن", "لقُبُل عدتهن، أي في طهر لم يجامعها فيه."], ["وأحصوا العدّة", "احفظوا مدّتها حتى يمكنكم المراجعة فيها."], ["واتقوا الله ربكم", "أطيعوه في أمره ونهيه."], ["لا تخرجوهن من بيوتهن", "لا تخرجوا المطلقة من بيت زوجها الذي طلّقها حتى تنقضي عدتها."], ["إلا أن يأتين بفاحشة مبيّنة", "إلا أن يأتين بالبذاء في القول وسوء الخلق، أو يرتكبن فاحشة من زنا بيّنة ظاهرة لا شك فيها."], ["وتلك حدود الله", "المذكورات من الطلاق في أول الطهر، وإحصاء العدة، وعدم إخراج المطلقة من بيتها حتى تنقضي عدتها."], ["لا تدري لعل الله يُحدث بعد ذلك أمراً", "يجعل في قلب الزوج الرغبة في مراجعتها فيراجعها إذا لم تكن الثالثة من الطلقات."]], "m": "يخاطب الله تبارك وتعالى رجال أمة الإسلام في شخص نبيها محمد ﷺ فيقول: إذا أردتم طلاق نسائكم لأمر اقتضى ذلك فطلّقوهن لأول عدّتهن، وذلك في طهر لم تُجامع فيه، ليُعدّ ذلك الطهر أول عدتها. وأحصوا العدة، فاعرفوا بدايتها ونهايتها لما يترتب على ذلك من أحكام: من صحة المراجعة وعدمها، ومن النفقة والإسكان. واتقوا الله ربكم فامتثلوا أوامره وقفوا عند حدوده، لا تخرجوا المطلقات من بيوتهن اللاتي طُلّقن فيهن، ويجب ألّا يخرجن، إلا أن يأتين بفاحشة مبيّنة كزنا ظاهر، أو تكون سيئة بذيئة اللسان فتؤذي أهل البيت أذى لا يتحمّلونه، فعندئذ يُباح إخراجها. وتلك حدود الله، ومن يتعدّها فلم يقف عندها فقد ظلم نفسه وتعرّض لعقوبة الله عاجلاً أو آجلاً. لا تدري لعل الله يُحدث بعد ذلك أمراً، بأن يجعل في قلب الرجل رغبة في مراجعة مطلّقته فيراجعها، وفي ذلك خير كثير.", "h": ["بيان السنة في الطلاق، وهي أن يطلّقها في طهر لم يمسّها فيه بجماع.", "أن يكون الطلاق واحدة، لا اثنتين ولا ثلاثاً.", "وجوب إحصاء العدة ليعرف الزوج متى تنقضي عدة مطلّقته، لما يترتب على ذلك من أحكام الرجعة والنفقة والإسكان.", "حرمة إخراج المطلقة من بيتها الذي طُلّقت فيه إلى أن تنقضي عدتها، إلا أن ترتكب فاحشة ظاهرة كزنا، أو بذاءة وسوء خلق وقبيح معاملة، فعندئذ يجوز إخراجها."], "k": "«لا تدري لعل الله يُحدث بعد ذلك أمراً»… حتى في ساعة الغضب يترك الله باباً مفتوحاً؛ فهل أترك أنا باباً للصلح؟"}, {"lbl": "الآيتان ٢ – ٣", "q": "فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا ﴿٢﴾ وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا ﴿٣﴾", "w": [["فإذا بلغن أجلهن", "قاربن انقضاء عدّتهن."], ["فأمسكوهن بمعروف", "راجعوهن بمعروف من غير ضرر."], ["أو فارقوهن بمعروف", "اتركوهن حتى تنقضي عدتهن، ولا تضارّوهن بالمراجعة."], ["وأشهدوا ذوَي عدل منكم", "أشهدوا على الطلاق وعلى الرجعة رجلين عدلين منكم."], ["وأقيموا الشهادة لله", "لا للمشهود عليه أو له، بل لله تعالى وحده."], ["ذلكم يوعظ به من كان يؤمن بالله واليوم الآخر", "ذلكم المذكور من أول السورة من أحكام يُؤمر به وينفّذه المؤمن بالله واليوم الآخر."], ["ومن يتّق الله", "في أمره ونهيه فلا يعصه فيهما."], ["يجعل له مخرجاً", "من كل ضيق."], ["ويرزقه من حيث لا يحتسب", "من حيث لا يرجو ولا يؤمّل."], ["فهو حسبه", "كافيه ما يهمّه من أمر دينه ودنياه."], ["قد جعل الله لكل شيء قدراً", "من الطلاق والعدة وغير ذلك، حدّاً وأجلاً ينتهي إليه."]], "m": "ما زال السياق في بيان العِدد وأحكام الطلاق والرجعة: فإذا قاربت المطلقات انقضاء العدة فأمسكوهن بمعروف، أي راجعوهن على أساس حسن العشرة، لا للإضرار بهن، كأن يراجعها ثم يطلّقها ليطيل عليها العدة، فهذا لا يجوز لحرمة الإضرار بالناس، وفي الحديث: «لا ضرر ولا ضرار»، أو فارقوهن بمعروف بأن يعطيها ما بقي لها من مهرها ويمتّعها بحسب حاله غنى وفقراً. وأشهدوا ذوي عدل منكم على النكاح والطلاق والرجعة؛ أما الإشهاد على النكاح فركن لا يصح النكاح بدونه، وأما في الطلاق والرجعة فهو مندوب، وقد يصح الطلاق والرجعة بدونه، ويُشترط في الشهود أن يكونوا عدولاً مسلمين. وأقيموا الشهادة لله، أدّوها على وجهها ولا تراعوا فيها إلا وجه الله. ذلكم المأمور به من أول السورة يُوعظ به وينفّذه المؤمن بالله واليوم الآخر، إذ هو الذي يخاف عقوبة الله فلا يقدم على معصيته. ومن يتّق الله يجعل له مخرجاً ويرزقه من حيث لا يحتسب: نزلت في عوف بن مالك الأشجعي، أتى رسول الله ﷺ فقال: إن ابني أسره العدو وجزعت أمه فبمَ تأمرني؟ قال: «آمرك وإياها أن تكثرا من قول: لا حول ولا قوة إلا بالله»، فجعلا يكثران منها، فغفل العدو عن ابنهما فاستاق غنمهم وجاء بها إلى أبويه، فنزلت هذه الآية، وهي عامة في كل من يتّقي الله، يجعل له من كل ضيق مخرجاً ومن كل كرب فرجاً، ويرزقه من حيث لا يخطر له على بال. ومن يتوكّل على الله فلا يفرّط في أمر الله ولا يضيّع حقوقه فإن الله يكفيه ما يهمّه. إن الله بالغ أمره، منفّذه في عباده لا يعجزونه، قد جعل لكل شيء قدراً: مقداراً وزماناً ومكاناً، فلا يتقدّم ولا يتأخّر، فمن رضي فله الرضا ومن سخط فله السخط.", "h": ["لا تصح الرجعة إلا في العدة، فإن انقضت العدة فلا رجعة، وللمطلقة أن تتزوّج من شاءت، هو أو غيره، من ساعة انقضاء عدتها.", "لا تحل المراجعة للإضرار، ولكن للفضل والإحسان وطيب العشرة.", "مشروعية الإشهاد على الطلاق والرجعة معاً.", "يُشترط في الشهود العدالة.", "وعد الله الصادق بالفرج القريب لكل من يتّقيه سبحانه وتعالى، والرزق من حيث لا يرجو.", "تقرير عقيدة القضاء والقدر.", "كفاية الله لمن توكّل عليه."], "k": "«ومن يتّق الله يجعل له مخرجاً»… في ضيقي الحالي، هل أبحث عن المخرج في التقوى أم في الحيلة؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "وَٱلَّـٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرٖ وَٱلَّـٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرٗا ﴿٤﴾ ذَٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيۡكُمۡۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا ﴿٥﴾", "w": [["واللائي يئسن من المحيض", "والنسوة اللائي يئسن من الحيض."], ["إن ارتبتم", "شككتم في عدّتهن."], ["واللائي لم يحضن", "لصغر سن."], ["وأولات الأحمال", "النساء الحوامل."], ["أجلهن أن يضعن حملهن", "انقضاء عدتهن أن يضعن حملهن."], ["ذلك أمر الله", "ذلك المذكور في العدة وتفاصيلها."], ["أنزله إليكم", "لتأتمروا به وتعملوا بمقتضاه."]], "m": "ما زال السياق في بيان أحكام الطلاق والرجعة والعدة: واللائي يئسن من المحيض لكبر سنهن، كمن تجاوزت الخمسين، إذا طُلّقت بعد الدخول بها، إن شككتم أيها المؤمنون في مدة عدتهن فعدتهن ثلاثة أشهر، واللائي لم يحضن لصغرهن كذلك عدتهن ثلاثة أشهر. وأولات الأحمال إن طُلّقن أو مات عنهن أزواجهن أجلهن في انقضاء عدتهن أن يضعن حملهن، فمتى ولدت ما في بطنها انقضت عدتها ولو وضعته قبل استكمال التسعة أشهر، إن لم تتعمّد إسقاطه. ومن يتّق الله في هذه الأحكام فلا يخالف أمره يجعل له من أمره يسراً، فيسهّل عليه أمره ويرزقه ما تقرّ به عينه. ذلك المذكور من أحكام الطلاق والرجعة والعدة أمر الله أنزله إليكم لتعملوا به ولا تهملوه، ومن يتّق الله في أوامره ونواهيه يكفّر عنه سيئاته ويعظم له أجراً، فيغفر له ذنوبه ويدخله الجنة.", "h": ["بيان العدة، وهي كالتالي: المتوفى عنها زوجها وهي غير حامل عدتها أربعة أشهر وعشر ليال، والمتوفى عنها زوجها وهي حامل عدتها وضع حملها، والمطلقة التي لا تحيض لكبر سنها أو لصغر سنها وقد دُخل بها عدتها ثلاثة أشهر، والمطلقة التي تحيض عدتها ثلاثة قروء، أي حيض تبتدئ بالحيضة التي بعد الطهر الذي طُلّقت فيه، أو ثلاثة أطهار، كذلك الكل واسع، ولفظ القرء مشترك دالّ على الحيض وعلى الطهر.", "بيان أن أحكام الطلاق والرجعة والعِدد مما أوحى الله به وأنزله في كتابه، فوجب العمل به، ولا يحل تبديله أو تغييره باجتهاد أبداً.", "فضل التقوى، وأنها باب كل يسر وخير في الحياة الدنيا والآخرة."], "k": "«ومن يتّق الله يجعل له من أمره يسراً»… كم أمر عسير عندي الآن؟ فلأجرّب معه التقوى."}, {"lbl": "الآيتان ٦ – ٧", "q": "أَسۡكِنُوهُنَّ مِنۡ حَيۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ عَلَيۡهِنَّۚ وَإِن كُنَّ أُوْلَٰتِ حَمۡلٖ فَأَنفِقُواْ عَلَيۡهِنَّ حَتَّىٰ يَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ ﴿٦﴾ لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا ﴿٧﴾", "w": [["أسكنوهن من حيث سكنتم من وُجدكم", "من وسعكم، بحيث يُسكن الرجل مطلّقته في بعض سكنه."], ["ولا تضارّوهن", "لا تطلبوا ضررهن بأي حال، سواء في السكن أو في النفقة."], ["لتضيّقوا عليهن", "لأجل أن تضيّقوا عليهن السكن فيتركنه لكم ويخرجن منه."], ["وإن كنّ أولات حمل", "حوامل يحملن الأجنّة في بطونهن."], ["فإن أرضعن لكم", "أولادكم."], ["فآتوهن أجورهن", "أعطوهن أجورهن على الإرضاع، هذا في المطلقات."], ["وأتمروا بينكم بمعروف", "تشاوروا، وليأمر كل منكم صاحبه بأمر ينتهي باتفاق على أجرة معقولة لا إفراط فيها ولا تفريط."], ["وإن تعاسرتم", "فإن امتنعت الأم من الإرضاع، أو امتنع الأب من الأجرة."], ["لينفق ذو سعة من سعته", "لينفق على المطلقات المرضعات ذو الغنى من غناه."], ["ومن قُدر عليه رزقه", "ومن ضُيّق عليه عيشه."]], "m": "بعد بيان الطلاق بقسميه الرجعي والبائن، وبيان العِدد على اختلافها، بيّن تعالى أحكام النفقات والإرضاع: أسكنوهن من حيث سكنتم من وسعكم، ولا تضارّوهن بأي مضارة في السكن ولا في الإنفاق ولا في غيره، من أجل أن تضيّقوا عليهن فيتركن لكم السكن ويخرجن، وهؤلاء المطلقات طلاقاً رجعياً حوامل أو غير حوامل. وإن كانت المطلقة طلاق البتة حاملاً فأسكنوهن وأنفقوا عليهن إلى أن يلدن، فإن وضعت حملها فهما بالخيار: إن شاءت أرضعت له ولده بأجرة يتفقان عليها، وإن شاء هو أرضع ولده مرضعاً غير أمه، وذلك يتم بتبادل الرأي إلى الاتفاق على أجرة معيّنة، وإن تعاسرا فلم يتفقا فلترضع له امرأة أخرى. لينفق المؤمن على مطلّقته التي ترضع له ولده، أو التي هي في عدتها في بيته، بحسب يساره وإعساره، إذ لا يكلّف الله نفساً إلا ما آتاها، والقاضي هو الذي يقدّر النفقة عند المشاحّة بحسب دخل الرجل وما يملك. سيجعل الله بعد عسر يسراً: هذا وعد صدق أتمّه لأصحاب رسوله حيث كانوا في عسر ففتح عليهم ملك كسرى والروم فأبدل عسرهم يسراً، وأما غيرهم فمشروط بالتقوى كما تقدّم: «ومن يتّق الله يجعل له من أمره يسراً».", "h": ["وجوب السكن والنفقة للمطلقة طلاقاً رجعياً.", "وجوب السكنى والنفقة للمطلقة الحامل حتى تضع حملها.", "وجوب السكنى والنفقة للمتوفى عنها زوجها وهي حامل.", "المطلقة البائن والمبتوتة لم يقضِ لهما رسول الله ﷺ بنفقة ولا سكنى، لحديث فاطمة بنت قيس، ومن الفضل الذي ينبغي ألا يُنسى إن كانت محتاجة إلى سكن أو نفقة أن يسكنها مطلّقها وينفق عليها مدة عدتها، وأجره عظيم لأنه أحسن، والله يحب المحسنين.", "النفقة الواجبة تكون بحسب حال المطلّق غنى وفقراً، والقاضي يقدّرها إن تشاحّا.", "المطلقة طلاقاً بائناً إن أرضعت ولدها لها أجرة إرضاعها حسب اتفاق الطرفين الأم والأب.", "بيان القاعدة العامة، وهي أن لا تُكلّف نفس إلا وسعها."], "k": "«ولا تضارّوهن لتضيّقوا عليهن»… حتى بعد الفراق يحرّم الإضرار؛ فكيف أعامل من اختلفت معه؟"}, {"lbl": "الآيات ٨ – ١٢", "q": "وَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابٗا شَدِيدٗا وَعَذَّبۡنَٰهَا عَذَابٗا نُّكۡرٗا ﴿٨﴾ فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا ﴿٩﴾ أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدٗاۖ فَٱتَّقُواْ ٱللَّهَ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ٱلَّذِينَ ءَامَنُواْۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَيۡكُمۡ ذِكۡرٗا ﴿١٠﴾ رَّسُولٗا يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٖ لِّيُخۡرِجَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا ﴿١١﴾ ٱللَّهُ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا ﴿١٢﴾", "w": [["وكأيّن من قرية", "وكثير من قرية، أي مدينة."], ["عتت عن أمر ربها ورسله", "عصى أهلها ربهم ورسله."], ["وعذّبناها عذاباً نكراً", "فظيعاً."], ["قد أنزل الله إليكم ذكراً رسولاً", "القرآن، وأرسل إليكم رسولاً هو محمد ﷺ."], ["ليخرج الذين آمنوا… من الظلمات إلى النور", "من ظلمات الكفر والشرك إلى نور الإيمان والتوحيد."], ["قد أحسن الله له رزقاً", "رزق الجنة الذي لا ينقطع نعيمه أبداً."], ["ومن الأرض مثلهن", "سبع أرضين، أرضاً فوق أرض، كالسماوات سماء فوق سماء."], ["يتنزّل الأمر بينهن", "الوحي بين السماوات والأرض."], ["لتعلموا أن الله على كل شيء قدير", "أعلمكم بذلك الخلق العظيم والتنزيل العجيب لتعلموا قدرته وإحاطة علمه."]], "m": "لما قرّر تعالى أحكام الطلاق والرجعة والعدة والنفقات وقال: «ذلك أمر الله أنزله إليكم» وأوجب العمل به، حذّر في هذه الآيات من إهمال تلك الأحكام وتجاهلها فقال: وكثير من قرية عتا أهلها، أي ترفّعوا متكبّرين عن أوامر الله ورسله فلم يمتثلوها، وعن الحقوق فلم يؤدّوها، حاسبها الله في الدنيا حساباً شديداً، وعذّبها عذاباً فظيعاً، فذاقت عقوبة أمرها، وكان عاقبة أمرها خساراً وهلاكاً، وأعدّ الله لهم عذاباً شديداً يوم القيامة، وفي تكرار الوعيد تحذير من الوقوع فيه. فاتقوا الله، خافوا عقابه فلا تهملوا أحكامه ولا تعطّلوها فيحلّ بكم ما حلّ بغيركم، يا أولي العقول الذين آمنوا، قد أنزل الله إليكم ذكراً، رسولاً يتلو عليكم آيات الله مبيّنات واضحات، ليخرج الذين آمنوا وعملوا الصالحات من ظلمات الكفر والشرك إلى نور الإيمان والتوحيد والعمل الصالح. ومن يؤمن بالله ويعمل صالحاً يدخله جنات تجري من تحتها الأنهار خالدين فيها أبداً، قد أحسن الله له فيها رزقاً، وهو نعيم الجنة الذي لا ينفد. الله الذي خلق سبع سماوات ومن الأرض مثلهن سبع أرضين، هذا هو الله المعبود بحق، يتنزّل الأمر بينهن، أعلمكم بخلقه العظيم وتنزّل أمره في كل وقت وحين، لتعلموا أنه على كل شيء قدير فترغبوا فيما عنده، وأنه قد أحاط بكل شيء علماً فترهبوه وتراقبوه.", "h": ["التحذير من ترك الأحكام الشرعية وإهمالها والعبث بها.", "بيان منّة الله على هذه الأمة بإنزال القرآن عليها وإرسال الرسول إليها.", "بيان أن الكفر ظلمة، وأن الإيمان نور.", "بيان عظمة الله تعالى وسعة علمه."], "k": "«وأن الله قد أحاط بكل شيء علماً»… إحاطة علمه بي طمأنينة وتحذير معاً؛ فأيهما يغلب عليّ اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 415;
insert into public.tdb_cards(topic, i, body) select 415, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ١", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ ٱلۡعِدَّةَۖ وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرٗا ﴿١﴾", "w": [["يا أيها النبي", "أراد الله بالنداء النبي ﷺ وأمته، بدليل ما بعده."], ["إذا طلّقتم النساء", "إذا أردتم طلاقهن."], ["فطلّقوهن لعدّتهن", "لقُبُل عدتهن، أي في طهر لم يجامعها فيه."], ["وأحصوا العدّة", "احفظوا مدّتها حتى يمكنكم المراجعة فيها."], ["واتقوا الله ربكم", "أطيعوه في أمره ونهيه."], ["لا تخرجوهن من بيوتهن", "لا تخرجوا المطلقة من بيت زوجها الذي طلّقها حتى تنقضي عدتها."], ["إلا أن يأتين بفاحشة مبيّنة", "إلا أن يأتين بالبذاء في القول وسوء الخلق، أو يرتكبن فاحشة من زنا بيّنة ظاهرة لا شك فيها."], ["وتلك حدود الله", "المذكورات من الطلاق في أول الطهر، وإحصاء العدة، وعدم إخراج المطلقة من بيتها حتى تنقضي عدتها."], ["لا تدري لعل الله يُحدث بعد ذلك أمراً", "يجعل في قلب الزوج الرغبة في مراجعتها فيراجعها إذا لم تكن الثالثة من الطلقات."]], "m": "يخاطب الله تبارك وتعالى رجال أمة الإسلام في شخص نبيها محمد ﷺ فيقول: إذا أردتم طلاق نسائكم لأمر اقتضى ذلك فطلّقوهن لأول عدّتهن، وذلك في طهر لم تُجامع فيه، ليُعدّ ذلك الطهر أول عدتها. وأحصوا العدة، فاعرفوا بدايتها ونهايتها لما يترتب على ذلك من أحكام: من صحة المراجعة وعدمها، ومن النفقة والإسكان. واتقوا الله ربكم فامتثلوا أوامره وقفوا عند حدوده، لا تخرجوا المطلقات من بيوتهن اللاتي طُلّقن فيهن، ويجب ألّا يخرجن، إلا أن يأتين بفاحشة مبيّنة كزنا ظاهر، أو تكون سيئة بذيئة اللسان فتؤذي أهل البيت أذى لا يتحمّلونه، فعندئذ يُباح إخراجها. وتلك حدود الله، ومن يتعدّها فلم يقف عندها فقد ظلم نفسه وتعرّض لعقوبة الله عاجلاً أو آجلاً. لا تدري لعل الله يُحدث بعد ذلك أمراً، بأن يجعل في قلب الرجل رغبة في مراجعة مطلّقته فيراجعها، وفي ذلك خير كثير.", "h": ["بيان السنة في الطلاق، وهي أن يطلّقها في طهر لم يمسّها فيه بجماع.", "أن يكون الطلاق واحدة، لا اثنتين ولا ثلاثاً.", "وجوب إحصاء العدة ليعرف الزوج متى تنقضي عدة مطلّقته، لما يترتب على ذلك من أحكام الرجعة والنفقة والإسكان.", "حرمة إخراج المطلقة من بيتها الذي طُلّقت فيه إلى أن تنقضي عدتها، إلا أن ترتكب فاحشة ظاهرة كزنا، أو بذاءة وسوء خلق وقبيح معاملة، فعندئذ يجوز إخراجها."], "k": "«لا تدري لعل الله يُحدث بعد ذلك أمراً»… حتى في ساعة الغضب يترك الله باباً مفتوحاً؛ فهل أترك أنا باباً للصلح؟"}, {"lbl": "الآيتان ٢ – ٣", "q": "فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا ﴿٢﴾ وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا ﴿٣﴾", "w": [["فإذا بلغن أجلهن", "قاربن انقضاء عدّتهن."], ["فأمسكوهن بمعروف", "راجعوهن بمعروف من غير ضرر."], ["أو فارقوهن بمعروف", "اتركوهن حتى تنقضي عدتهن، ولا تضارّوهن بالمراجعة."], ["وأشهدوا ذوَي عدل منكم", "أشهدوا على الطلاق وعلى الرجعة رجلين عدلين منكم."], ["وأقيموا الشهادة لله", "لا للمشهود عليه أو له، بل لله تعالى وحده."], ["ذلكم يوعظ به من كان يؤمن بالله واليوم الآخر", "ذلكم المذكور من أول السورة من أحكام يُؤمر به وينفّذه المؤمن بالله واليوم الآخر."], ["ومن يتّق الله", "في أمره ونهيه فلا يعصه فيهما."], ["يجعل له مخرجاً", "من كل ضيق."], ["ويرزقه من حيث لا يحتسب", "من حيث لا يرجو ولا يؤمّل."], ["فهو حسبه", "كافيه ما يهمّه من أمر دينه ودنياه."], ["قد جعل الله لكل شيء قدراً", "من الطلاق والعدة وغير ذلك، حدّاً وأجلاً ينتهي إليه."]], "m": "ما زال السياق في بيان العِدد وأحكام الطلاق والرجعة: فإذا قاربت المطلقات انقضاء العدة فأمسكوهن بمعروف، أي راجعوهن على أساس حسن العشرة، لا للإضرار بهن، كأن يراجعها ثم يطلّقها ليطيل عليها العدة، فهذا لا يجوز لحرمة الإضرار بالناس، وفي الحديث: «لا ضرر ولا ضرار»، أو فارقوهن بمعروف بأن يعطيها ما بقي لها من مهرها ويمتّعها بحسب حاله غنى وفقراً. وأشهدوا ذوي عدل منكم على النكاح والطلاق والرجعة؛ أما الإشهاد على النكاح فركن لا يصح النكاح بدونه، وأما في الطلاق والرجعة فهو مندوب، وقد يصح الطلاق والرجعة بدونه، ويُشترط في الشهود أن يكونوا عدولاً مسلمين. وأقيموا الشهادة لله، أدّوها على وجهها ولا تراعوا فيها إلا وجه الله. ذلكم المأمور به من أول السورة يُوعظ به وينفّذه المؤمن بالله واليوم الآخر، إذ هو الذي يخاف عقوبة الله فلا يقدم على معصيته. ومن يتّق الله يجعل له مخرجاً ويرزقه من حيث لا يحتسب: نزلت في عوف بن مالك الأشجعي، أتى رسول الله ﷺ فقال: إن ابني أسره العدو وجزعت أمه فبمَ تأمرني؟ قال: «آمرك وإياها أن تكثرا من قول: لا حول ولا قوة إلا بالله»، فجعلا يكثران منها، فغفل العدو عن ابنهما فاستاق غنمهم وجاء بها إلى أبويه، فنزلت هذه الآية، وهي عامة في كل من يتّقي الله، يجعل له من كل ضيق مخرجاً ومن كل كرب فرجاً، ويرزقه من حيث لا يخطر له على بال. ومن يتوكّل على الله فلا يفرّط في أمر الله ولا يضيّع حقوقه فإن الله يكفيه ما يهمّه. إن الله بالغ أمره، منفّذه في عباده لا يعجزونه، قد جعل لكل شيء قدراً: مقداراً وزماناً ومكاناً، فلا يتقدّم ولا يتأخّر، فمن رضي فله الرضا ومن سخط فله السخط.", "h": ["لا تصح الرجعة إلا في العدة، فإن انقضت العدة فلا رجعة، وللمطلقة أن تتزوّج من شاءت، هو أو غيره، من ساعة انقضاء عدتها.", "لا تحل المراجعة للإضرار، ولكن للفضل والإحسان وطيب العشرة.", "مشروعية الإشهاد على الطلاق والرجعة معاً.", "يُشترط في الشهود العدالة.", "وعد الله الصادق بالفرج القريب لكل من يتّقيه سبحانه وتعالى، والرزق من حيث لا يرجو.", "تقرير عقيدة القضاء والقدر.", "كفاية الله لمن توكّل عليه."], "k": "«ومن يتّق الله يجعل له مخرجاً»… في ضيقي الحالي، هل أبحث عن المخرج في التقوى أم في الحيلة؟"}, {"lbl": "الآيتان ٤ – ٥", "q": "وَٱلَّـٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرٖ وَٱلَّـٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرٗا ﴿٤﴾ ذَٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيۡكُمۡۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا ﴿٥﴾", "w": [["واللائي يئسن من المحيض", "والنسوة اللائي يئسن من الحيض."], ["إن ارتبتم", "شككتم في عدّتهن."], ["واللائي لم يحضن", "لصغر سن."], ["وأولات الأحمال", "النساء الحوامل."], ["أجلهن أن يضعن حملهن", "انقضاء عدتهن أن يضعن حملهن."], ["ذلك أمر الله", "ذلك المذكور في العدة وتفاصيلها."], ["أنزله إليكم", "لتأتمروا به وتعملوا بمقتضاه."]], "m": "ما زال السياق في بيان أحكام الطلاق والرجعة والعدة: واللائي يئسن من المحيض لكبر سنهن، كمن تجاوزت الخمسين، إذا طُلّقت بعد الدخول بها، إن شككتم أيها المؤمنون في مدة عدتهن فعدتهن ثلاثة أشهر، واللائي لم يحضن لصغرهن كذلك عدتهن ثلاثة أشهر. وأولات الأحمال إن طُلّقن أو مات عنهن أزواجهن أجلهن في انقضاء عدتهن أن يضعن حملهن، فمتى ولدت ما في بطنها انقضت عدتها ولو وضعته قبل استكمال التسعة أشهر، إن لم تتعمّد إسقاطه. ومن يتّق الله في هذه الأحكام فلا يخالف أمره يجعل له من أمره يسراً، فيسهّل عليه أمره ويرزقه ما تقرّ به عينه. ذلك المذكور من أحكام الطلاق والرجعة والعدة أمر الله أنزله إليكم لتعملوا به ولا تهملوه، ومن يتّق الله في أوامره ونواهيه يكفّر عنه سيئاته ويعظم له أجراً، فيغفر له ذنوبه ويدخله الجنة.", "h": ["بيان العدة، وهي كالتالي: المتوفى عنها زوجها وهي غير حامل عدتها أربعة أشهر وعشر ليال، والمتوفى عنها زوجها وهي حامل عدتها وضع حملها، والمطلقة التي لا تحيض لكبر سنها أو لصغر سنها وقد دُخل بها عدتها ثلاثة أشهر، والمطلقة التي تحيض عدتها ثلاثة قروء، أي حيض تبتدئ بالحيضة التي بعد الطهر الذي طُلّقت فيه، أو ثلاثة أطهار، كذلك الكل واسع، ولفظ القرء مشترك دالّ على الحيض وعلى الطهر.", "بيان أن أحكام الطلاق والرجعة والعِدد مما أوحى الله به وأنزله في كتابه، فوجب العمل به، ولا يحل تبديله أو تغييره باجتهاد أبداً.", "فضل التقوى، وأنها باب كل يسر وخير في الحياة الدنيا والآخرة."], "k": "«ومن يتّق الله يجعل له من أمره يسراً»… كم أمر عسير عندي الآن؟ فلأجرّب معه التقوى."}, {"lbl": "الآيتان ٦ – ٧", "q": "أَسۡكِنُوهُنَّ مِنۡ حَيۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ عَلَيۡهِنَّۚ وَإِن كُنَّ أُوْلَٰتِ حَمۡلٖ فَأَنفِقُواْ عَلَيۡهِنَّ حَتَّىٰ يَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ ﴿٦﴾ لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا ﴿٧﴾", "w": [["أسكنوهن من حيث سكنتم من وُجدكم", "من وسعكم، بحيث يُسكن الرجل مطلّقته في بعض سكنه."], ["ولا تضارّوهن", "لا تطلبوا ضررهن بأي حال، سواء في السكن أو في النفقة."], ["لتضيّقوا عليهن", "لأجل أن تضيّقوا عليهن السكن فيتركنه لكم ويخرجن منه."], ["وإن كنّ أولات حمل", "حوامل يحملن الأجنّة في بطونهن."], ["فإن أرضعن لكم", "أولادكم."], ["فآتوهن أجورهن", "أعطوهن أجورهن على الإرضاع، هذا في المطلقات."], ["وأتمروا بينكم بمعروف", "تشاوروا، وليأمر كل منكم صاحبه بأمر ينتهي باتفاق على أجرة معقولة لا إفراط فيها ولا تفريط."], ["وإن تعاسرتم", "فإن امتنعت الأم من الإرضاع، أو امتنع الأب من الأجرة."], ["لينفق ذو سعة من سعته", "لينفق على المطلقات المرضعات ذو الغنى من غناه."], ["ومن قُدر عليه رزقه", "ومن ضُيّق عليه عيشه."]], "m": "بعد بيان الطلاق بقسميه الرجعي والبائن، وبيان العِدد على اختلافها، بيّن تعالى أحكام النفقات والإرضاع: أسكنوهن من حيث سكنتم من وسعكم، ولا تضارّوهن بأي مضارة في السكن ولا في الإنفاق ولا في غيره، من أجل أن تضيّقوا عليهن فيتركن لكم السكن ويخرجن، وهؤلاء المطلقات طلاقاً رجعياً حوامل أو غير حوامل. وإن كانت المطلقة طلاق البتة حاملاً فأسكنوهن وأنفقوا عليهن إلى أن يلدن، فإن وضعت حملها فهما بالخيار: إن شاءت أرضعت له ولده بأجرة يتفقان عليها، وإن شاء هو أرضع ولده مرضعاً غير أمه، وذلك يتم بتبادل الرأي إلى الاتفاق على أجرة معيّنة، وإن تعاسرا فلم يتفقا فلترضع له امرأة أخرى. لينفق المؤمن على مطلّقته التي ترضع له ولده، أو التي هي في عدتها في بيته، بحسب يساره وإعساره، إذ لا يكلّف الله نفساً إلا ما آتاها، والقاضي هو الذي يقدّر النفقة عند المشاحّة بحسب دخل الرجل وما يملك. سيجعل الله بعد عسر يسراً: هذا وعد صدق أتمّه لأصحاب رسوله حيث كانوا في عسر ففتح عليهم ملك كسرى والروم فأبدل عسرهم يسراً، وأما غيرهم فمشروط بالتقوى كما تقدّم: «ومن يتّق الله يجعل له من أمره يسراً».", "h": ["وجوب السكن والنفقة للمطلقة طلاقاً رجعياً.", "وجوب السكنى والنفقة للمطلقة الحامل حتى تضع حملها.", "وجوب السكنى والنفقة للمتوفى عنها زوجها وهي حامل.", "المطلقة البائن والمبتوتة لم يقضِ لهما رسول الله ﷺ بنفقة ولا سكنى، لحديث فاطمة بنت قيس، ومن الفضل الذي ينبغي ألا يُنسى إن كانت محتاجة إلى سكن أو نفقة أن يسكنها مطلّقها وينفق عليها مدة عدتها، وأجره عظيم لأنه أحسن، والله يحب المحسنين.", "النفقة الواجبة تكون بحسب حال المطلّق غنى وفقراً، والقاضي يقدّرها إن تشاحّا.", "المطلقة طلاقاً بائناً إن أرضعت ولدها لها أجرة إرضاعها حسب اتفاق الطرفين الأم والأب.", "بيان القاعدة العامة، وهي أن لا تُكلّف نفس إلا وسعها."], "k": "«ولا تضارّوهن لتضيّقوا عليهن»… حتى بعد الفراق يحرّم الإضرار؛ فكيف أعامل من اختلفت معه؟"}, {"lbl": "الآيات ٨ – ١٢", "q": "وَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابٗا شَدِيدٗا وَعَذَّبۡنَٰهَا عَذَابٗا نُّكۡرٗا ﴿٨﴾ فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا ﴿٩﴾ أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدٗاۖ فَٱتَّقُواْ ٱللَّهَ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ٱلَّذِينَ ءَامَنُواْۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَيۡكُمۡ ذِكۡرٗا ﴿١٠﴾ رَّسُولٗا يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٖ لِّيُخۡرِجَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا ﴿١١﴾ ٱللَّهُ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا ﴿١٢﴾", "w": [["وكأيّن من قرية", "وكثير من قرية، أي مدينة."], ["عتت عن أمر ربها ورسله", "عصى أهلها ربهم ورسله."], ["وعذّبناها عذاباً نكراً", "فظيعاً."], ["قد أنزل الله إليكم ذكراً رسولاً", "القرآن، وأرسل إليكم رسولاً هو محمد ﷺ."], ["ليخرج الذين آمنوا… من الظلمات إلى النور", "من ظلمات الكفر والشرك إلى نور الإيمان والتوحيد."], ["قد أحسن الله له رزقاً", "رزق الجنة الذي لا ينقطع نعيمه أبداً."], ["ومن الأرض مثلهن", "سبع أرضين، أرضاً فوق أرض، كالسماوات سماء فوق سماء."], ["يتنزّل الأمر بينهن", "الوحي بين السماوات والأرض."], ["لتعلموا أن الله على كل شيء قدير", "أعلمكم بذلك الخلق العظيم والتنزيل العجيب لتعلموا قدرته وإحاطة علمه."]], "m": "لما قرّر تعالى أحكام الطلاق والرجعة والعدة والنفقات وقال: «ذلك أمر الله أنزله إليكم» وأوجب العمل به، حذّر في هذه الآيات من إهمال تلك الأحكام وتجاهلها فقال: وكثير من قرية عتا أهلها، أي ترفّعوا متكبّرين عن أوامر الله ورسله فلم يمتثلوها، وعن الحقوق فلم يؤدّوها، حاسبها الله في الدنيا حساباً شديداً، وعذّبها عذاباً فظيعاً، فذاقت عقوبة أمرها، وكان عاقبة أمرها خساراً وهلاكاً، وأعدّ الله لهم عذاباً شديداً يوم القيامة، وفي تكرار الوعيد تحذير من الوقوع فيه. فاتقوا الله، خافوا عقابه فلا تهملوا أحكامه ولا تعطّلوها فيحلّ بكم ما حلّ بغيركم، يا أولي العقول الذين آمنوا، قد أنزل الله إليكم ذكراً، رسولاً يتلو عليكم آيات الله مبيّنات واضحات، ليخرج الذين آمنوا وعملوا الصالحات من ظلمات الكفر والشرك إلى نور الإيمان والتوحيد والعمل الصالح. ومن يؤمن بالله ويعمل صالحاً يدخله جنات تجري من تحتها الأنهار خالدين فيها أبداً، قد أحسن الله له فيها رزقاً، وهو نعيم الجنة الذي لا ينفد. الله الذي خلق سبع سماوات ومن الأرض مثلهن سبع أرضين، هذا هو الله المعبود بحق، يتنزّل الأمر بينهن، أعلمكم بخلقه العظيم وتنزّل أمره في كل وقت وحين، لتعلموا أنه على كل شيء قدير فترغبوا فيما عنده، وأنه قد أحاط بكل شيء علماً فترهبوه وتراقبوه.", "h": ["التحذير من ترك الأحكام الشرعية وإهمالها والعبث بها.", "بيان منّة الله على هذه الأمة بإنزال القرآن عليها وإرسال الرسول إليها.", "بيان أن الكفر ظلمة، وأن الإيمان نور.", "بيان عظمة الله تعالى وسعة علمه."], "k": "«وأن الله قد أحاط بكل شيء علماً»… إحاطة علمه بي طمأنينة وتحذير معاً؛ فأيهما يغلب عليّ اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (416, 66, 1, 12, 'سورة التحريم ١ – ١٢', 'التحريم: قوا أنفسكم وأهليكم ناراً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 416) = $j$[{"lbl": "الآيات ١ – ٥", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿١﴾ قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ﴿٢﴾ وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ ﴿٣﴾ إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَـٰٓئِكَةُ بَعۡدَ ذَٰلِكَ ظَهِيرٌ ﴿٤﴾ عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا خَيۡرٗا مِّنكُنَّ مُسۡلِمَٰتٖ مُّؤۡمِنَٰتٖ قَٰنِتَٰتٖ تَـٰٓئِبَٰتٍ عَٰبِدَٰتٖ سَـٰٓئِحَٰتٖ ثَيِّبَٰتٖ وَأَبۡكَارٗا ﴿٥﴾", "w": [["لم تحرّم ما أحلّ الله لك", "لِم تحرّم جاريتك مارية التي أحلّها الله لك؟"], ["تبتغي مرضات أزواجك", "بتحريمها."], ["قد فرض الله لكم تحلّة أيمانكم", "شرع لكم تحليلها بالكفارة المذكورة في سورة المائدة."], ["وإذ أسرّ النبي إلى بعض أزواجه", "هي حفصة بنت عمر رضي الله عنهما."], ["حديثاً", "هو تحريم مارية، وقوله لها: لا تفشيه."], ["فلما نبّأت به", "أخبرت حفصة عائشة به ظناً منها أنه لا حرج في ذلك."], ["وأظهره الله عليه", "أطلعه على المنبّأ به."], ["وأعرض عن بعض", "تكرّماً منه ﷺ."], ["إن تتوبا إلى الله", "حفصة وعائشة رضي الله عنهما، تُقبل توبتكما."], ["فقد صغت قلوبكما", "مالت إلى تحريم مارية، أي سرّكما ذلك."], ["وإن تظاهرا عليه", "تتعاونا على النبي ﷺ فيما يكرهه."], ["فإن الله هو مولاه", "ناصره."], ["وصالح المؤمنين", "أبو بكر وعمر رضي الله عنهما."], ["والملائكة بعد ذلك ظهير", "ظُهراء وأعوان له."], ["قانتات", "عابدات."], ["سائحات", "صائمات أو مهاجرات."]], "m": "في هذا عتاب من الله تعالى لرسوله ﷺ إذ حرّم جاريته مارية ترضية لإحدى نسائه، وذلك أنه ﷺ خلا بها في بيت إحدى نسائه فاطّلعت عليه، فجعلها عليه حراماً ترضية لصاحبة الحجرة، فأنزل الله: يا أيها النبي لم تحرّم ما أحلّ الله لك، يعني جاريته مارية القبطية أم إبراهيم، تطلب رضا أزواجك، والله غفور رحيم بك، فلا لوم عليك بعد هذا، فجاريتك لا تحرم عليك، وكفّر عن يمينك، إذ قال لها: هي عليّ حرام، ووالله لا أطؤها. قد شرع الله لكم ما تتحلّلون به من أيمانكم إذا حلفتم، وهي ما جاء في سورة المائدة: «فكفّارته إطعام عشرة مساكين…»، والله مولاكم متولّي أمركم وناصركم، وهو العليم الحكيم. واذكر إذ أسرّ النبي لحفصة حديثاً إذ قال لها: لقد حرّمت فلانة، وطلب منها ألا تفشي هذا السر، فحدّثت به عائشة، فأطلع الله رسوله على ذلك، فعرّف بعضه لحفصة وأعرض عن بعض تكرّماً منه ﷺ، قالت: من أنبأك هذا؟ قال: نبّأني العليم الخبير. إن تتوبا إلى الله يا حفصة وعائشة فقد مالت قلوبكما إلى تحريم مارية، تُقبل توبتكما، وإن تتعاونا عليه فيما يكرهه فإن تعاونكما لن يضرّه شيئاً، فإن الله هو مولاه وجبريل وصالح المؤمنين أبو بكر وعمر، والملائكة بعد ذلك أعوان له على كل من يؤذيه. عسى ربه إن طلّقكن أن يبدله أزواجاً خيراً منكن، وفي هذا تخويف شديد لأمهات المؤمنين وتأديب رباني كبير لهن، إلا أن الرسول ﷺ لم يطلّقهن، فهن زوجاته في الدنيا وزوجاته في الآخرة. وفي الذي حرّمه رسول الله ﷺ على نفسه خلاف كبير بين أهل التفسير: هل هو شراب كان يحبه أو جاريته مارية، والجمهور على أن المحرّم مارية، وفي البخاري أنه العسل، والله أعلم.", "h": ["تقرير نبوته ﷺ وبشريته الكاملة.", "أخذ الشافعي وأحمد رحمهما الله من هذه الآية أن من قال لزوجته: أنت حرام، أو حرّمتك، وهو لم ينوِ طلاقها، أن عليه كفارة يمين لا غير، وذكر القرطبي في هذه المسألة ثمانية عشر قولاً للفقهاء أشدّها البتّة، وأرفقها أن فيها كفارة يمين.", "كرامة الرسول ﷺ على ربه.", "فضل أبي بكر وعمر رضي الله عنهما."], "k": "«وأعرض عن بعض»… من كرم النفس ألا أستقصي كل خطأ لمن أحب؛ فهل أعرض عن بعض؟"}, {"lbl": "الآيات ٦ – ٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَـٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ ﴿٦﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٧﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٨﴾", "w": [["قوا أنفسكم وأهليكم", "اجعلوا لها وقاية بطاعة الله والرسول ﷺ."], ["ناراً وقودها الناس والحجارة", "تُوقد بالكفار والأصنام التي تُعبد من دون الله، لا بالحطب."], ["لا تعتذروا اليوم", "لأنه لا ينفعكم اعتذار، يقال لهم هذا عند دخولهم النار."], ["توبة نصوحاً", "توبة صادقة، بألا يُعاد إلى الذنب ولا يُراد العود إليه."], ["يوم لا يُخزي الله النبي والذين آمنوا معه", "بإدخالهم النار."], ["نورهم يسعى بين أيديهم وبأيمانهم", "أمامهم ومن كل جهاتهم على قدر أعمالهم."], ["ربنا أتمم لنا نورنا", "إلى الجنة، لأن المنافقين ينطفئ نورهم."]], "m": "هذا نداء الله إلى عباده المؤمنين يعظهم وينصح لهم فيه أن يقوا أنفسهم وأهليهم من زوجة وولد ناراً عظيمة وقودها الناس من المشركين والحجارة التي هي أصنامهم، يقون أنفسهم بطاعة الله ورسوله، تلك الطاعة التي تزكّي أنفسهم وتؤهّلهم لدخول الجنة بعد النجاة من النار. عليها ملائكة قائمون عليها، وهم الخزنة التسعة عشر، غلاظ القلوب والطباع، شداد البطش، لا يخالفون أمره، ويفعلون ما يؤمرون. ويقال لأهل النار: يا أيها الذين كفروا لا تعتذروا اليوم حيث لا ينفع الاعتذار، إنما تُجزون ما كنتم تعملون. ثم النداء الثاني: يا أيها الذين آمنوا توبوا إلى الله توبة عاجلة نصوحاً، لا يعود صاحبها إلى الذنب كما لا يعود اللبن إلى الضرع، يعدهم بتكفير سيئاتهم ويبشّرهم بالجنة: عسى ربكم أن يكفّر عنكم سيئاتكم ويدخلكم جنات تجري من تحتها الأنهار، يوم لا يُخزي الله النبي والذين آمنوا معه بإدخالهم النار، نورهم يسعى بين أيديهم وبأيمانهم وهم يجتازون الصراط، يسألون ربهم أن يُبقي لهم نورهم حتى يجتازوا الصراط، وأن يغفر لهم ذنوبهم، ويتوسّلون إليه بصفة القدرة: إنك على كل شيء قدير.", "h": ["وجوب العناية بالزوجة والأولاد وتربيتهم، وأمرهم بطاعة الله ورسوله، ونهيهم عن ترك ذلك.", "وجوب التوبة الفورية على كل من أذنب من المؤمنين والمؤمنات، وهي الإقلاع من الذنب فوراً، أي تركه والتخلّي عنه، ثم العزم على ألا يعود إليه في صدق، ثم ملازمة الندم والاستغفار، كلما ذكر ذنبه استغفر ربه وندم على فعله، وإن كان الذنب متعلقاً بحق آدمي كأخذ ماله أو ضرب جسمه أو انتهاك عرضه وجب التحلّل منه حتى يعفو ويسامح."], "k": "«قوا أنفسكم وأهليكم ناراً»… أهتم بطعام أهلي ولباسهم؛ فهل أهتم بنجاتهم بالقدر نفسه؟"}, {"lbl": "الآيات ٩ – ١٢", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٩﴾ ضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحٖ وَٱمۡرَأَتَ لُوطٖۖ كَانَتَا تَحۡتَ عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ ٱللَّهِ شَيۡـٔٗا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّـٰخِلِينَ ﴿١٠﴾ وَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿١١﴾ وَمَرۡيَمَ ٱبۡنَتَ عِمۡرَٰنَ ٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَٰنِتِينَ ﴿١٢﴾", "w": [["جاهد الكفار", "بالسيف."], ["والمنافقين", "باللسان."], ["واغلظ عليهم", "اشدد عليهم في الخطاب، ولا تعاملهم باللين."], ["امرأة نوح وامرأة لوط", "ضربهما الله مثلاً للذين كفروا."], ["فخانتاهما", "في الدين، إذ كانتا كافرتين."], ["فلم يُغنيا عنهما من الله شيئاً", "لم يغنِ نوح ولوط عن امرأتيهما من عذاب الله شيئاً وإن قلّ."], ["امرأة فرعون", "آسيا بنت مزاحم، آمنت بموسى."], ["أحصنت فرجها", "حفظته فلم يصل إليه الرجال لا بنكاح ولا زنا."], ["فنفخنا فيه من روحنا", "نفخنا في كُمّ درعها بواسطة جبريل الملقّب بروح القدس."], ["وصدّقت بكلمات ربها", "بولدها عيسى أنه كلمة الله وعبده ورسوله، وبشرائعه وكتبه."]], "m": "يأمر تعالى رسوله ﷺ بعدما ناداه بعنوان النبوة تشريفاً بجهاد الكفار والمنافقين: الكفار بالسيف حتى يسلموا، والمنافقين بالقول الغليظ والعبارة البليغة الحاملة للوعيد والتهديد، واشدد عليهم، ومأواهم جهنم وبئس المصير إذا ماتوا على نفاقهم وكفرهم. ثم ضرب الله مثلاً في عدم انتفاع الكافر بقرابة المؤمن مهما كانت درجة القرابة: امرأة نوح وامرأة لوط، كانتا تحت نبيّين رسولين فخانتاهما في دينهما فكانتا كافرتين؛ فامرأة نوح تفشي سر من يؤمن بزوجها وتخبر به الجبابرة من قومه، وتقول لهم: إن زوجها مجنون، وامرأة لوط كانت تدلّ المجرمين على ضيوف لوط إذا نزلوا عليه، فلم تغنِ عنهما قرابة الزوجية شيئاً، ويوم القيامة يقال لهما: ادخلا النار مع الداخلين. ومثل آخر في عدم تضرّر المؤمن بقرابة الكافر ولو كانت الزوجية: امرأة فرعون آسيا بنت مزاحم، آمنت بموسى، فلما عرف فرعون إيمانها أمر بقتلها، فقالت في مناجاتها: رب ابنِ لي عندك بيتاً في الجنة ونجّني من فرعون وعمله الذي هو الكفر والظلم، ونجّني من القوم الظالمين، فشُدّت يداها ورجلاها لتُلقى عليها صخرة عظيمة إن هي أصرّت على الإيمان، فرفعت بصرها إلى السماء فرأت بيتها في الجنة ففاضت روحها، فوصلت الصخرة إليها بعد أن فاضت روحها، فنجّاها الله من عذاب القتل. ومريم ابنة عمران التي أحصنت فرجها، عطفها على آسيا ليكون المثل مكوّناً من امرأتين مؤمنتين كما كان الأول من امرأتين كافرتين؛ أحصنت فرجها عن الرجال في الوقت الذي عمّ البغاء ديار بني إسرائيل، فأكرمها الله بأن أرسل إليها روحه جبريل ﵇ فنفخ في كُمّ درعها، فسرت النفخة بقدرة الله في جسمها فحملت بعيسى الذي كان بكلمة الله «كن». قال ابن عباس رضي الله عنهما: ما بغت امرأة نبي قط، فالمراد من الخيانة المذكورة الخيانة في الدين وإفشاء الأسرار. وصدّقت بكلمات ربها وكتبه، وكانت من القانتين المطيعين لله المخبتين.", "h": ["وجوب الجهاد في الكفار بالسيف، وفي المنافقين باللسان، وعلى حكّام المسلمين القيام بذلك لأنهم خلفاء النبي ﷺ في أمته.", "تقرير مبدأ: لا تزر وازرة وزر أخرى؛ فالكافر لا ينتفع بالمؤمن يوم القيامة، والمؤمن لا يتضرّر بالكافر ولو كانت القرابة نبوة أو أبوة أو بنوة، فإبراهيم لم يضرّه كفر آزر، ونوح لم يضرّه كفر ابنه، كما أن آزر وابن نوح لم ينفعهما إيمان الأب والابن؛ هذا، وقرابة المؤمن الصالح تنفع المؤمن دون الصالح، لقوله تعالى: «والذين آمنوا واتّبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم»."], "k": "«رب ابنِ لي عندك بيتاً في الجنة»… في قصر فرعون كان همّها بيتاً عند ربها؛ فما همّي أنا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 416;
insert into public.tdb_cards(topic, i, body) select 416, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿١﴾ قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ﴿٢﴾ وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ ﴿٣﴾ إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَـٰٓئِكَةُ بَعۡدَ ذَٰلِكَ ظَهِيرٌ ﴿٤﴾ عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا خَيۡرٗا مِّنكُنَّ مُسۡلِمَٰتٖ مُّؤۡمِنَٰتٖ قَٰنِتَٰتٖ تَـٰٓئِبَٰتٍ عَٰبِدَٰتٖ سَـٰٓئِحَٰتٖ ثَيِّبَٰتٖ وَأَبۡكَارٗا ﴿٥﴾", "w": [["لم تحرّم ما أحلّ الله لك", "لِم تحرّم جاريتك مارية التي أحلّها الله لك؟"], ["تبتغي مرضات أزواجك", "بتحريمها."], ["قد فرض الله لكم تحلّة أيمانكم", "شرع لكم تحليلها بالكفارة المذكورة في سورة المائدة."], ["وإذ أسرّ النبي إلى بعض أزواجه", "هي حفصة بنت عمر رضي الله عنهما."], ["حديثاً", "هو تحريم مارية، وقوله لها: لا تفشيه."], ["فلما نبّأت به", "أخبرت حفصة عائشة به ظناً منها أنه لا حرج في ذلك."], ["وأظهره الله عليه", "أطلعه على المنبّأ به."], ["وأعرض عن بعض", "تكرّماً منه ﷺ."], ["إن تتوبا إلى الله", "حفصة وعائشة رضي الله عنهما، تُقبل توبتكما."], ["فقد صغت قلوبكما", "مالت إلى تحريم مارية، أي سرّكما ذلك."], ["وإن تظاهرا عليه", "تتعاونا على النبي ﷺ فيما يكرهه."], ["فإن الله هو مولاه", "ناصره."], ["وصالح المؤمنين", "أبو بكر وعمر رضي الله عنهما."], ["والملائكة بعد ذلك ظهير", "ظُهراء وأعوان له."], ["قانتات", "عابدات."], ["سائحات", "صائمات أو مهاجرات."]], "m": "في هذا عتاب من الله تعالى لرسوله ﷺ إذ حرّم جاريته مارية ترضية لإحدى نسائه، وذلك أنه ﷺ خلا بها في بيت إحدى نسائه فاطّلعت عليه، فجعلها عليه حراماً ترضية لصاحبة الحجرة، فأنزل الله: يا أيها النبي لم تحرّم ما أحلّ الله لك، يعني جاريته مارية القبطية أم إبراهيم، تطلب رضا أزواجك، والله غفور رحيم بك، فلا لوم عليك بعد هذا، فجاريتك لا تحرم عليك، وكفّر عن يمينك، إذ قال لها: هي عليّ حرام، ووالله لا أطؤها. قد شرع الله لكم ما تتحلّلون به من أيمانكم إذا حلفتم، وهي ما جاء في سورة المائدة: «فكفّارته إطعام عشرة مساكين…»، والله مولاكم متولّي أمركم وناصركم، وهو العليم الحكيم. واذكر إذ أسرّ النبي لحفصة حديثاً إذ قال لها: لقد حرّمت فلانة، وطلب منها ألا تفشي هذا السر، فحدّثت به عائشة، فأطلع الله رسوله على ذلك، فعرّف بعضه لحفصة وأعرض عن بعض تكرّماً منه ﷺ، قالت: من أنبأك هذا؟ قال: نبّأني العليم الخبير. إن تتوبا إلى الله يا حفصة وعائشة فقد مالت قلوبكما إلى تحريم مارية، تُقبل توبتكما، وإن تتعاونا عليه فيما يكرهه فإن تعاونكما لن يضرّه شيئاً، فإن الله هو مولاه وجبريل وصالح المؤمنين أبو بكر وعمر، والملائكة بعد ذلك أعوان له على كل من يؤذيه. عسى ربه إن طلّقكن أن يبدله أزواجاً خيراً منكن، وفي هذا تخويف شديد لأمهات المؤمنين وتأديب رباني كبير لهن، إلا أن الرسول ﷺ لم يطلّقهن، فهن زوجاته في الدنيا وزوجاته في الآخرة. وفي الذي حرّمه رسول الله ﷺ على نفسه خلاف كبير بين أهل التفسير: هل هو شراب كان يحبه أو جاريته مارية، والجمهور على أن المحرّم مارية، وفي البخاري أنه العسل، والله أعلم.", "h": ["تقرير نبوته ﷺ وبشريته الكاملة.", "أخذ الشافعي وأحمد رحمهما الله من هذه الآية أن من قال لزوجته: أنت حرام، أو حرّمتك، وهو لم ينوِ طلاقها، أن عليه كفارة يمين لا غير، وذكر القرطبي في هذه المسألة ثمانية عشر قولاً للفقهاء أشدّها البتّة، وأرفقها أن فيها كفارة يمين.", "كرامة الرسول ﷺ على ربه.", "فضل أبي بكر وعمر رضي الله عنهما."], "k": "«وأعرض عن بعض»… من كرم النفس ألا أستقصي كل خطأ لمن أحب؛ فهل أعرض عن بعض؟"}, {"lbl": "الآيات ٦ – ٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَـٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ ﴿٦﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٧﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٨﴾", "w": [["قوا أنفسكم وأهليكم", "اجعلوا لها وقاية بطاعة الله والرسول ﷺ."], ["ناراً وقودها الناس والحجارة", "تُوقد بالكفار والأصنام التي تُعبد من دون الله، لا بالحطب."], ["لا تعتذروا اليوم", "لأنه لا ينفعكم اعتذار، يقال لهم هذا عند دخولهم النار."], ["توبة نصوحاً", "توبة صادقة، بألا يُعاد إلى الذنب ولا يُراد العود إليه."], ["يوم لا يُخزي الله النبي والذين آمنوا معه", "بإدخالهم النار."], ["نورهم يسعى بين أيديهم وبأيمانهم", "أمامهم ومن كل جهاتهم على قدر أعمالهم."], ["ربنا أتمم لنا نورنا", "إلى الجنة، لأن المنافقين ينطفئ نورهم."]], "m": "هذا نداء الله إلى عباده المؤمنين يعظهم وينصح لهم فيه أن يقوا أنفسهم وأهليهم من زوجة وولد ناراً عظيمة وقودها الناس من المشركين والحجارة التي هي أصنامهم، يقون أنفسهم بطاعة الله ورسوله، تلك الطاعة التي تزكّي أنفسهم وتؤهّلهم لدخول الجنة بعد النجاة من النار. عليها ملائكة قائمون عليها، وهم الخزنة التسعة عشر، غلاظ القلوب والطباع، شداد البطش، لا يخالفون أمره، ويفعلون ما يؤمرون. ويقال لأهل النار: يا أيها الذين كفروا لا تعتذروا اليوم حيث لا ينفع الاعتذار، إنما تُجزون ما كنتم تعملون. ثم النداء الثاني: يا أيها الذين آمنوا توبوا إلى الله توبة عاجلة نصوحاً، لا يعود صاحبها إلى الذنب كما لا يعود اللبن إلى الضرع، يعدهم بتكفير سيئاتهم ويبشّرهم بالجنة: عسى ربكم أن يكفّر عنكم سيئاتكم ويدخلكم جنات تجري من تحتها الأنهار، يوم لا يُخزي الله النبي والذين آمنوا معه بإدخالهم النار، نورهم يسعى بين أيديهم وبأيمانهم وهم يجتازون الصراط، يسألون ربهم أن يُبقي لهم نورهم حتى يجتازوا الصراط، وأن يغفر لهم ذنوبهم، ويتوسّلون إليه بصفة القدرة: إنك على كل شيء قدير.", "h": ["وجوب العناية بالزوجة والأولاد وتربيتهم، وأمرهم بطاعة الله ورسوله، ونهيهم عن ترك ذلك.", "وجوب التوبة الفورية على كل من أذنب من المؤمنين والمؤمنات، وهي الإقلاع من الذنب فوراً، أي تركه والتخلّي عنه، ثم العزم على ألا يعود إليه في صدق، ثم ملازمة الندم والاستغفار، كلما ذكر ذنبه استغفر ربه وندم على فعله، وإن كان الذنب متعلقاً بحق آدمي كأخذ ماله أو ضرب جسمه أو انتهاك عرضه وجب التحلّل منه حتى يعفو ويسامح."], "k": "«قوا أنفسكم وأهليكم ناراً»… أهتم بطعام أهلي ولباسهم؛ فهل أهتم بنجاتهم بالقدر نفسه؟"}, {"lbl": "الآيات ٩ – ١٢", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٩﴾ ضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحٖ وَٱمۡرَأَتَ لُوطٖۖ كَانَتَا تَحۡتَ عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ ٱللَّهِ شَيۡـٔٗا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّـٰخِلِينَ ﴿١٠﴾ وَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿١١﴾ وَمَرۡيَمَ ٱبۡنَتَ عِمۡرَٰنَ ٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَٰنِتِينَ ﴿١٢﴾", "w": [["جاهد الكفار", "بالسيف."], ["والمنافقين", "باللسان."], ["واغلظ عليهم", "اشدد عليهم في الخطاب، ولا تعاملهم باللين."], ["امرأة نوح وامرأة لوط", "ضربهما الله مثلاً للذين كفروا."], ["فخانتاهما", "في الدين، إذ كانتا كافرتين."], ["فلم يُغنيا عنهما من الله شيئاً", "لم يغنِ نوح ولوط عن امرأتيهما من عذاب الله شيئاً وإن قلّ."], ["امرأة فرعون", "آسيا بنت مزاحم، آمنت بموسى."], ["أحصنت فرجها", "حفظته فلم يصل إليه الرجال لا بنكاح ولا زنا."], ["فنفخنا فيه من روحنا", "نفخنا في كُمّ درعها بواسطة جبريل الملقّب بروح القدس."], ["وصدّقت بكلمات ربها", "بولدها عيسى أنه كلمة الله وعبده ورسوله، وبشرائعه وكتبه."]], "m": "يأمر تعالى رسوله ﷺ بعدما ناداه بعنوان النبوة تشريفاً بجهاد الكفار والمنافقين: الكفار بالسيف حتى يسلموا، والمنافقين بالقول الغليظ والعبارة البليغة الحاملة للوعيد والتهديد، واشدد عليهم، ومأواهم جهنم وبئس المصير إذا ماتوا على نفاقهم وكفرهم. ثم ضرب الله مثلاً في عدم انتفاع الكافر بقرابة المؤمن مهما كانت درجة القرابة: امرأة نوح وامرأة لوط، كانتا تحت نبيّين رسولين فخانتاهما في دينهما فكانتا كافرتين؛ فامرأة نوح تفشي سر من يؤمن بزوجها وتخبر به الجبابرة من قومه، وتقول لهم: إن زوجها مجنون، وامرأة لوط كانت تدلّ المجرمين على ضيوف لوط إذا نزلوا عليه، فلم تغنِ عنهما قرابة الزوجية شيئاً، ويوم القيامة يقال لهما: ادخلا النار مع الداخلين. ومثل آخر في عدم تضرّر المؤمن بقرابة الكافر ولو كانت الزوجية: امرأة فرعون آسيا بنت مزاحم، آمنت بموسى، فلما عرف فرعون إيمانها أمر بقتلها، فقالت في مناجاتها: رب ابنِ لي عندك بيتاً في الجنة ونجّني من فرعون وعمله الذي هو الكفر والظلم، ونجّني من القوم الظالمين، فشُدّت يداها ورجلاها لتُلقى عليها صخرة عظيمة إن هي أصرّت على الإيمان، فرفعت بصرها إلى السماء فرأت بيتها في الجنة ففاضت روحها، فوصلت الصخرة إليها بعد أن فاضت روحها، فنجّاها الله من عذاب القتل. ومريم ابنة عمران التي أحصنت فرجها، عطفها على آسيا ليكون المثل مكوّناً من امرأتين مؤمنتين كما كان الأول من امرأتين كافرتين؛ أحصنت فرجها عن الرجال في الوقت الذي عمّ البغاء ديار بني إسرائيل، فأكرمها الله بأن أرسل إليها روحه جبريل ﵇ فنفخ في كُمّ درعها، فسرت النفخة بقدرة الله في جسمها فحملت بعيسى الذي كان بكلمة الله «كن». قال ابن عباس رضي الله عنهما: ما بغت امرأة نبي قط، فالمراد من الخيانة المذكورة الخيانة في الدين وإفشاء الأسرار. وصدّقت بكلمات ربها وكتبه، وكانت من القانتين المطيعين لله المخبتين.", "h": ["وجوب الجهاد في الكفار بالسيف، وفي المنافقين باللسان، وعلى حكّام المسلمين القيام بذلك لأنهم خلفاء النبي ﷺ في أمته.", "تقرير مبدأ: لا تزر وازرة وزر أخرى؛ فالكافر لا ينتفع بالمؤمن يوم القيامة، والمؤمن لا يتضرّر بالكافر ولو كانت القرابة نبوة أو أبوة أو بنوة، فإبراهيم لم يضرّه كفر آزر، ونوح لم يضرّه كفر ابنه، كما أن آزر وابن نوح لم ينفعهما إيمان الأب والابن؛ هذا، وقرابة المؤمن الصالح تنفع المؤمن دون الصالح، لقوله تعالى: «والذين آمنوا واتّبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم»."], "k": "«رب ابنِ لي عندك بيتاً في الجنة»… في قصر فرعون كان همّها بيتاً عند ربها؛ فما همّي أنا؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;